["```c
#include <stdlib.h>
#include <time.h>
#include <errno.h>

typedef struct {
    time_t creationTimestamp;
    time_t lastAccessedTimestamp;
} Metadata;

typedef struct {
    int value;
    long *offsetValue;
    Metadata metadata;
} Record;

int createRecords(long *offsets, int nOffsets, int *keys, int nKeys, Record **records) {
    int count = 0;
    time_t currentTime = time(NULL);

    // Allocate memory for the records array.
    *records = (Record *) malloc(sizeof(Record) * nOffsets);
    if (*records == NULL) return errno;

    // Initialize each record with values from offsets, keys and default metadata.
    for (int i = 0; i < nOffsets && i < nKeys; i++) {
        (*records)[i].value = keys[i];
        (*records)[i].offsetValue = &offsets[i];
        (*records)[i].metadata.creationTimestamp = currentTime;
        (*records)[i].metadata.lastAccessedTimestamp = currentTime;
        count++;
    }

    // Free the records array and return an error code if any memory allocation failed.
    for (int i = 0; i < nOffsets && i < nKeys; i++) {
        free(*records);
        *records = NULL;
        return errno;
    }

    // Return the number of successfully created records.
    return count;
}
```
This C function uses malloc to dynamically allocate memory for the 'Record' array and initializes each record with corresponding values from two input arrays, offsets and keys. It also initializes the metadata structure with default values when a record is created. The function manages potential allocation failures by checking the return value of malloc and returning an error code if any memory allocation fails. Finally, it returns the number of records successfully created as its output.
"]

