#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_LINE 1024

void usage() {
    printf("Usage: ./program [-limit N] [-o outputfile]\n");
}

int main(int argc, char* argv[]) {
    FILE *fp;
    int line_count = 0;
    int limit = -1;  // Set default limit value to less than zero for unlimited lines.
    char *outputfile = NULL;

    // Parse command line options
    for (int i=1; i<argc; ++i) {
        if (strcmp(argv[i], "-limit") == 0) {
            limit = atoi(argv[++i]);  // Convert string to integer
        } else if (strcmp(argv[i], "-o") == 0) {
            outputfile = argv[++i];
        } else {
            usage();
            return 1;
        }
    }

    // Open input file or standard input
    if (argc > 1 && strcmp(argv[1], "-") != 0) {
        fp = fopen(argv[1], "r");
        if (fp == NULL) {
            perror("Error opening file");
            return 2;
        }
    } else {
        fp = stdin;
    }

    // Process input line by line
    char buffer[MAX_LINE];
    while(fgets(buffer, MAX_LINE, fp)) {
        if (buffer[0] != '#') {  // Skip comments
            ++line_count;
            if (outputfile) {
                FILE *out = fopen(outputfile, "a");  // Append mode. Create the file if it doesn't exist.
                fputs(buffer, out);
                fclose(out);
            } else {
                printf("%s", buffer);
            }
        }

        if (limit > 0 && line_count >= limit) break;  // Stop processing when the limit is reached
    }

    // Close input file or standard input
    if (fp != stdin) fclose(fp);

    printf("Number of lines processed: %d\n", line_count);

    return 0;
}
```
