// Function for DNS resolution
int dns_resolution(const char *hostname, u_char *ip) {
    struct hostent *he;
    struct in_addr **addr_list;

    if ((he = gethostbyname(hostname)) == NULL) {
        herror("gethostbyname"); // Print error message
        return 1;
    }

