        strcpy(ip, inet_ntoa(*addr_list[i])); // Copy IP address to u_char array
    }

    return 0;
}

// Function for processing log file lines
void process_line(char *line) {
    char *token = strtok(line, ",");
    double sum = 0.0, count = 0.0;

    while (token != NULL) {
        char *endptr;
        double val = strtod(token, &endptr); // Try to convert token to double

        if (*endptr == '\0') { // If conversion is successful
            sum += val;
            count++;

            if (count > 2) { // Keep only the last two numbers in sum
                sum -= strtod(token, NULL);
            }
        }

        token = strtok(NULL, ",");
    }

    double average = count < 2 ? 0.0 : sum / count; // Calculate and append the average
    char buffer[16];
    sprintf(buffer, ",%.2lf", average);
    strcat(line, buffer);
}

// Main function to read lines from log file
int main() {
    FILE *file = fopen("log.txt", "r"); // Open log file in read mode

    if (file == NULL) {
        perror("Error opening file"); // Print error message
        return 1;
    }

    char *line = NULL;
    size_t len = 0;
    ssize_t read;

    while ((read = getline(&line, &len, file)) != -1) {
        process_line(line); // Process each line from log file
        printf("%s", line);
    }

    free(line); // Free allocated memory for each line
    fclose(file); // Close the file

    return 0;
}
```
