    int *arr = malloc(BUFFER_SIZE * sizeof(int));

    if (arr == NULL){
        perror("Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    while(scanf("%d", &num) == 1 && i < BUFFER_SIZE){
        arr[i++] = num;
    }

    if (i == BUFFER_SIZE){
      perror("Input limit exceeded.\n");
      exit(EXIT_FAILURE);
    }

    *length = i;
    return arr;
