['Here's a basic implementation in C using POSIX semaphores (`sem_t`) and error handling. 

```C
#include <fcntl.h>           /* For O_* constants */
#include <sys/stat.h>        /* For mode constants */
#include <errno.h>           /* For errno */
#include <semaphore.h>       /* For sem_t, sem_open(), and other functions */
#include <stdio.h>           /* For fprintf() */
#include <unistd.h>          /* For close() */
#include <string.h>          /* For strerror() */

sem_t* createSemaphore(const char* name, unsigned int value) {
    sem_t* sem = sem_open(name, O_CREAT | O_EXCL, S_IRUSR | S_IWUSR, value);

    if (sem == SEM_FAILED && errno == EEXIST) {
        fprintf(stderr, "Failed to create semaphore: Semaphore with name %s already exists.\n", name);
        return NULL;
    } else if (sem == SEM_FAILED) {
        fprintf(stderr, "Failed to create semaphore: %s\n", strerror(errno));
        return NULL;
    }

    return sem;
}

int destroySemaphore(const char* name) {
    if (sem_unlink(name) == -1 && errno != ENOENT) {
        fprintf(stderr, "Failed to delete semaphore: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main() {
    const char* name = "/testSem";

    sem_t* sem = createSemaphore(name, 5);
    if (sem == NULL) {
        fprintf(stderr, "Failed to create semaphore.\n");
        return -1;
    }

    // Use the semaphore here.

    if (destroySemaphore(name) != 0) {
        fprintf(stderr, "Failed to delete semaphore.\n");
        return -1;
    }

    return 0;
}
```
This is a basic example and it doesn't include error handling for invalid values. You would need additional code to handle this case depending on your requirements. Similarly, edge cases like concurrent semaphore creation and deletion are not handled in the above example because they might require a locking mechanism or specific synchronization primitives depending upon your use-case.

Remember that POSIX semaphores allow for thread safety out of the box, but the actual usage will depend on the needs of your program (e.g., using `sem_wait()` and `sem_post()` for mutual exclusion). 

