["Here's a basic implementation of the program, using Boost's random number generator library for Mersenne Twister algorithm. Note that C++11 std::random has its own implementation but we use Boost for more control over underlying implementation. This code is just a starting point and may need adjustments according to your specific needs:

```cpp
#include <boost/random/mersenne_twister.hpp>
#include <boost/random/uniform_real_distribution.hpp>
#include <boost/random/normal_distribution.hpp>
#include <ctime>
#include <mutex>

namespace HighFrequencyTrading {
    class RandomNumberGenerator {
        public:
            enum DistributionType {
                UNIFORM,
                NORMAL
            };

            static std::mutex mtx;  // protects the generator and seed across threads
            static boost::random::mt19937 gen;  // Mersenne Twister engine used for random number generation
            static unsigned long seed;  // Current seed value

            RandomNumberGenerator(DistributionType type, double param1 = 0.0, double param2 = 1.0) {
                std::lock_guard<std::mutex> lock(mtx);  // lock mutex for thread safety

                if (seed == 0) {  // if seed is not set, use system time as seed
                    seed = static_cast<unsigned long>(std::time(nullptr));
                    gen.seed(seed);
                }

                switch (type) {
                    case UNIFORM:
                        distributionUniform = new boost::random::uniform_real_distribution<>(param1, param2);
                        break;
                    case NORMAL:
                        distributionNormal = new boost::random::normal_distribution<>(param1, param2);
                        break;
                }
            }

            ~RandomNumberGenerator() {
                std::lock_guard<std::mutex> lock(mtx);  // lock mutex for thread safety

                if (distributionUniform) delete distributionUniform;
                if (distributionNormal) delete distributionNormal;
            }

            double getRandomNumber() {
                std::lock_guard<std::mutex> lock(mtx);  // lock mutex for thread safety

                if (distributionUniform != nullptr) return (*distributionUniform)(gen);
                if (distributionNormal != nullptr) return (*distributionNormal)(gen);
            }

        private:
            boost::random::uniform_real_distribution<>* distributionUniform = nullptr;
            boost::random::normal_distribution<>* distributionNormal = nullptr;
    };

    std::mutex RandomNumberGenerator::mtx;  // initialize mutex
    boost::random::mt19937 RandomNumberGenerator::gen(static_cast<unsigned long>(std::time(nullptr)));  // initialize engine with system time seed
    unsigned long RandomNumberGenerator::seed = 0;  // initialize seed to 0, indicating unset status
}
```

