using Newtonsoft.Json;
using RestSharp;

public abstract class PhysicsEngine
{
    public abstract void Update(float deltaTime);
}

public class NewtonsLawEngine : PhysicsEngine
{
    // Simulate physics with Newton's Law of Motion
    public override void Update(float deltaTime) { }
}

public class SpecialRelativityEngine : PhysicsEngine
{
    // Simulate physics with Einstein's Theory of Relativity
    public override void Update(float deltaTime) { }
}

public class ParticleSystem
{
    private List<Particle> particles = new List<Particle>();
    private PhysicsEngine engine;
    private RemoteConfig config;
    private float simSpeed = 1f; // default speed is 1x

    public void Initialize(int particleCount, PhysicsEngine engine)
    {
        this.engine = engine;

        for (int i = 0; i < particleCount; ++i)
            particles.Add(new Particle());
    }

    // Dynamically load configuration from remote endpoint on separate thread
    public void LoadConfig()
    {
        ThreadPool.QueueUserWorkItem(_ =>
        {
            var client = new RestClient("https://api.example.com/config");
            var request = new RestRequest(Method.GET);
            var response = client.Execute<RemoteConfig>(request);

            config = JsonConvert.DeserializeObject<RemoteConfig>(response.Content);
        });
    }

    // Switch physics engine at runtime safely
    public void SetPhysicsEngine(PhysicsEngine engine) => this.engine = engine;

    // Adjust simulation speed dynamically
    public void SetSimulationSpeed(float speed) => simSpeed = speed;

    // Update positions in real-time without race conditions
    public void Update()
    {
        foreach (var particle in particles)
            lock (particle)
                engine.Update(Time.deltaTime * simSpeed);
    }
}
```
