['```python
from flask import Flask, request, jsonify
from werkzeug.exceptions import BadRequest
from functools import wraps
import time
import logging
from authentication_service import verify_user
from database_service import DatabaseService
from logging_service import log
from cachetools import cached, TTLCache

app = Flask(__name__)
cache = TTLCache(maxsize=100, ttl=300)  # Adjust maxsize and ttl as needed
db = DatabaseService()
rate_limit = 100  # Set your rate limit
window = 60  # Window for the rate limiting (seconds)
requests = {}

def validate(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        # Verify user permissions
        if not verify_user():
            return jsonify({"message": "Unauthorized"}), 401
        # Check request body
        data = request.get_json()
        if not data:
            return jsonify({"message": "Bad request"}), 400
        return f(data, *args, **kwargs)
    return decorated_function

def limit_rate(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        ip = request.remote_addr
        if ip not in requests:
            requests[ip] = [time.time(), 1]
        else:
            while requests[ip][0] <= time.time() - window:
                requests[ip].pop(0)
            if len(requests[ip]) >= rate_limit:
                return jsonify({"message": "Rate limit exceeded"}), 429
            else:
                requests[ip][1] += 1
        return f(*args, **kwargs)
    return decorated_function

@app.route('/resources/<resource_id>', methods=['PUT'])
@limit_rate
@validate
def update_resource(data, resource_id):
    # Check if resource exists and is not soft deleted
    db_result = db.get('SELECT * FROM resources WHERE id = %s AND deleted = 0' % (resource_id))
    if not db_result:
        return jsonify({"message": "Resource not found or already deleted"}), 404

    # Optimistic locking check
    if data.get('version') != db_result[0].get('version'):
        return jsonify({"message": "Resource out of date, please refresh and try again"}), 409

    # Update resource in database
    new_data = {k: v for k, v in data.items() if k != 'id'}
    new_version = db_result[0]['version'] + 1
    db.execute('UPDATE resources SET version = %s, %s WHERE id = %s' % (new_version, ', '.join(['%s = %s' % (k, v) for k, v in new_data.items()]), resource_id))

    # Log API call
    log('PUT', resource_id)

    return jsonify({"message": "Resource updated", "resource_id": resource_id}), 200

@app.route('/resources/<resource_id>', methods=['DELETE'])
@limit_rate
def delete_resource(resource_id):
    # Check if resource exists and is not soft deleted
    db_result = db.get('SELECT * FROM resources WHERE id = %s AND deleted = 0' % (resource_id))
    if not db_result:
        return jsonify({"message": "Resource not found or already deleted"}), 404

    # Soft delete the resource
    db.execute('UPDATE resources SET deleted = 1 WHERE id = %s' % (resource_id))

    # Log API call
    log('DELETE', resource_id)

    return jsonify({"message": "Resource soft-deleted", "resource_id": resource_id}), 200
```
']

