```csharp
using System;
using System.IO;
using System.Xml.XPath;
using System.Security.AccessControl;
using System.Security.Principal;

public void ParseAndSetLoggingDirectory(string xmlConfig, string envVariableName)
{
    try
    {
        var doc = new XPathDocument(new StringReader(xmlConfig));
        var navigator = doc.CreateNavigator();

        // Assuming that the logging directory path is in an element named "loggingDirectory". 
        string dirElementValue = (string)navigator.Evaluate("//loggingDirectory");

        if (dirElementValue == null)
            throw new Exception("No 'loggingDirectory' element found in XML document.");

        var directoryInfo = Directory.CreateDirectory(Environment.ExpandEnvironmentVariables(dirElementValue));

        if (!string.IsNullOrEmpty(directoryInfo?.FullName))
        {
            Environment.SetEnvironmentVariable(envVariableName, directoryInfo.FullName);
            Console.WriteLine("Logging Directory set to: " + directoryInfo.FullName);
        }
        else
        {
            var existingDir = Environment.GetEnvironmentVariable(envVariableName);
            if (string.IsNullOrEmpty(existingDir))
                throw new Exception("Failed to create or get logging directory.");

            Console.WriteLine("Logging Directory already set: " + existingDir);
        }
    }
    catch (Exception ex)
    {
        // Log the exception and rethrow it for upstream handling.
        Console.Error.WriteLine(ex.Message);
        throw;
    }
}
```
This code reads an XML configuration string, parses it using XPath, retrieves a specified element value (loggingDirectory in this case), creates a directory with the given path and environment variable, and sets the environment variable to its path if creation is successful. If there's already an existing environment variable set, the function uses that instead of creating a new one. The code also includes error handling for potential issues such as invalid XML format or missing elements.
']

