```java
import org.apache.commons.codec.digest.DigestUtils;
import java.security.MessageDigest;
import java.util.logging.Level;
import java.util.logging.Logger;
import javax.xml.bind.DatatypeConverter;
import java.nio.charset.StandardCharsets;
import java.lang.String;

public class InvalidInputException extends RuntimeException {
    public InvalidInputException(String message) {
        super(message);
    }
}

public final class HashUtil {

    private static final Logger LOGGER = Logger.getLogger(HashUtil.class.getName());
    private static Level level = Level.INFO; // default logging level, configurable via setLogLevel method

    public static String md5(String input) throws InvalidInputException {
        if (input == null || input.isEmpty()) {
            LOGGER.log(level, "Invalid input provided");
            throw new InvalidInputException("Provided string is null or empty");
        } else {
            try {
                MessageDigest md = MessageDigest.getInstance("MD5");
                byte[] digest = md.digest(input.getBytes(StandardCharsets.UTF_8));
                String myHash = DatatypeConverter.printHexBinary(digest);
                return myHash;
            } catch (Exception e) {
                LOGGER.log(level, "Unexpected error", e);
                throw new InvalidInputException("An unexpected error occurred");
            }
        }
    }

    public static void setLogLevel(String logLevel) {
        switch(logLevel) {
            case "SEVERE": level = Level.SEVERE; break;
            case "WARNING": level = Level.WARNING; break;
            case "INFO": level = Level.INFO; break;
            case "CONFIG": level = Level.CONFIG; break;
            case "FINE": level = Level.FINE; break;
            case "FINER": level = Level.FINER; break;
            case "FINEST": level = Level.FINEST; break;
        }
    }
}
```
The `HashUtil` class is designed in such a way that it can be easily extended or configured without affecting other components. The logger instance and logging level are encapsulated within the `HashUtil` class, meaning they can be changed on a global scale across all instances of `HashUtil`.

