const fs = require('fs');
const path = require('path');
const fetch = require('node-fetch');
const logger = require('./logger'); // This needs to be replaced with your actual logger library

async function getDirectoryFiles(dir, metadataServiceUrl) {
  let filesWithMetadata = [];
  try {
    const fileNames = await fs.promises.readdir(dir);
    for (const fileName of fileNames) {
      const filePath = path.join(dir, fileName);
      const stats = await fs.promises.stat(filePath); // This is an async call to get the stats of a file

      if (stats.isFile()) {
        let metadata;
        try {
          const response = await fetch(metadataServiceUrl + '/' + encodeURIComponent(fileName));
          metadata = await response.json();
        } catch (error) {
          logger.error('Error fetching metadata for file: ' + fileName, error);
        }

        filesWithMetadata.push({
          name: fileName,
          lastModified: stats.mtimeMs, // mtimeMs is a timestamp in ms since epoch
          metadata
        });
      } else if (stats.isDirectory()) {
        logger.warn('Skipping directory: ' + filePath);
      }
    }
  } catch (error) {
    logger.error('Error reading directory: ' + dir, error);
  }

  return filesWithMetadata;
}
```
