#include <forward_list>
#include <string>

void insertAfter(std::forward_list<std::string>& list, const std::string& target, const std::string& toInsert) {
    auto pos = list.begin();
    while (pos != list.end()) {
        if (*pos == target) {
            // Insert after the found element and exit the loop
            list.insert_after(pos, toInsert);
            break;
        }
        ++pos;
    }

    if (pos == list.end()) {
        // Target not found: insert at the end
        list.insert_after(list.before_begin(), toInsert);
    }
}
