        if (window.getComputedStyle(element).display !== 'none' && window.getComputedStyle(element).visibility !== 'hidden') {
            let matchCount = 0;

            for (let attribute in attributeMap) {
                const values = attributeMap[attribute];

                if (values.includes($(element).attr(attribute))) {
                    matchCount++;
                }
            }

            if (matchCount === Object.keys(attributeMap).length) {
                result.push(element);
            }
        }
    });

    $.ajax({
        url: metadataUrl,
        type: 'GET',
        success: function(response) {
            // Update filtering criteria dynamically based on response from the external data source
            // Here you can modify the attributeMap or maxDepth based on the received response.
        },
        error: function() {
            console.log("Failed to fetch metadata.");
        }
    });

    if (maxDepth > 1) {
        $(result).find('*').each((index, element) => {
            result.push(element);
        });

        maxDepth--;
        findElementsWithAttributes(selector, attributeMap, maxDepth, metadataUrl); // Recursive call
    }

    return result;
}
```
