            } catch (IOException e) {
                Log.e(TAG, "Failed to create cache directory: " + e);
            }
        }
    }

    public void setBitmap(Bitmap bitmap) {
        if (bitmap != null && !bitmap.isRecycled()) {
            bitmap.recycle();
            Log.d(TAG, "Recycling and setting Bitmap to null");
            bitmap = null;
        }
    }

    public void setDefaultThemeDirectory() {
        String defaultDirPath = cacheRootDir + "/default";
        File defaultDir = new File(defaultDirPath);
