```c
#include <stdio.h>
#include <string.h>
#include <sys/types.h>
#include <sys/socket.h>
#include <netdb.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <errno.h>

int get_ip(char *hostname, u_char *ip) {
    struct addrinfo hints, *res;
    int errcode;
    char addrstr[100];
    void *ptr;

    memset (&hints, 0, sizeof (hints));
    hints.ai_family = PF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_flags |= AI_CANONNAME;

    errcode = getaddrinfo (hostname, NULL, &hints, &res);
    if (errcode != 0) {
        perror ("getaddrinfo");
        return -1;
    }

    printf ("Host: %s\n", hostname);
    while (res) {
        inet_ntop (res->ai_family, res->ai_addr->sa_data, addrstr, 100);

        switch (res->ai_family) {
            case AF_INET:
                ptr = &((struct sockaddr_in *) res->ai_addr)->sin_addr;
                inet_ntop (res->ai_family, ptr, ip, 16); // Assuming IPV4
                break;
            case AF_INET6:
                ptr = &((struct sockaddr_in6 *) res->ai_addr)->sin6_addr;
                inet_ntop (res->ai_family, ptr, ip, 16); // Assuming IPV6
                break;
            default:
                return -1;
        }

        printf ("IPv%d address: %s (%s)\n", res->ai_family == PF_INET6 ? 6 : 4, ip, addrstr);
        res = res->ai_next;
    }

    return 0;
}
```
