} SensorData;

// Create an array of sensor data
SensorData *sensorDatas[3];
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

double calculateMovingAverage(int sensorIndex) {
    pthread_mutex_lock(&lock);
    double sum = 0.0;
    int count = 0;

    for (int i = sensorDatas[sensorIndex]->count - 1; i >= 0 && i > sensorDatas[sensorIndex]->count - MAX_DATAPOINTS; --i) {
        sum += sensorDatas[sensorIndex][i].temperature;
        ++count;
    }

    pthread_mutex_unlock(&lock);
    return count > 0 ? sum / count : 0.0;
}

double getMaxMovingAverage() {
    double maxAvgTemp = 0.0;
    for (int i = 0; i < 3; ++i) {
        double movingAverage = calculateMovingAverage(i);
        if (movingAverage > maxAvgTemp) {
            maxAvgTemp = movingAverage;
        }
    }

    return maxAvgTemp;
}

void *processSensorData(void *arg) {
