['To solve this task, we need to use C++ standard library `<random>` for generating random numbers, `<thread>` for managing threads and `<chrono>` for time manipulation. 
The shared data structures are managed using a mutex to ensure thread safety.
Here is the code:

```cpp
#include <iostream>
#include <random>
#include <map>
#include <mutex>
#include <thread>
#include <chrono>

class GameCharacter {
public:
    void selectAttack() {
        std::lock_guard<std::mutex> guard(attacksMutex);  // Lock the mutex.

        auto currentTime = std::chrono::high_resolution_clock::now();
        if (lastUsed != -1 && std::chrono::duration_cast<std::chrono::seconds>(currentTime - lastSelected).count() < 9) {
            // If the cooldown hasn't passed, use the other attack.
            int alternateAttack = 3 - lastUsed;
            attacks[alternateAttack]++;  // Increase usage count for the selected attack.

            std::cout << "Attack: " << alternateAttack << std::endl;
        } else {
            // Randomly select an attack and update the last used attack.
            std::random_device rd;
            std::mt19937 gen(rd());
            std::uniform_int_distribution<> dis(1, 2);

            int selectedAttack = dis(gen);
            while (selectedAttack == lastUsed) {
                // Ensure the selected attack is not the same as the previous one.
                selectedAttack = dis(gen);
            }

            attacks[selectedAttack]++;  // Increase usage count for the selected attack.
            lastSelected = currentTime;
            lastUsed = selectedAttack;

            std::cout << "Attack: " << selectedAttack << std::endl;
        }
    }

private:
    std::map<int, int> attacks{{1, 0}, {2, 0}};  // Map to track usage of each attack.
    int lastUsed = -1;  // Last used attack number (-1 for not used yet).
    std::chrono::time_point<std::chrono::high_resolution_clock> lastSelected;  // Time point of the last attack selection.
    std::mutex attacksMutex;  // Mutex to protect shared data structures.
};
```
In this code, each instance of `GameCharacter` has its own map (attacks) to track usage of each attack. The selected attack is stored in lastUsed and the time point of selection is stored in lastSelected for calculation of cooldown. 
When a new attack needs to be selected, we lock the mutex to ensure thread-safe access to shared data structures, then check if there is any remaining cooldown period from the previous attack (if not used previously or enough time has passed), otherwise, it selects an attack randomly and updates lastUsed and lastSelected.
']

