```c
#include <stdlib.h>
#include <string.h>

// Function to modify filenames based on heuristics
void modify_filename(char *filename) {
    char *ext = strrchr(filename, '.'); // find last occurrence of '.'
    if (ext == NULL) {
        ext = filename + strlen(filename); // If no extension found, set at the end
    }

    size_t len = 0;
    char *p = ext + 1; 
    while (*p && len < 255 - strlen(filename)) { // Calculate number of digits and append it to filename
        if (isdigit(*p)) ++len;
        ++p;
    }

    size_t new_len = ext + len - filename + 1; // New length with added ".digits"

    char *new_filename = malloc(new_len + 1); // Allocate memory for new filename
    if (new_filename == NULL) return; // Handle allocation error, can be improved

    strncpy(new_filename, filename, ext - filename); // Copy first part of old name to new name
    new_filename[ext - filename] = '\0'; // Terminate string at extension start

    char *type_start;
    while ((type_start = strrchr(new_filename, '.')) != NULL) { // Check for other extensions and remove them
        if (strlen(++type_start) >= 3 && isdigit(*type_start)) break; // If extension has digits before '.' it's not a file type
    }

    sprintf(new_filename + strlen(new_filename), ".%zu.txt", len); // Append ".digits.filetype" to new name

    strcpy(filename, new_filename); // Update original filename
    free(new_filename); // Free allocated memory
}
```
This function doesn't follow any specific heuristic to determine the number of digits. It simply counts the number of digits in the last extension. 

In a real-world situation, this approach might require adjustments according to your needs and resources. You might need to apply more sophisticated algorithms or use predefined rules to decide how many digits should be added based on the file content or other factors.
']

