['```c
#include <stdio.h>
#include <string.h>
#include <regex.h>
#include <json-c/json.h>

int validate_token(const char *input) {
    json_object *jobj = json_tokener_parse(input);

    if (jobj == NULL) return 0;

    json_object *access_token, *expires_in, *token_type, *refresh_token;

    json_bool access_token_exists = json_object_object_get_ex(jobj, "access_token", &access_token);
    if (!access_token_exists) return 0;

    const char *access_token_str = json_object_get_string(access_token);
    regex_t regexCompiled;
    regcomp(&regexCompiled, "^[a-zA-Z0-9@#$]{1,}$", REG_EXTENDED|REG_NOSUB);
    if (regexec(&regexCompiled, access_token_str, 0, NULL, 0) != 0) return 0;

    json_bool expires_in_exists = json_object_object_get_ex(jobj, "expires_in", &expires_in);
    if (!expires_in_exists) return 0;

    int64_t expires_in_int = json_object_get_int64(expires_in);
    if (expires_in_int < 1) return 0;

    json_bool token_type_exists = json_object_object_get_ex(jobj, "token_type", &token_type);
    if (!token_type_exists) return 0;

    const char *token_type_str = json_object_get_string(token_type);
    if (strcmp("Bearer", token_type_str)) return 0;

    json_bool refresh_token_exists = json_object_object_get_ex(jobj, "refresh_token", &refresh_token);

    regfree(&regexCompiled);

    if (access_token_exists && expires_in_int > 0 && token_type_str != NULL) {
        json_object_put(jobj);
        return 1;
    } else {
        json_object_put(jobj);
        return 0;
    }
}
```
Note: This code uses the json-c library, which is not a standard library. You'll need to install it before you can compile and run this code. To do that, use your package manager to install libjson-c-dev or similar package name depending on your system. Also make sure to link -ljson-c when compiling with gcc.
