    public string ModifyFilename(string filename, int digitsCount, string fileType)
    {
        if (filename == null || filename.Length > 255)
        {
            logger.Error("Invalid filename: " + filename);
            throw new ArgumentException("Invalid filename");
        }

        var splitFilename = Regex.Split(filename, @"\.(?=[^.]*$)", RegexOptions.None); // Split on last '.' character only

        if (splitFilename.Length < 2)
