['Below is the C# code for this task using Triple DES encryption algorithm and validating key & IV lengths. This function also throws ArgumentException in case of incorrect length of keys or null inputs and handles network delays/service unavailability by throwing `CryptographicException`, which should be caught and handled at higher levels:

```csharp
using System;
using System.Text;
using System.Security.Cryptography;

public string DecryptMessage(string base64EncodedMessage, string keyHex, string ivHex)
{
    if (string.IsNullOrEmpty(base64EncodedMessage) || string.IsNullOrEmpty(keyHex) || string.IsNullOrEmpty(ivHex))
        throw new ArgumentException("Input parameters cannot be null or empty");

    if (keyHex.Length != 48 || ivHex.Length != 24)  // Triple DES key and IV lengths are 16 bytes each (hence 48 hex chars and 24 hex chars respectively).
        throw new ArgumentException("Incorrect key or initialization vector length");

    byte[] encryptedData = Convert.FromBase64String(base64EncodedMessage);
    byte[] keyBytes = StringToByteArray(keyHex);
    byte[] ivBytes = StringToByteArray(ivHex);

    using (TripleDES desAlg = TripleDES.Create())  // Create a Triple DES object to perform encryption/decryption.
    {
        desAlg.Key = keyBytes;
        desAlg.IV = ivBytes;

        ICryptoTransform decryptor = desAlg.CreateDecryptor(desAlg.Key, desAlg.IV);  // Create a decryptor to perform the actual decryption.

        byte[] decryptedData = null;
        try
        {
            decryptedData = decryptor.TransformFinalBlock(encryptedData, 0, encryptedData.Length);  // Attempt to decrypt data.
        }
        catch (CryptographicException e) 
        {
             throw new CryptographicException("Decryption failed due to invalid padding", e);  
            // If the exception is thrown by the cryptographic transformation, it's likely due to invalid padding and should be handled accordingly.
        }

        return Encoding.UTF8.GetString(decryptedData);  // Return decrypted data as a string (assuming original message was UTF-8 encoded).
    }
}

private byte[] StringToByteArray(string hex) 
{
    int NumberChars = hex.Length;
    byte[] bytes = new byte[NumberChars / 2];
    for (int i = 0; i < NumberChars; i += 2)
        bytes[i / 2] = Convert.ToByte(hex.Substring(i, 2), 16);
    return bytes;
}
```
