['Here is a basic implementation of your request. This solution uses parallelism to improve I/O efficiency, exception handling to prevent crashes, and dependency injection for testability. It also handles varying network conditions by attempting the operation multiple times before failing, with exponential backoff between attempts to avoid overloading the service. 

```csharp
using System;
using System.Collections.Generic;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class FileMetadataService
{
    private readonly IFileSystem _fileSystem;

    public FileMetadataService(IFileSystem fileSystem)
    {
        _fileSystem = fileSystem;
    }

    public async Task<Dictionary<string, FileMetadata>> CalculateFileHashesAsync(List<string> filePaths)
    {
        var tasks = new List<Task<FileMetadata>>();

        foreach (var path in filePaths)
        {
            tasks.Add(_fileSystem.GetFileMetadataAsync(path));
        }

        await Task.WhenAll(tasks);

        return tasks.ToDictionary(task => task.Result.FileName, task => task.Result);
    }
}

public class FileMetadata
{
    public string FileName  { get; set; }
    public string Sha256Hash  { get; set; }
    public DateTime LastModified  { get; set; }
    public long SizeInBytes  { get; set; }
}

public interface IFileSystem
{
    Task<FileMetadata> GetFileMetadataAsync(string path);
}

public class FileSystem : IFileSystem
{
    private const int MaxRetries = 5;

    public async Task<FileMetadata> GetFileMetadataAsync(string path)
    {
        var retries = MaxRetries;

        while (retries-- > 0)
        {
            try
            {
                using var stream = new FileStream(path, FileMode.Open);

                var fileInfo = new FileInfo(path);
                var buffer = new byte[4096]; // Adjust this value as necessary to balance between memory usage and performance
                var sha256 = SHA256.Create();
                int read;

                while ((read = await stream.ReadAsync(buffer, 0, buffer.Length)) > 0)
                {
                    sha256.TransformBlock(buffer, 0, read, buffer, 0);
                }

                return new FileMetadata
                {
                    FileName = Path.GetFileName(path),
                    Sha256Hash = Convert.ToBase64String(sha256.Hash),
                    LastModified = fileInfo.LastWriteTimeUtc,
                    SizeInBytes = fileInfo.Length
                };
            }
            catch (IOException) when (retries > 0) // Retry on IOExceptions like network unavailability
            {
                await Task.Delay((MaxRetries - retries + 1) * 1000); // Exponential backoff
            }
        }

        throw new IOException($"Could not read file after {MaxRetries} attempts: {path}");
    }
}
```
This code assumes that you are running on an environment where `async`/`await` is available. If you're targeting an older .NET Framework version, please replace the async/await syntax with equivalent Task-based patterns (for example, continuations or callbacks). 

Please note: Error handling and retry strategies are not free and should be used judiciously, as they can add complexity to your code without adding significant value if you have a very reliable network. Also, it's better to handle exceptions at a higher level where possible, rather than retrying after every single operation.
']

['Here's a code snippet in C# which includes logging using NLog framework, async tasks for efficiency, error handling and verification against checksum before returning data:

```Csharp
using System;
using System.IO;
using System.Security.Cryptography;
using System.Threading.Tasks;
using NLog;

public static class CipherDecryptionUtilities
{
    private static readonly Logger logger = LogManager.GetCurrentClassLogger();

    public static async Task<byte[]> DecryptAesCbcAsync(byte[] ciphertext, byte[] key, byte[] iv, byte[] checksum)
    {
        if (key == null || key.Length != 32)
            throw new ArgumentException("Key must be 32 bytes.", nameof(key));

        if (iv == null || iv.Length != 16)
            throw new ArgumentException("IV must be 16 bytes.", nameof(iv));

        byte[] plaintext = null;

        using (Aes aesAlg = Aes.Create())
        {
            aesAlg.Key = key;
            aesAlg.IV = iv;
            aesAlg.Mode = CipherMode.CBC;
            aesAlg.Padding = PaddingMode.PKCS7;

            ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

            using (MemoryStream msDecrypt = new MemoryStream())
            {
                await Task.Run(() =>
                {
                    try
                    {
                        using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Write))
                        {
                            csDecrypt.Write(ciphertext, 0, ciphertext.Length);
                            csDecrypt.Close();
                        }
                    }
                    catch (Exception ex)
                    {
                        logger.Error(ex, "An error occurred during decryption.");
                    }
                });

                plaintext = msDecrypt.ToArray();
            }
        }

        if (!VerifyChecksum(plaintext, checksum))
        {
            logger.Warn("Decrypted data does not match provided checksum. Returned data may be corrupted.");
        }

        return plaintext;
    }

    private static bool VerifyChecksum(byte[] data, byte[] checksum)
    {
        // This method will vary based on the checksum algorithm being used. 
        // For simplicity, let's assume it's just a simple checksum (XOR of all bytes).

        int calculatedCheckSum = 0;
        foreach(byte b in data) 
            calculatedCheckSum ^= b;

        return BitConverter.GetBytes(calculatedCheckSum) == checksum;
    }
}
```
This code will decrypt given ciphertext using AES-CBC algorithm and then it will verify the plaintext against provided checksum. It uses async/await pattern to perform decryption in separate task without blocking main thread which is crucial for handling large files efficiently. Logging errors or exceptions that occur during the decryption process. 

You need to install `NLog` via NuGet package manager to use it:
```
Install-Package NLog -Version 4.7.0
```
']

