['```rust
use std::fs;
use std::io::ErrorKind;
use std::os::unix::fs::PermissionsExt;
use std::sync::{Arc, Mutex};
use std::thread;
use log::*;

fn create_directories_and_subdirs(name: &str, subdir_names: &[&str], log_file_path: Option<&str>) -> Result<(), Box<dyn std::error::Error>> {
    let dir_path = format!["/path/to/{}", name];
    let mutex_dir_path = Arc::new(Mutex::new(dir_path));
    init_logger(log_file_path);

    // Create main directory
    match fs::create_dir(&dir_path) {
        Ok(_) => info_log("Created main directory", &mutex_dir_path),
        Err(e) if e.kind() == ErrorKind::AlreadyExists => 
            info_log("Main directory already exists", &mutex_dir_path),
        Err(e) => return Err(Box::new(e)),
    };

    // Create subdirectories
    for dir in subdir_names {
        let subdir = format!["/path/to/{}/{}", name, dir];
        match fs::create_dir(&subdir) {
            Ok(_) => info_log(&format![ "Created subdirectory {}", dir], &mutex_dir_path),
            Err(e) if e.kind() == ErrorKind::AlreadyExists => 
                info_log(&format![ "Subdirectory {} already exists", dir], &mutex_dir_path),
            Err(e) => return Err(Box::new(e)),
        }
    };

    // Set environment variable
    if let Ok(_) = std::env::var("DIRECTORY") {
        info_log("Environment variable already set", &mutex_dir_path);
    } else {
        match std::env::set_var("DIRECTORY", dir_path.clone()) {
            Ok(_) => info_log("Set environment variable", &mutex_dir_path),
            Err(e) => return Err(Box::new(e)),
        };
    };

    Ok(())
}

fn init_logger(log_file_path: Option<&str>) {
    let log_path = match log_file_path {
        Some(path) => path,
        None => "app.log",
    };

    simple_logger::init_with_level(log_path.to_owned(), LevelFilter::Info).unwrap();
}

fn info_log<T: std::fmt::Display>(message: T, path: &Arc<Mutex<String>>) {
    let mut lock = path.lock().unwrap();
    info![&format![ "{}: {}", *lock, message];
}
```
