        perror ("Error opening file");
        return NULL;
    }

    pthread_mutex_lock(&key_lock); // Lock for thread safety

    EVP_CIPHER *cipher = NULL;
    size_t mapSize = sizeof(cipherMap) / sizeof(CipherMapEntry);

    for (size_t i = 0; i < mapSize; ++i) {
        if (strcmp(name, cipherMap[i].cipherName) == 0) {
            cipher = cipherMap[i].getCipherFunc(); // Get the function and call it to get the EVP_CIPHER structure
            break;
        }
