Java Code:
```java
import java.util.HashSet;

class UnionFind {
    int[] parent;
    int[] rank;

    public UnionFind(int size) {
        parent = new int[size];
        rank = new int[size];

        for (int i = 0; i < size; i++) {
            parent[i] = i;
        }
    }

    public int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    public void union(int x, int y) {
        int x_set = find(x), y_set = find(y);
        if (x_set == y_set) {
            return;
        }

        if (rank[x_set] < rank[y_set]) {
            parent[x_set] = y_set;
        } else if (rank[x_set] > rank[y_set]) {
            parent[y_set] = x_set;
        } else {
            parent[y_set] = x_set;
            rank[x_set]++;
        }
    }
}

public class Main {
    public static void main(String[] args) {
        int n = 5; // Size of array
        Integer arr[] = new Integer[n];  // Assume this is the input
        for (int i=0;i<n;++i)
            arr[i] = i+1;

        long startTime = System.currentTimeMillis();
        UnionFind uf = new UnionFind(2*n + 1);
        int disjointPairs = 0;
        for (int i=0; i<n/2; ++i) {
            uf.union(arr[i], arr[n-i-1]);
            if (!uf.find(arr[i]).equals(uf.find(arr[i+1]))) {
                ++disjointPairs;
                System.out.println("Disjoint pair found: " + arr[i] + ", " + arr[n - i - 1]);
            }
        }

        long endTime = System.currentTimeMillis();
        System.out.println("Number of milliseconds taken to perform the check for each pair: "+(endTime-startTime));
    }
}
```
