    int value;
    Metadata metadata;
} Record;

int createAndSortRecords(Arrays *arrays, long rangeStart, long rangeEnd) {
    if (rangeStart > rangeEnd || arrays == NULL){
        return -1; // Invalid arguments or null pointer.
    }

    srand(time(0));  // Initialize random seed
    long size = rangeEnd - rangeStart + 1;
    arrays->offset = malloc(sizeof(long) * size);
    arrays->key = malloc(sizeof(int) * size);
    arrays->recordArray = malloc(sizeof(Record) * size);

    if (arrays->offset == NULL || arrays->key == NULL || arrays->recordArray == NULL){
        free(arrays->offset);
        free(arrays->key);
        free(arrays->recordArray);
        return -1; // Memory allocation failed.
    }

    for (long i = 0; i < size; ++i) {
        arrays->offset[i] = rangeStart + i;
        arrays->key[i] = rand() % 1000;  // Generate a random int value between 0 and 999.

        Record newRecord;
        newRecord.value = arrays->key[i];
        time(&newRecord.metadata.creationTimestamp);
        newRecord.metadata.lastAccessedTimestamp = 0; // Initialize with default values for timestamps.

        arrays->recordArray[i] = newRecord;  // Store record in array.
    }

    qsort(arrays->recordArray, size, sizeof(Record), compareRecords);  // Sort records based on value field.

    return size; // Return count of successfully created records.
}

int compareRecords (const void * a, const void * b){
   Record* recordA = (Record *)a;
   Record* recordB = (Record *)b;

   return (recordA->value - recordB->value);
}
