void find_largest(int* arr, size_t n) {
    if (n == 0) {
        printf("No elements in the array.\n");
        return;
    }

    int max = arr[0];
    for (size_t i = 1; i < n; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    printf("The largest integer is: %d\n", max);
}

int main() {
    srand(time(0));  // For random number generation

    size_t n;
