        return EXIT_FAILURE;
    }

    int* arr = calloc(n, sizeof(*arr));  // Allocate and initialize to zero
    long* offsets = calloc(n, sizeof(*offsets));  // Allocate and initialize to zero
    int* keys = calloc(n, sizeof(*keys));  // Allocate and initialize to zero

    if (arr == NULL || offsets == NULL || keys == NULL) {
        fprintf(stderr, "Failed to allocate memory\n");
        return EXIT_FAILURE;
    }

    printf("Enter %zu integers:\n", n);
    for (size_t i = 0; i < n; ++i) {
        if (scanf("%d", &arr[i]) != 1) {
            fprintf(stderr, "Invalid input\n");
            return EXIT_FAILURE;
        }
    }

    find_largest(arr, n);  // Find and print the largest integer in the array

    Record* records = calloc(n, sizeof(*records));  // Allocate and initialize to zero
    if (records == NULL) {
        fprintf(stderr, "Failed to allocate memory\n");
        return EXIT_FAILURE;
    }

    int range = 100;  // You can adjust this range as needed
    for (size_t i = 0; i < n; ++i) {
