int parse_args(int argc, char** argv, long* size1, long* size2, long* size3, int* lower, int* upper) {
    if (argc != 6) return 0; // incorrect number of arguments

    *size1 = strtol(argv[1], NULL, 10);
    *size2 = strtol(argv[2], NULL, 10);
    *size3 = strtol(argv[3], NULL, 10);

    if (*size1 <= 0 || *size2 <= 0 || *size3 <= 0) return 0; // invalid array size

