```c
#include <openssl/evp.h>
#include <semaphore.h>
#include <stdio.h>

EVP_CIPHER* getAESCipher(int keySize, const EVP_CIPHER **mode) {
    EVP_CIPHER *cipher;
    if (keySize == 128) 
        cipher = EVP_aes_128_ecb();
    else if (keySize == 256)
        cipher = EVP_aes_256_ecb();

    // other modes available in openssl
    *mode = EVP_aes_128_cbc(); 
    return cipher;
}

void encryptAES(unsigned char* plaintext, int plaintextLength, unsigned char* key, unsigned char* iv, unsigned char* ciphertext) {
    EVP_CIPHER_CTX *ctx;

    ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_128_ecb(), NULL, key, iv);

    int len;
    EVP_EncryptUpdate(ctx, ciphertext, &len, plaintext, plaintextLength);
    EVP_EncryptFinal_ex(ctx, ciphertext + len, &len);

    EVP_CIPHER_CTX_free(ctx);
}

void decryptAES(unsigned char* ciphertext, int ciphertextLength, unsigned char* key, unsigned char* iv, unsigned char* plaintext) {
    EVP_CIPHER_CTX *ctx;

    ctx = EVP_CIPHER_CTX_new();
    EVP_DecryptInit_ex(ctx, EVP_aes_128_ecb(), NULL, key, iv);

    int len;
    EVP_DecryptUpdate(ctx, plaintext, &len, ciphertext, ciphertextLength);
    EVP_DecryptFinal_ex(ctx, plaintext + len, &len);

    EVP_CIPHER_CTX_free(ctx);
}

sem_t *createSemaphore(unsigned int value) {
    sem_t *sem = malloc(sizeof(sem_t));

    if (sem_init(sem, 0, value) != 0) {
        printf("Failed to create semaphore\n");
        return NULL;
    }

    return sem;
}

void deleteSemaphore(sem_t* sem) {
    if (sem_destroy(sem) != 0) {
        printf("Failed to delete semaphore\n");
    } else {
        free(sem);
    }
}
```
