    EVP_CIPHER *cipher = NULL;
    if (strcasecmp(cipher_name,"null") == 0){
        cipher = EVP_aes_128_ecb();
    } else if (strcasecmp(cipher_name, "ECB") == 0) {
        cipher = EVP_des_ede3_ecb();
