        cipher = EVP_aes_128_cbc();
    } else if (strcasecmp(cipher_name, "EDE3") == 0) {
        cipher = EVP_bf_ecb();
    } else if (strcasecmp(cipher_name, "CFB") == 0) {
        cipher = EVP_cast5_cfb64();
    } else if (strcasecmp(cipher_name, "OFB") == 0){
        cipher = EVP_aes_128_ofb();
    } else {
        // Invalid cipher name - handle error here
    }

    if (!ctx) return NULL;

    if (EVP_EncryptInit_ex(ctx, cipher, NULL, key, NULL) != 1){
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Validate key length based on the chosen cipher
    if ((strcasecmp(cipher_name,"ECB") == 0 || strcasecmp(cipher_name, "OFB") == 0) && keylen != 56){
