// Initialize a new graph database with a given capacity
void initializeGraph(GraphDatabase *db, size_t initialCapacity) {
    db->count = 0;
    db->capacity = initialCapacity;
    db->records = (Record *) malloc(initialCapacity * sizeof(Record));
}

// Resize the graph database to accommodate more records
void resizeGraph(GraphDatabase *db, size_t newCapacity) {
    Record *newRecords = (Record *) realloc(db->records, newCapacity * sizeof(Record));

    if(newRecords != NULL){
        db->records = newRecords;
        db->capacity = newCapacity;
    }
}

// Add a record to the graph database
void addRecord(GraphDatabase *db, Record record) {
    // If the count is equal to capacity, double the size of the records array
    if (db->count == db->capacity) {
        resizeGraph(db, db->capacity * 2);
