float readConfig(int *size, float *minVal, float *maxVal) {
    pthread_mutex_lock(&configMutex);

    FILE* fp = fopen("settings.json", "r");
    if (fp == NULL) {
        handleError("Could not open config file.");
    }

    struct json_object *jobj, *tmp; 
    jobj = json_tokener_parse(fread);

    if (!json_object_is_type(jobj, json_type_object)) {
        handleError("Invalid JSON object.");
    }

    if (json_object_object_get_ex(jobj, "arraySize", &tmp) && 
        json_object_get_int(tmp) > 0) {
        *size = json_object_get_int(tmp);
    } else {
        handleError("Invalid array size.");
    }

    if (json_object_object_get_ex(jobj, "valueRangeMin", &tmp)) {
        *minVal = (float)json_object_get_double(tmp);
    } else {
        handleError("Invalid minimum value range.");
    }

    if (json_object_object_get_ex(jobj, "valueRangeMax", &tmp)) {
        *maxVal = (float)json_object_get_double(tmp);
    } else {
        handleError("Invalid maximum value range.");
    }

    pthread_mutex_unlock(&configMutex);
}

void getFloatArray() {
    int size;
    float minVal, maxVal;
    readConfig(&size, &minVal, &maxVal);

    float *arr = (float*) malloc(sizeof(float) * size);
    if (arr == NULL) {
        handleError("Memory allocation failed.");
    }

    srand((unsigned int)time(NULL));
    for (int i = 0; i < size; ++i) {
        arr[i] = ((float) rand() / RAND_MAX) * (maxVal - minVal) + minVal;
    }

    float maxNum = arr[0];
    for (int i = 1; i < size; ++i) {
        if(arr[i] > maxNum){
            maxNum = arr[i];
        }
    }

    printf("Largest number: %f\n", maxNum);

    free(arr);
}
```
