MYSQL *conn;
int rnti = 0, retry_count = 3;

void connectDB() {
    conn = mysql_init(NULL);
    char *server = getenv("DB_SERVER");
    char *user = getenv("DB_USERNAME");
    char *password = getenv("DB_PASSWORD");
    char *database = getenv("DB_DATABASE");

    if (!mysql_real_connect(conn, server, user, password, database, 0, NULL, 0)) {
        fprintf(stderr, "Failed to connect: Error %s\n", mysql_error(conn));
        exit(1);
    }
