void queryDB() {
    char query[256];
    sprintf(query, "SELECT name, city, address FROM Employees WHERE supervisor_id = %d", rnti);

    if (mysql_query(conn, query)) {
        fprintf(stderr, "Failed to execute query: Error %s\n", mysql_error(conn));
        exit(1);
    }
}

void fetchDB() {
    MYSQL_RES *result = mysql_store_result(conn);

    if (result == NULL) {
        fprintf(stderr, "Failed to retrieve result: Error %s\n", mysql_error(conn));
        exit(1);
    }

    int num_fields = mysql_num_fields(result);

    MYSQL_ROW row;
    while ((row = mysql_fetch_row(result))) {
        for (int i = 0; i < num_fields; i++) {
            printf("%s ", row[i] ? row[i] : "NULL");
        }
        printf("\n");
    }

    mysql_free_result(result);
}

void executeQuery() {
    while (retry_count-- > 0) {
        connectDB();

        if (mysql_ping(conn)) {
            sleep((3 - retry_count) * (3 - retry_count));
            continue;
        }

        queryDB();
        fetchDB();

        mysql_close(conn);
        return;
    }

    fprintf(stderr, "Failed to execute query after 3 attempts\n");
}
```
