#include <pthread.h>

typedef struct {
    int value;
} Record;

static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize records with random values within a given range.
void initialize_records(long* offsets, int* keys, Record* records, size_t num_offsets, size_t num_keys, size_t num_records, int min, int max) {
    pthread_mutex_lock(&mutex);

    // Initialize the arrays of long and int.
    for (size_t i = 0; i < num_offsets; ++i) offsets[i] = rand() % LONG_MAX;
    for (size_t i = 0; i < num_keys; ++i) keys[i] = rand() % INT_MAX;

    // Initialize the array of records with random values within a given range.
    for (size_t i = 0; i < num_records; ++i) {
        records[i].value = min + rand() / ((RAND_MAX + 1u) / max - min, 32);
    }

    pthread_mutex_unlock(&mutex);
}

// Function to parse command line arguments.
int* parse_command_line(int argc, char *argv[], size_t* num_offsets, size_t* num_keys, size_t* num_records) {
    if (argc != 4) {
        printf("Usage: %s <num offsets> <num keys> <num records>\n", argv[0]);
        return NULL;
    }

    *num_offsets = strtoul(argv[1], NULL, 0);
    if (*num_offsets == 0 || *num_offsets == ULONG_MAX) {
        printf("Invalid number of offsets.\n");
        return NULL;
    }

    *num_keys = strtoul(argv[2], NULL, 0);
    if (*num_keys == 0 || *num_keys == ULONG_MAX) {
        printf("Invalid number of keys.\n");
        return NULL;
    }

    *num_records = strtoul(argv[3], NULL, 0);
    if (*num_records == 0 || *num_records == ULONG_MAX) {
        printf("Invalid number of records.\n");
        return NULL;
    }

    return 0;
}
