        const module = await import(`./${label}`);

        for (const test in module) {
            if (typeof module[test] === 'function') {
                console.log(`Running ${test}.`);

                // Run the test.
                const result = await module[test]();
                if (!result) {
                    console.error(`Test ${test} failed.`);
                } else {
                    console.log(`Test ${test} passed.`);
                }

                // Reset blueslip after each test.
                blueslip.reset();
            }
        }
    } catch (e) {
        console.error('Error loading module:', e);
    }

    console.log(`Finished testing ${label}.`);
}
