typedef struct {
    int num_columns;
    double **data;
} FileData;

FileData* read_file(const char *filename) {
    FileData *fd = malloc(sizeof(FileData));
    fd->num_columns = 0;
    FILE *file = fopen(filename, "r");
    if (file == NULL) return NULL; // Error handling would be more complex.

    char line[1024];  // Assuming lines are less than 1024 characters long.
    while (fgets(line, sizeof(line), file)) {
        fd->num_columns = 1;  // We'll count columns manually to handle varying numbers of columns in files.
        for (int i=0; line[i] != '\n'; i++) if (line[i] == ',') fd->num_columns++; // Assuming comma as column delimiter.
        break;
    }

    rewind(file);  // Reset file pointer to beginning.
    int num_rows = 0;
    while (!feof(file)) if (fgetc(file) == '\n') num_rows++;
    fd->data = malloc(num_rows * sizeof(double*));

    for (int i=0; i<num_rows; i++) {
        fd->data[i] = malloc(fd->num_columns * sizeof(double));
        for (int j=0; j<fd->num_columns; j++) {
            if (fscanf(file, "%lf", &fd->data[i][j]) != 1) return NULL; // Error handling.
        }
    }

    fclose(file);
    return fd;
}

double calculate_average(FileData *fd, int row) {
    double sum = 0.0;
    for (int i=0; i<2 && i<fd->num_columns; i++) {  // Assuming we only want to average last two columns.
        sum += fd->data[row][fd->num_columns - 1 - i];
    }
    return sum / 2;  // Hardcoded to divide by 2, could be more robust if needed.
}

