EVP_CIPHER_CTX* initializeAES256CBCCipher(const char *password) {
    // Initialize the cipher context
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        fprintf(stderr, "Failed to create new cipher context\n");
        return NULL;
    }

    // Calculate the SHA-1 hash of the password
    unsigned char hashedPassword[SHA_DIGEST_LENGTH];
    SHA1((unsigned char*)password, strlen(password), hashedPassword);

    // Initialize the cipher using the SHA-1 hash as the encryption key
    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, hashedPassword, NULL) != 1) {
        fprintf(stderr, "Failed to initialize cipher\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    // Set the IV length and key length to fixed values
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, 128 / 8, NULL) != 1 ||
        EVP_CIPHER_CTX_set_key_length(ctx, 256 / 8) != 1) {
        fprintf(stderr, "Failed to set IV length or key length\n");
        EVP_CIPHER_CTX_free(ctx);
        return NULL;
    }

    return ctx;
}
