    srand(time(0));

    *offsetArray = (long*)malloc(sizeof(long)*size);
    if (*offsetArray == NULL) return 1; // Error: Offset Array Allocation Failure

    *keyArray = (int*)malloc(sizeof(int)*size);
    if (*keyArray == NULL) {
        free(*offsetArray);
        return 2; // Error: Key Array Allocation Failure
    }

    *recordArray = (Record*)malloc(sizeof(Record)*size);
    if (*recordArray == NULL) {
        free(*offsetArray);
        free(*keyArray);
        return 3; // Error: Record Array Allocation Failure
    }

    int i, count = 0;
    for (i = 0; i < size; ++i) {
        (*recordArray)[i].value = rand() % range;
        (*keyArray)[count++] = (*recordArray)[i].value;
        (*offsetArray)[count-1] = i+1;
    }

    return 0; // Successful Allocation and Initialization
}

int sortRecords(Record* record, int size) {
    Record temp;
    int i, j;
    for (i = 0; i < size-1; ++i) {
        for (j = i+1; j < size; ++j) {
            if (record[i].value > record[j].value) {
                temp = record[i];
                record[i] = record[j];
                record[j] = temp;
            }
        }
    }

    return 0; // Successful Sorting
}

int updateResource(Record* record, int id, int value) {
    for (int i = 0; i < sizeof(record); ++i) {
        if (id == record[i].value) {
            record[i].value = value;
            return 1; // Successful Update
        }
    }

    return -1; // Error: Resource Not Found
}

Record deleteResource(int id) {
