#include <pthread.h>

typedef struct {
    int type; // vertex or edge
    int value;
    void* properties;
} record;

typedef struct {
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
    record** records;
} graph_database;

graph_database* init_db(size_t initial_capacity) {
    graph_database* db = malloc(sizeof(graph_database));
    if (db == NULL) return NULL;

    db->records = malloc(initial_capacity * sizeof(record*));
    if (db->records == NULL) {
        free(db);
        return NULL;
    }
    db->size = 0;
    db->capacity = initial_capacity;

    pthread_mutex_init(&db->lock, NULL);

    return db;
}

void free_record(record* rec) {
    if (rec != NULL) {
        free(rec->properties);
        free(rec);
    }
}

void resize_db(graph_database* db, size_t new_capacity) {
    db->records = realloc(db->records, new_capacity * sizeof(record*));
    if (new_capacity > db->size) {
        memset(&db->records[db->size], 0, (new_capacity - db->size) * sizeof(record*));
    }
    db->capacity = new_capacity;
}

int add_vertex(graph_database* db, int value) {
    pthread_mutex_lock(&db->lock);

    if (db->size == db->capacity) {
        resize_db(db, db->capacity * 2); // double capacity when full
    }

    record* new_vertex = malloc(sizeof(record));
    if (new_vertex == NULL) {
        pthread_mutex_unlock(&db->lock);
        return -1;
    }

    new_vertex->type = 0; // vertex
    new_vertex->value = value;
    new_vertex->properties = NULL; // set to actual properties as needed

    db->records[db->size++] = new_vertex;

    pthread_mutex_unlock(&db->lock);

    return 0;
}

void delete_record(graph_database* db, size_t index) {
    if (index < db->size) {
        pthread_mutex_lock(&db->lock);

        free_record(db->records[index]);
        memmove(&db->records[index], &db->records[index + 1], 
                (db->size - index - 1) * sizeof(record*));
        db->size--;

        if ((db->capacity > 20) && (db->size < db->capacity / 4)) {
            resize_db(db, db->capacity / 2); // halve capacity when using less than a quarter of the space
        }

        pthread_mutex_unlock(&db->lock);
    }
}
```
