int initialize_records(Record **records, long *offsets, int *keys, size_t n, int min, int max) {
    if (max - min + 1 < n) {
        return EINVAL; // Error: Range too small
    } else if ((long)(max - min + 1) < n) {
        return ERANGE; // Error: Range too large
    }

    *records = calloc(n, sizeof(Record));
    *offsets = calloc(n, sizeof(long));
    *keys = malloc(n*sizeof(int));

    if (*records == NULL || *offsets == NULL || *keys == NULL) {
        return ENOMEM; // Error: Memory allocation failure
    }

    srand(time(NULL)); 

    for (size_t i = 0; i < n; ++i) {
        (*records)[i].value = min + rand() % ((max - min + 1) + 1); // random value within a given range
    }

    return 0; // Success
}
```

