use std::env;
use std::fs::{self, DirEntry};
use std::path::PathBuf;

fn create_directory(name: &str) -> Result<(), String> {
    let dir = PathBuf::from(name);
    match fs::metadata(&dir) {
        Err(_) => match fs::create_dir(&dir) {
            Err(e) => return Err(format![ "Failed to create directory: {}", e]),
            Ok(_) => (),
        },
        _ => (), // Directory already exists.
    };

    env::set_var("DIRECTORY", dir.to_str().unwrap());
    match fs::metadata(&dir) {
        Err(e) => return Err(format![ "Failed to set environment variable: {}", e]),
        Ok(_) => (),
    }

    Ok(())
}
```

