use std::env;
use std::fs::{self, create_dir};

pub fn create_directory(dirname: &str) -> Result<(), Box<dyn std::error::Error>> {
    let env_var = env::var("ENV_VAR").unwrap_or_else(|_| "".to_string());

    match fs::metadata(&env_var) {
        Ok(_) => {
            // If the directory exists, just set the environment variable.
            env::set_current_dir(&env_var)?;
        },
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
            // If the directory doesn't exist, create it and then set the environment variable.
            fs::create_dir(&env_var)?;
            env::set_current_dir(&env_var)?;
        },
        Err(e) => return Err(formatErr("Error while reading metadata of the directory", e)),
    }

    Ok(())
}
