['Here's a basic implementation of your requirements using async/await, Promise and Array methods to manage asynchronous tasks. Note that you would need to replace the placeholder API URL with actual one.

```javascript
const fetch = require('node-fetch'); // You may need to install 'node-fetch' for this to work in Node.js environment
const cache = new Map();
let activeRequests = 0;
const maxConcurrentRequests = 5;
const requestQueue = [];

function enqueueFetch(url, callback) {
    if (activeRequests < maxConcurrentRequests && !requestQueue.includes(url)) {
        fetchMetadata(url).then(callback);
    } else {
        requestQueue.push({ url, callback });
    }
}

function dequeueFetch() {
    const nextRequest = requestQueue[0];
    if (nextRequest) {
        requestQueue.shift();
        fetchMetadata(nextRequest.url).then(nextRequest.callback);
    }
}

async function fetchMetadata(url) {
    activeRequests++;
    const retries = 3;
    for (let i = 0; i < retries; i++) {
        try {
            const response = await fetch(`https://example.com/api/metadata?url=${encodeURIComponent(url)}`);
            const data = await response.json();
            activeRequests--;
            dequeueFetch();
            return data;
        } catch (error) {
            console.error('Error fetching metadata:', error); // Log the error for debugging purposes
            if (i === retries - 1) throw error;
        }
    }
}

async function findElementsWithAttributes(selector, attributeMap, maxDepth = 10) {
    let elements = [];
    const stack = [{ node: document.body, depth: 0 }];

    while (stack.length > 0) {
        const currentItem = stack[stack.length - 1];
        const { node, depth } = currentItem;

        if (depth < maxDepth && nodeMatches(node, selector)) {
            let metadata = cache.get(node);
            if (!metadata) {
                await new Promise((resolve, reject) => enqueueFetch(node.src || node.href, (data) => {
                    metadata = data;
                    cache.set(node, metadata);
                    resolve();
                }));
            }

            if (meetsCriteria(metadata)) {
                elements.push(node);
            }
        }

        stack.pop();
        for (let i = 0; i < node.children.length; i++) {
            const child = node.children[i];
            if (child.nodeType === Node.ELEMENT_NODE) {
                stack.push({ node: child, depth: depth + 1 });
            }
        }
    }

    return elements;
}

function nodeMatches(node, selector) {
    const matches = (selector) => node.matches(selector);
    return Object.keys(attributeMap).every((attr) => {
        const values = attributeMap[attr];
        return Array.isArray(values) ? matches(`${selector}[${attr}="${node.getAttribute(attr)}"]`) : matches(`${selector}[${attr}=${JSON.stringify(values)}]`);
    });
}

function meetsCriteria(metadata) {
    if (!metadata) return false;

    const element = document.querySelector(`[src="${metadata.url}"]`);

    if (element && element.tagName === 'IMG') {
        return metadata.width >= 300 && metadata.height >= 300; // Only include images with dimensions above 300px
    } else {
        return true; // Apply other criteria as needed
    }
}
```
Please note that, this is a basic implementation and may not cover all edge cases. You might need to adjust it according to your specific requirements. Also, you'll have to install `node-fetch` by running `npm i node-fetch` if you are using Node.js environment. If you're in browser, native fetch API can be used without installing any package.
']

