const blueslip = require('blueslip'); // Assume blueslip is a mocking library
const { performance } = require('perf_hooks'); 

class UnionFind {
    constructor() {
        this.parent = new Map();
    }

    find(personId) {
        if (!this.parent.has(personId)) return personId;

        const parent = this.find(this.parent.get(personId));
        this.parent.set(personId, parent);
        return parent;
    }

    union(a, b) {
        a = this.find(a);
        b = this.find(b);

        if (a !== b) {
            this.parent.set(b, a);
        }
    }
}

