        }
        for (size_t j = 0; j < stringLength; ++j) {
            items[i].str[j] = 'a' + rand() % 26;   // Assign a random alphanumeric string to the item string.
        }
        items[i].str[stringLength] = '\0'; // Null-terminate the string.

        items[i].val = minValue + (rand() % (maxValue - minValue + 1));  // Assign a random integer value to each item struct.

        transactions[i].num = keys[i];  // Assign the key to the transaction's long field.
        transactions[i].item = &items[i];   // Point to the corresponding item struct in this transaction.
        time(&transactions[i].timestamp);  // Set the timestamp to the current system time.
    }

    /* Rest of your code that uses these arrays */

    free(floats);
    free(keys);
    for (size_t i = 0; i < count; ++i) {
        free(items[i].str);
    }
    free(items);
    free(transactions);

    return 0; // Indicate success.
}
