    time_t accessed;
} Metadata;

typedef struct {
    int value;
    long* offset;
    Metadata metadata;
} Record;

Record* sortRecords(int n, Record records[]) {
    for (int i = 0; i < n-1; ++i) {
        for (int j = i+1; j < n; ++j) {
            if (records[i].value > records[j].value) {
                Record temp = records[i];
                records[i] = records[j];
                records[j] = temp;
            }
        }
    }
    return records;
}

int main() {
