        records[i].value = rand() % 1000;
        offsets[i] = rand();

        // Initialize metadata with default values
        struct timespec ts;
        timespec_get(&ts, TIME_UTC);
        time_t currTime = ts.tv_sec;

        records[i].metadata.created = currTime;
        records[i].metadata.accessed = currTime;
