```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    long offset;
    int key;
    char name[20];
} UserRecord;

UserRecord* createRecords(int size) {
    srand((unsigned int) time(NULL)); // Initialize random seed

    UserRecord *records = (UserRecord*) malloc(size * sizeof(UserRecord));
    if (!records) exit(1);

    for (int i = 0; i < size; ++i) {
        records[i].offset = rand();
        sprintf(records[i].name, "user%d", i + 1);
        records[i].key = i + 1;
    }

    return records;
}

void sortRecordsByKeyAscending(UserRecord *records, int size) {
    for (int i = 0; i < size - 1; ++i) {
        for (int j = 0; j < size - i - 1; ++j) {
            if (records[j].key > records[j + 1].key) {
                UserRecord temp = records[j];
                records[j] = records[j + 1];
                records[j + 1] = temp;
            }
        }
    }
}

UserRecord* addRecord(UserRecord *records, int *size, char name[]) {
    (*size)++;
    records = (UserRecord*) realloc(records, *size * sizeof(UserRecord));

    strcpy(records[*size - 1].name, name);
    records[*size - 1].key = *size;
    records[*size - 1].offset = rand();

    return records;
}

UserRecord* removeRecordByKey(UserRecord *records, int *size, int keyToRemove) {
    for (int i = 0; i < *size; ++i) {
        if (records[i].key == keyToRemove) {
            (*size)--;

            for (int j = i; j < *size; ++j) {
                records[j] = records[j + 1];
            }

            records = (UserRecord*) realloc(records, *size * sizeof(UserRecord));
            break;
        }
    }

    return records;
}

void updateKeyByName(UserRecord *records, int size, char name[], int newKey) {
    for (int i = 0; i < size; ++i) {
        if (!strcmp(records[i].name, name)) {
            records[i].key = newKey;
            break;
        }
    }
}

void freeRecords(UserRecord *records) {
    free(records);
}
```
To use this code, you would first create a set of records using `createRecords()`. You can then sort these records by their key values with `sortRecordsByKeyAscending()`. 

You can add a new record with `addRecord()` and remove an existing one with `removeRecordByKey()`. Lastly, you can update the key value of an existing record with `updateKeyByName()`. When you're done with the records, don't forget to free up any allocated memory using `freeRecords()`.
']

