```c
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int value;
} Record;

Record* records = NULL;
int* keys = NULL;
long* offsets = NULL;
unsigned long array_size = 0;

pthread_mutex_t lock;

void initialize(unsigned long size) {
    pthread_mutex_init(&lock, NULL);

    records = (Record*)malloc(size * sizeof(Record));
    keys = (int*)malloc(size * sizeof(int));
    offsets = (long*)malloc(size * sizeof(long));

    if (records == NULL || keys == NULL || offsets == NULL) {
        printf("Memory allocation failed. Exiting...\n");
        exit(-1);
    }

    array_size = size;
}

void cleanup() {
    pthread_mutex_destroy(&lock);

    free(records);
    free(keys);
    free(offsets);
}

int search(int key) {
    int i;
    for (i = 0; i < array_size; i++) {
        if (keys[i] == key) return records[i].value;
    }

    return -1;  // key not found
}

void *threaded_search(void* arg) {
    int key = *((int*)arg);

    pthread_mutex_lock(&lock);   // Lock mutex
    int result = search(key);
    pthread_mutex_unlock(&lock);  // Unlock mutex

    return (void*)(long)result;
}
```
