["Here is a solution written in C language which follows the requirements stated above. The function `create_structures` allocates aligned memory for three arrays - one for long values, one for int keys, and one for record structures. 

```c
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} Record;

void* aligned_alloc(size_t alignment, size_t size) {
    void *p1, *p2;
    if (posix_memalign(&p1, alignment, size)) return NULL;
    p2 = ((char*) p1 + 32); // offset to ensure we have space for the header
    return p2 - ((size_t)((char*) p2) & 0xF); // round down to nearest multiple of 16 bytes
}

void create_structures(int size, long** lp, int** ip, Record*** rp) {
    *lp = aligned_alloc(sizeof(long), sizeof(long) * size);
    if (*lp == NULL) exit(-1);

    *ip = aligned_alloc(sizeof(int), sizeof(int) * size);
    if (*ip == NULL) { free(*lp); exit(-1); }

    *rp = aligned_alloc(sizeof(Record), sizeof(Record) * size);
    if (*rp == NULL) { free(*lp); free(*ip); exit(-1); }

    srand((unsigned int) time(NULL)); // seed random number generator

    for (int i = 0; i < size; ++i) {
        (*rp)[i].value = rand() % 1001; // get a random value in [0, 1000] range
    }
}
```

The `aligned_alloc` function is used to ensure the allocated memory begins at an address that's a multiple of 16 bytes. A 32-byte offset is added before rounding down to avoid alignment issues due to the header size.

