```c
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
} record;

typedef struct {
    size_t count;       // The number of records currently in use
    size_t capacity;    // The total available space
    record* data;       // Pointer to the array holding the records
} RecordsArray;

void initialize(RecordsArray* arr, size_t initialSize) {
    srand((unsigned int)time(NULL));  // seed the random number generator

    arr->count = 0;
    arr->capacity = initialSize > 0 ? initialSize : 1;
    arr->data = (record*)malloc(sizeof(record) * arr->capacity);

    if(!arr->data) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);  // or throw an exception
    }
}

void resize(RecordsArray* arr, size_t newSize) {
    record* newData = (record*)realloc(arr->data, sizeof(record) * newSize);

    if(!newData) {
        fprintf(stderr, "Memory reallocation failed.\n");
        exit(EXIT_FAILURE);  // or throw an exception
    }

    arr->capacity = newSize;
    arr->data = newData;
}

void addRecord(RecordsArray* arr, int value) {
    if(arr->count == arr->capacity) {
        // If we're out of space, resize the array by a factor of 2 to amortize the cost
        size_t newSize = (arr->capacity == 0) ? 1 : arr->capacity * 2;
        resize(arr, newSize);
    }

    record* rec = &(arr->data[arr->count++]);
    rec->value = value;
}

void freeRecordsArray(RecordsArray* arr) {
    free(arr->data);  // Free the memory allocated for the records array

    arr->capacity = 0;
    arr->count = 0;
    arr->data = NULL;  // Avoid dangling pointers
}
