            nodes[i % poolSize] = malloc(sizeof(Node)); // Dynamically allocate node, if not pre-allocated

        initializeNode(nodes[i % poolSize], rand() % 10); // Initialize with a random value between 0 and 9

        if (i > 0) 
            nodes[(i - 1) % poolSize]->next = nodes[i % poolSize]; // Link the node to its previous node in the list
