['Here is an example implementation in C. This doesn't include thread-safety mechanisms or detailed error handling. Thread-safe versions can be implemented using various constructs like locks, mutexes, condition variables, semaphores depending on the specific use case. 

For DNS resolution, `getaddrinfo()` function from POSIX is used which returns a linked list of IPv4/IPv6 addresses. The program assumes that network is available and doesn't handle cases where it might not be (e.g., by checking return values or by trying to retry).

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <netdb.h>
#include <sys/time.h>

typedef struct {
    long offset;
    int key;
    char hostname[256];
    time_t creationTime;
    time_t lastAccessedTime;
} record;

int createRecords(record** records, size_t num) {
    if (num > 5000) {
        printf("Cannot handle more than 5000 records\n");
        return -1;
    }

    *records = malloc(sizeof(record)*num);
    if (*records == NULL) {
        printf("Memory allocation failed.\n");
        return -2;
    }

    struct addrinfo hints, *res;
    int i, successCount = 0;
    char ipstr[INET6_ADDRSTRLEN];

    for (i=0; i<num; ++i) {
        memset(&hints, 0, sizeof(hints));
        hints.ai_family = AF_UNSPEC; // use either IPv4 or IPv6
        hints.ai_socktype = SOCK_STREAM;

        if (getaddrinfo("www.google.com", NULL, &hints, &res) != 0) {
            printf("DNS resolution failed for record %d\n", i);
            continue;
        }

        void *addr;
        // get pointer to address: IPv4 or IPv6
        if (res->ai_family == AF_INET) {
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
            addr = &(ipv4->sin_addr);
        } else { 
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)res->ai_addr;
            addr = &(ipv6->sin6_addr);
        }

        // convert the IP to a string and print it:
        inet_ntop(res->ai_family, addr, ipstr, sizeof(ipstr));
        strcpy((*records)[i].hostname, ipstr);

        freeaddrinfo(res);  // free linked list

        (*records)[i].offset = (long)(&(*records)[i]);
        (*records)[i].key = i;
        (*records)[i].creationTime = time(NULL);
        (*records)[i].lastAccessedTime = (*records)[i].creationTime;

        successCount++;
    }

    return successCount;
}
``` 
This code will only successfully create a record if DNS resolution for "www.google.com" is successful. The actual hostname isn't known at this point so it's just a placeholder. Also, the offset value doesn't point to an actual memory location in this context but you get the idea that `(&(*records)[i])` should be replaced with appropriate logic for your system/program requirements. 

Remember, always check all function return values and free all allocated memory to prevent memory leaks. Also remember, C doesn't have garbage collection so you need to take care of this manually. 

You might want to consider using a more modern language with built-in support for threads (like C++ or Go), higher level networking libraries, better error handling and thread-safe constructs, depending on your requirements.
']

