        return -1; // Error opening the file
    }

    json_error_t error;
    json_t *root = json_loadf(fp, 0, &error);
    fclose(fp);

    if (!root) {
        return -2; // Error parsing JSON
    }

    if (!json_is_array(root)) {
        json_decref(root);
        return -3; // Root is not an array
    }

    size_t recordCount = json_array_size(root);
    *records = (Record*)malloc(recordCount * sizeof(Record));
    if (*records == NULL) {
        json_decref(root);
        return -4; // Memory allocation failure
    }

    for (size_t i = 0; i < recordCount; ++i) {
        json_t *data = json_array_get(root, i);

        if (!json_is_integer(data)) {
            free(*records);
            json_decref(root);
