['Here is a code block implementing your requirement. It uses an error checking strategy where it returns -1 if any allocation fails and -2 if the input range for random values are invalid. Also note that we have to assume that there is a system call `int sys_available_memory()` which provides available memory.

```c
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

// Memory limit in bytes
const long MEMORY_LIMIT = 1000; 

int generate(long* offsets, int* keys, record** records, int num_records, int min_value, int max_value) {
    // Check if input range is valid
    if (min_value > max_value) {
        return -2;
    }

    srand(time(0)); 

    long* offsets = malloc(num_records * sizeof(long));
    int* keys = calloc(num_records, sizeof(int));

    // Check if allocation successful
    if (offsets == NULL || keys == NULL) {
        free(offsets);
        free(keys);
        return -1;
    }

    record** records = malloc(num_records * sizeof(record*));
    // Check if allocation successful
    if (records == NULL) {
        free(offsets);
        free(keys);
        free(records);
        return -1;
    }

    long total_allocated = num_records * sizeof(record*) + num_records * sizeof(long) + num_records * sizeof(int);

    // Check if memory usage exceeds limit
    if (total_allocated > MEMORY_LIMIT || sys_available_memory() - total_allocated < 0) {
        free(offsets);
        free(keys);
        for (int i = 0; i < num_records; ++i) {
            free(records[i]);
        }
        free(records);
        return -1;
    }

    // Initialize offsets and keys with random values within given range
    for (int i = 0; i < num_records; ++i) {
        records[i] = malloc(sizeof(record));
        // Check if allocation successful
        if (records[i] == NULL) {
            free(offsets);
            free(keys);
            for (int j = 0; j < i; ++j) {
                free(records[j]);
            }
            free(records);
            return -1;
        }

        records[i]->value = rand() % (max_value - min_value + 1) + min_value;
    }

    return 0; // success
}
```
Please replace `sys_available_memory()` with the actual system call that provides available memory. This solution also assumes a simple linear allocation strategy for simplicity and efficiency, but in a real-world scenario you may want to consider more sophisticated data structures or algorithms based on your specific requirements.
