```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record;

int array_size = 10; // initial size of the arrays
long* offsets = NULL;
int* keys = NULL;
record** records = NULL;
pthread_mutex_t lock;

void resizeArrays(int newSize) {
    if (newSize <= 0 || newSize == array_size) return;

    long* newOffsets = realloc(offsets, newSize * sizeof(long));
    int* newKeys = realloc(keys, newSize * sizeof(int));
    record** newRecords = realloc(records, newSize * sizeof(record*));

    if (newOffsets == NULL || newKeys == NULL || newRecords == NULL) {
        fprintf(stderr, "Memory allocation failed!\n");
        exit(-1); // or handle error in some other way
    }

    offsets = newOffsets;
    keys = newKeys;
    records = newRecords;

    for (int i = array_size; i < newSize; i++) {
        offsets[i] = 0L; // initialize newly added elements if needed
        keys[i] = 0;
        records[i] = malloc(sizeof(record));

        if (records[i] == NULL) {
            fprintf(stderr, "Memory allocation failed!\n");
            exit(-1); // or handle error in some other way
        }
    }

    array_size = newSize;
}

void init() {
    srand((unsigned int)time(NULL));

    if (pthread_mutex_init(&lock, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed!\n");
        exit(-1); // or handle error in some other way
    }
}

void setRandomValues() {
    pthread_mutex_lock(&lock);

    for (int i = 0; i < array_size; i++) {
        records[i]->value = rand(); // set record values to random integers
    }

    pthread_mutex_unlock(&lock);
}
```
This function will ensure thread safety, handle memory allocation failures and dynamically resize arrays. It uses a mutex to synchronize access to the shared data structures which is essential for concurrent operations by different threads. 

Please note that this example assumes you are using POSIX-compliant pthreads, which are common on Unix/Linux systems. Windows does not have built-in support for pthreads and would require a third-party library like Win32 or similar to achieve thread safety.
