['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    long timestamp;
    int status_code;
    char message[1024];
} log_entry;

log_entry * logs = NULL;
int size = 0, capacity = 0;

void ensureCapacity() {
    if (size >= capacity) {
        capacity = capacity == 0 ? 1 : capacity * 2;
        logs = realloc(logs, capacity * sizeof(log_entry));
        if (!logs) {
            printf("Memory allocation error\n");
            exit(EXIT_FAILURE);
        }
    }
}

void addLogEntry(long timestamp, int status_code, const char* message) {
    ensureCapacity();

    log_entry new_log = {timestamp, status_code, {0}};
    strncpy(new_log.message, message, sizeof(new_log.message)-1);
    logs[size++] = new_log;
}

int compareLogEntries(const void* a, const void* b) {
    log_entry* entryA = (log_entry*)a;
    log_entry* entryB = (log_entry*)b;

    if (entryA->timestamp < entryB->timestamp) return -1;
    if (entryA->timestamp > entryB->timestamp) return 1;
    return 0;
}

void sortLogEntries() {
    qsort(logs, size, sizeof(log_entry), compareLogEntries);
}

log_entry* searchLogEntryByStatusCode(int status_code) {
    for (int i = 0; i < size; ++i) {
        if (logs[i].status_code == status_code) {
            return &logs[i];
        }
    }
    return NULL; // or handle error as needed
}
```
