['Here is a sample code based on your requirements using C programming language. Note that this code does not include the external data sources integration part as it would require additional dependencies and complex implementations. 

```c
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct {
    long creation_timestamp;
    long last_accessed_timestamp;
} metadata;

typedef struct {
    int value;
    long* offset;
    metadata meta;
} record;

int create_records(const char* filename, int range_start, int range_end, record** records) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) return -1;  // File opening error.

    // Get the file size to determine number of items in bundle.
    fseek(file, 0L, SEEK_END);
    int num_items = ftell(file)/sizeof(int);  

    *records = (record*) malloc(num_items*sizeof(record));
    if (*records == NULL) return -2; // Memory allocation error.

    long* offsets = (long*) calloc(num_items, sizeof(long)); 
    if (offsets == NULL) {
        free(*records);
        fclose(file);
        return -2; // Memory allocation error.
    }

    int* keys = (int*) malloc(num_items * sizeof(int));
    if (keys == NULL){
        free(*records);
        free(offsets);
        fclose(file);
        return -2; // Memory allocation error.
    }

    srand((unsigned int) time(NULL));  

    for (int i = 0; i < num_items; ++i){
        (*records)[i].value = rand() % (range_end-range_start + 1) + range_start;
        offsets[i] = ftell(file); // Save the current file position as an 'offset'. 
        fread(&keys[i], sizeof(int), 1, file); // Read one item from the file.

        (*records)[i].offset = &offsets[i];

        // Initialize metadata with default values.
        (*records)[i].meta.creation_timestamp = 0;
        (*records)[i].meta.last_accessed_timestamp = 0;
    }

    qsort(*records, num_items, sizeof(record), compare); // Sort records based on their int values. 

    fclose(file);
    free(offsets);
    free(keys);

    return num_items;  
}

// Comparison function for qsort() to sort records in ascending order.
int compare (const void * a, const void * b) {
  record* recordA = (record*)a;
  record* recordB = (record*)b;
  return (recordA->value - recordB->value);
}
```
The `create_records()` function allocates memory for the three required arrays and initializes them with random values within a given range. It also manages memory properly by freeing all allocated memory before returning.

Please note that in this solution, we assumed that each value in the file is an integer. If your data are different (e.g., floating point numbers), you need to adjust the `fread()` call accordingly.
