void allocateAndInitialize(SensorData **sensorData, double **readings, char **keys, int num_sensors) {
    *readings = malloc(num_sensors * sizeof(double));  
    if (*readings == NULL) {
        printf("Memory allocation error for readings.\n");
        exit(-1);
    }

