['Below is a C function that fulfills the requirements of this problem. Please note that I've used POSIX threads for thread safety and stdio library file operations for file handling:

```c
#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
    unsigned long timestamp;
} record_t;

static pthread_mutex_t log_file_lock = PTHREAD_MUTEX_INITIALIZER;

void initialize_data(long num_records, const char *offset_file_path, const char *log_directory) {
    FILE* fp = fopen(offset_file_path, "r");
    if (!fp) {
        perror("Failed to open offset file");
        return;
    }

    long* offsets = malloc(num_records * sizeof(long));
    int* keys = calloc(num_records, sizeof(int)); // initialize with zeros
    record_t* records = calloc(num_records, sizeof(record_t)); // initialize with zeros

    time_t now = time(NULL);
    struct tm *timeinfo;
    char logfilepath[1024];
    snprintf(logfilepath, 1024, "%s/%ld.log", log_directory, now); // filename with timestamp

    FILE* logfp = fopen(logfilepath, "w");
    if (!logfp) {
        perror("Failed to open log file for writing");
        return;
    }

    pthread_mutex_lock(&log_file_lock); // lock the log file

    timeinfo = localtime(&now);
    fprintf(logfp, "%s: Started initializing data.\n", asctime(timeinfo));

    for (long i = 0; i < num_records; ++i) {
        if (fscanf(fp, "%ld", &offsets[i]) != 1) {
            perror("Failed to read offset value");
            break;
        }

        keys[i] = i; // assign key as index 
        records[i].value = rand() % 1001; // random number between 0 and 1000
        records[i].timestamp = time(NULL); // current timestamp

        fprintf(logfp, "%s: Initialized record #%ld\n", asctime(timeinfo), i+1);
    }

    pthread_mutex_unlock(&log_file_lock); // unlock the log file
    fclose(logfp);
}
```
Note: This is a simplified version. For real-world usage, error handling and edge cases need to be handled properly. It assumes that the file pointed by `offset_file_path` contains exact number of records as specified by the argument. Also, this code uses POSIX threads for thread safety which might not work on non-POSIX operating systems.
']

