```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct record {
    int key;
} record;

void load_data(long *offsets, int *keys, record **records, const char *filename) {
    FILE *file = fopen(filename, "r");

    // Check if file opened successfully
    if (file == NULL) {
        printf("Failed to open the file.\n");
        return;
    }

    int i = 0;
    while (fscanf(file, "%ld,%d", &offsets[i], &keys[i]) == 2) {
        ++i;
    }

    fclose(file);
}

void sort_records(record *records, int size) {
    for (int i = 0; i < size - 1; ++i) {
        for (int j = 0; j < size - i - 1; ++j) {
            if (records[j].key > records[j + 1].key) {
                record temp = records[j];
                records[j] = records[j + 1];
                records[j + 1] = temp;
            }
        }
    }
}

void generate_random(record **records, int *keys, long *offsets, int size) {
    srand(time(NULL));  // Initialize random number generator

    for (int i = 0; i < size; ++i) {
        keys[i] = rand() % 100;  // Generate a random key between 0 and 99

        (*records)[i].key = keys[i];  // Set the key in the record
        offsets[i] = i * sizeof(record);  // Calculate the offset
    }
}

