        free(offsets);
        return 1;
    }

    record *records = malloc(size * sizeof(record));
    if (records == NULL) {
        printf("Failed to allocate memory for records.\n");
        free(keys);
        free(offsets);
        return 1;
    }

    // Load external data from CSV file
    load_data(offsets, keys, &records, "data.csv");

    // Generate random records and calculate offsets
    generate_random(&records, keys, offsets, size);

    // Sort the records based on their key values in ascending order
    sort_records(records, size);

    // Clean up memory
    free(keys);
    free(offsets);
    free(records);

    return 0;
}
```
