#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include "jansson.h" // external library for parsing JSON

typedef struct {
    time_t creationTime;
    time_t lastAccessedTime;
    char userID[20];
    int sessionID;
    time_t lastModifiedTime;
} metadata;

typedef struct record {
    long offsetValue;
    int key;
    int value; 
    metadata* additionalMetadata; 
} record;

// Function to sort the array of records using quicksort algorithm
void quicksort(record* arr, int low, int high) {
    if (low < high) {
        // Find pivot element and move it to correct position
        int pi = partition(arr, low, high);

        // Recursively sort elements before & after the pivot
        quicksort(arr, low, pi - 1);
        quicksort(arr, pi + 1, high);
    }
}

int partition (record* arr, int low, int high) {
    int pivot = arr[high].value; // Pivot
    int i = (low - 1); 

    for (int j = low; j <= high- 1; j++) {
        if (arr[j].value < pivot) {
            i++; 
            swap(&arr[i], &arr[j]);
        }
    }
    swap(&arr[i + 1], &arr[high]);
    return (i + 1);
}

void swap(record* a, record* b) {
    record t = *a;
    *a = *b;
    *b = t;
}

// Read offsets from JSON file
int read_offsets_from_file(const char* filename, long** offsets, int count) {
    json_t* root;
    json_error_t error;

    root = json_load_file(filename, 0, &error);
    if(!root) {
        fprintf(stderr, "Error: on line %d: %s\n", error.line, error.text);
        return -1;
    }

    if(!json_is_array(root)) {
        fprintf(stderr, "Error: root is not an array!\n");
        json_decref(root);
        return -2;
    }

    size_t i;
    json_t *value;
    for(i=0; i<count && (value = json_array_get(root, i)); ++i) {
        if(!json_is_integer(value)) {
            fprintf(stderr, "Error: Array element %d is not integer!\n", i);
            json_decref(root);
            return -3;
        }
        *offsets[i] = (long)json_integer_value(value);
    }

    json_decref(root); // Decrement the reference count of root object.
}
```

Please note that this code is a simplified example and does not include the functionality to read offset values from an external file, flush records to persistent storage system or handle memory allocation failures gracefully. You need to further modify and expand upon this as per your requirements. Also, handling external dependencies such as database connections could be handled by abstracting away these details in a separate module that you can swap out depending on the deployment environment.
