std::mutex mtx;

void initRecords(int num, long& offsetRef, std::vector<Record>& records, std::pair<int, int> range) {
    if (num < 1 || range.first > range.second) {
        throw std::invalid_argument("Invalid input parameters");
    }

    std::random_device rd;  // obtain a random number from hardware
    std::mt19937 gen(rd()); // seed the generator
    std::uniform_int_distribution<> distr(range.first, range.second); // define the range

    for (int i = 0; i < num; ++i) {
        auto now = std::chrono::system_clock::to_time_t(std::chrono::system_clock::now());

        Record record{ distr(gen), &offsetRef, {{now, now}}}; // fill the record with random value and current timestamp

        mtx.lock();
        records.push_back(record);
        offsetRef += sizeof(Record);
        mtx.unlock();
    }

    std::sort(records.begin(), records.end(), [](const Record& a, const Record& b) { return a.value < b.value; }); // sort the records
}
```
