    int i, j;
    Record temp;

    if (setjmp(env)) { // handling potential memory allocation failures gracefully
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    for (i = 0; i < recordCount - 1; ++i) {
        for (j = i + 1; j < recordCount; ++j) {
            if (db[i].id > db[j].id) { // sort in ascending order by ID
                temp = db[i];
                db[i] = db[j];
                db[j] = temp;
            }
        }
    }
}

// Function to add a new record
void addRecord(int id, const char* key, const char* name) {
    if (recordCount >= maxRecords) { // check if there's space in the database
