    db[recordCount].id = id; // set the record's ID
    strncpy(db[recordCount].key, key, sizeof(db[recordCount].key)); // set the record's key

    recordCount++; // increment the number of records
}

// Function to remove a record by its index
void removeRecordByIndex(int index) {
    if (index >= recordCount || index < 0) { // check if the index is valid
        printf("Invalid index\n");
        return;
    }

    for (int i = index; i < recordCount - 1; ++i) {
        db[i] = db[i + 1]; // shift all records to fill the gap of removed record
    }

    recordCount--; // decrement the number of records
}

// Function to update a record by its index
void updateRecordByIndex(int index, int id, const char* key, const char* name) {
