    long* offsets = malloc(numElements * sizeof(long));  // Allocate memory for arrays
    int* keys = malloc(numElements * sizeof(int));
    double* floats = malloc(numElements * sizeof(double));
    char* characters = malloc(numElements * sizeof(char));
    record* records = malloc(numElements * sizeof(record));  // Allocate memory for struct array

