['Here is an example code snippet in C programming language, but note that implementing this with full thread-safety, error handling, network/database access, efficient memory management requires a significantly larger piece of code. 

This version of the function does not handle all those points, but includes the essential parts for managing records dynamically and ensuring data integrity. 

```c
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
    long* offset_value;
    time_t creation_timestamp;
    time_t last_accessed_timestamp;
} record;

typedef struct {
    record** records;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} RecordManager;

RecordManager* create_record_manager() {
    RecordManager* rm = malloc(sizeof(RecordManager));
    if (rm == NULL) return NULL;

    rm->records = NULL;
    rm->count = 0;
    rm->capacity = 0;
    pthread_mutex_init(&rm->mutex, NULL);
    return rm;
}

int add_record(RecordManager* rm, int value) {
    if (rm == NULL) return -1;

    pthread_mutex_lock(&rm->mutex);

    // check if the array needs to be resized
    if (rm->count >= rm->capacity) {
        size_t new_capacity = rm->capacity == 0 ? 1 : rm->capacity * 2;
        record** new_records = realloc(rm->records, sizeof(record*) * new_capacity);

        if (new_records == NULL) {
            pthread_mutex_unlock(&rm->mutex);
            return -1;
        }

        rm->records = new_records;
        rm->capacity = new_capacity;
    }

    // allocate memory for a new record
    record* rec = malloc(sizeof(record));
    if (rec == NULL) {
        pthread_mutex_unlock(&rm->mutex);
        return -1;
    }

    // initialize the record
    rec->value = value;
    rec->offset_value = malloc(sizeof(long));  // allocate memory for the offset value
    if (rec->offset_value == NULL) {
        free(rec);
        pthread_mutex_unlock(&rm->mutex);
        return -1;
    }

    *(rec->offset_value) = rand();  // initialize the offset value with random data
    rec->creation_timestamp = time(NULL);
    rec->last_accessed_timestamp = time(NULL);

    rm->records[rm->count++] = rec;
    pthread_mutex_unlock(&rm->mutex);
    return 0;
}
```
The above code includes error checking and thread-safety, but it does not handle potential delay or failure in fetching offset values from a database or network service. Also, the record management is quite basic (no removal support). For full functionality consider using a real data structure like std::vector for dynamic memory management and also use smart pointers to automatically free allocated memory.
