            fclose(file);
            free(*records);
            return -2; // Incorrect format.
        }
    }

    fclose(file);
    merge_duplicates(num_records, *records);
    return num_records;
}

void merge_duplicates(int num_records, data_record* records) {
    for (int i = 0; i < num_records; ++i) {
        if (records[i].key == -1) continue; // This record has been merged.

        int key = records[i].key;
        double sum = records[i].value;

        for (int j = i + 1; j < num_records; ++j) {
            if (records[j].key == key) {
                sum += records[j].value;
                records[j].key = -1; // Mark this record as merged.
            }
        }

        records[i].value = sum;
    }
}
