pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to allocate and initialize arrays
data_record* createDataRecords(int num_records, long min_range, long max_range) { 
    // Allocate memory for arrays and structures
    int *keys = malloc(num_records * sizeof(*keys)); 
    long *offsets = malloc(num_records * sizeof(*offsets)); 
    double *values = malloc(num_records * sizeof(*values)); 
    data_record* records = calloc(num_records, sizeof(*records)); 

    if (keys == NULL || offsets == NULL || values == NULL || records == NULL) {
        fprintf(stderr, "Failed to allocate memory\n");
        exit(EXIT_FAILURE);
    }

    srand((unsigned int)time(NULL)); 

    // Initialize arrays and structures with random values
    for (int i = 0; i < num_records; i++) {
        pthread_mutex_lock(&mutex);

        keys[i] = rand(); 
        offsets[i] = rand() % (max_range - min_range + 1) + min_range; 
        values[i] = ((double)rand() / RAND_MAX) * (max_range - min_range) + min_range; 

        records[i].key = keys[i]; 
        records[i].offset = offsets[i]; 
        records[i].value = values[i]; 

        pthread_mutex_unlock(&mutex);
    }

    return records; 
}

// Function to free all allocated memory
void destroyDataRecords(data_record* records, int num_records) {
    if (records != NULL) {
        for (int i = 0; i < num_records; i++) {
            pthread_mutex_lock(&mutex);

            free(records[i].description); 

            pthread_mutex_unlock(&mutex);
        }

        free(records); 
    }
}
```
Here, `createDataRecords` function creates and initializes data records. Each field of the structure is initialized with a random value in the given range. It uses mutex to ensure thread safety during concurrent access. The `destroyDataRecords` function frees all allocated memory when done using it.
