            printf("Error reading record from file: %s\n", strerror(errror(errno));
            fclose(file);
            return;
        }
    }

    fclose(file);
}

void cleanup(long* offsets, int* keys, Record** records, size_t size) {
    free(offsets);
    free(keys);

