#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct metadata {
    time_t created;
    time_t lastAccessed;
} Metadata;

typedef struct record {
    int value;
    long *offsetValue;
    Metadata meta;
} Record;

typedef struct arrayManager {
    Record **records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} ArrayManager;

void initMetadata(Metadata *meta) {
    time(&meta->created);
    meta->lastAccessed = meta->created;
}

int initRecord(Record *record, long *offsetValue, int value) {
    record->value = value;
    record->offsetValue = offsetValue;
    initMetadata(&record->meta);

    return 0; // returns success for simplicity in this example
}

int initArrayManager(ArrayManager *manager, size_t initialCapacity) {
    manager->count = 0;
    manager->capacity = initialCapacity;

    if (pthread_mutex_init(&manager->lock, NULL) != 0) {
        printf("\n Mutex init failed");
        return -1; // returns error code for simplicity in this example
    }

    manager->records = malloc(sizeof(Record*) * initialCapacity);

    if (manager->records == NULL) {
        printf("\n Memory allocation failed");
        pthread_mutex_destroy(&manager->lock); // clean up after error
        return -1; // returns error code for simplicity in this example
    }

    return 0; // returns success for simplicity in this example
}

int addRecord(ArrayManager *manager, Record *record) {
    pthread_mutex_lock(&manager->lock);

    if (manager->count == manager->capacity) {
        size_t newCapacity = manager->capacity * 2; // increase capacity by a factor of 2

        Record **newRecords = realloc(manager->records, sizeof(Record*) * newCapacity);
        if (newRecords == NULL) {
            printf("\n Memory allocation failed");
            pthread_mutex_unlock(&manager->lock); // clean up after error
            return -1; // returns error code for simplicity in this example
        }

        manager->records = newRecords;
        manager->capacity = newCapacity;
    }

    manager->records[manager->count] = record;
    manager->count++;

    pthread_mutex_unlock(&manager->lock);
    return 0; // returns success for simplicity in this example
}

Record *getRecord(ArrayManager *manager, size_t index) {
    if (index >= manager->count) {
        printf("\n Invalid index");
        return NULL; // handle error case as you see fit
    }

    pthread_mutex_lock(&manager->lock);
    Record *record = manager->records[index];
    record->meta.lastAccessed = time(NULL); // update last accessed timestamp
    pthread_mutex_unlock(&manager->lock);

    return record;
}

void freeArrayManager(ArrayManager *manager) {
    for (size_t i = 0; i < manager->count; i++) {
        free(manager->records[i]->offsetValue); // clean up offset value memory
        free(manager->records[i]); // clean up record memory
    }

    free(manager->records); // clean up records array memory
    pthread_mutex_destroy(&manager->lock); // clean up mutex memory
}
```

