        (*records)[i].meta.lastaccessed_ts = now;
    }

    qsort(*records, numRecords, sizeof(record), compare); // sort records based on their int values

    fclose(fptr);
    return numRecords;
}

int compare(const void *a, const void *b) {
    record *r1 = (record *)a;
    record *r2 = (record *)b;
    return r1->val - r2->val;
}
```
The function `createRecords` allocates and initializes three arrays as per the given specifications. It uses `qsort` to sort the records based on their integer values in ascending order before returning them. It also checks for potential allocation failures, file read errors, or data mismatches. The DES cipher is configured using function pointers that are passed as parameters. This allows the user to specify which cryptographic operation mode they would like to use.
