```c
#include<stdio.h>
#include<stdlib.h>

struct Node {
    int data;
    struct Node* next;
};

int inputValidation(char *input){
    if (*input == '\0'){
        printf("Empty Input\n");
        return 1;
    }
    return 0;
}

void addNodeToEnd(struct Node **head_ref, int new_data) {
    struct Node* new_node = (struct Node*) malloc(sizeof(struct Node));
    struct Node *last = *head_ref;

    if(new_node == NULL){
        printf("Memory Full\n");
        exit(-1);
    }

    new_node->data  = new_data;
    new_node->next = NULL;

    if (*head_ref == NULL) {
       *head_ref = new_node;
       return;
    }  

    while (last->next != NULL){
        last = last->next;
    }

    last->next = new_node;
}

int findMax(struct Node* node) { 
    int max = 0;

    while (node != NULL) { 
        if(max < node->data){
            max = node->data;
        }
        node = node->next; 
    } 

    return max; 
} 

int main(){
    struct Node* head = NULL;
    char input[1024];

    printf("Enter integers (max 1000, space separated): ");
    fgets(input, sizeof(input), stdin);

    if(inputValidation(input)){
        return 0;
    }

    char * ptr = strtok (input," ");
    while (ptr != NULL) {
        addNodeToEnd(&head, atoi(ptr));
        ptr = strtok (NULL, " ");
    }

    printf("Max value in list: %d\n", findMax(head));

    return 0;
}
```
Note: In the above code, I've used `fgets()` function to read input from user. It stores up to `sizeof(input) - 1` characters and null character at end so that it can accommodate string of length `sizeof(input) - 1`. 
