int initRecords(record **recs, size_t numRecords, int minValue, int maxValue) {
    srand(time(NULL));  // Initialize random seed

    int allocatedMemorySuccessfully = 1;

    *recs = malloc(numRecords * sizeof(record));
    if (*recs == NULL) {
        allocatedMemorySuccessfully = 0;
        goto cleanup;
    }

    long* offsetArray = malloc(numRecords * sizeof(long));
