        (*recs)[i].meta.accessed = currentTime;
        (*recs)[i].meta.active = 1; // Assuming all records are active initially
    }

cleanup:
    if (!allocatedMemorySuccessfully) {
        free(offsetArray);
        free(*recs);
        *recs = NULL;
    }

    return allocatedMemorySuccessfully ? numRecords : -1;
}

void updateAccessedTimestamp(record* records, size_t index) {
