    FILE *file = fopen(filepath, "r");
    if (file == NULL) {
        perror("Error opening file");
        return -1;
    }

    // Allocate memory for offset and key arrays
    *offsets = malloc(sizeof(long) * 10000);
    if (*offsets == NULL) {
        perror("Memory allocation failed for offsets");
        return -1;
    }

    *keys = calloc(5000, sizeof(int)); // Initialize to zero
    if (*keys == NULL) {
        free(*offsets);
        perror("Memory allocation failed for keys");
        return -1;
    }

    // Allocate memory for records array
    *records = malloc(sizeof(Record*) * 5000);
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        perror("Memory allocation failed for records");
        return -1;
    }

    // Initialize records array elements to NULL
    memset(*records, 0, sizeof(Record*) * 5000);

    int num_records = 0;
    char buffer[256];

    while (fgets(buffer, sizeof(buffer), file) != NULL && num_records < 5000) {
        errno = 0;
        long value = strtol(buffer, NULL, 10);

        if (errno == ERANGE || value < -10000 || value > 10000) {
            continue; // Skip this line, not a valid integer in the specified range
        }

        // Allocate memory for new record and assign value
        Record *record = malloc(sizeof(Record));
        if (record == NULL) {
            perror("Memory allocation failed for records");
            break;
        }

        record->value = (int)value;
        (*records)[num_records++] = record;
    }

    fclose(file);
    return num_records;
}
