#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct User {
    int id;
    char key[32];
    char display_name[64];
    struct User *next;
} User;

User* add_user(User *head, int id, char *key, char *display_name) {
    User *new_user = malloc(sizeof(*new_user));
    if (new_user == NULL) {
        printf("Failed to allocate memory.\n");
        return head;
    }

    new_user->id = id;
    strncpy(new_user->key, key, sizeof(new_user->key) - 1);
    new_user->key[sizeof(new_user->key) - 1] = 0;

    // Ensure unique display name
    int i = 0;
    char new_display_name[64];
    strncpy(new_display_name, display_name, sizeof(new_display_name) - 1);
    new_display_name[sizeof(new_display_name) - 1] = 0;
    while (find_user_by_display_name(head, new_display_name)) {
        sprintf(new_display_name, "%s_%d", display_name, ++i);
    }
    strncpy(new_user->display_name, new_display_name, sizeof(new_user->display_name) - 1);
    new_user->display_name[sizeof(new_user->display_name) - 1] = 0;

    new_user->next = head;
    return new_user;
}

User* remove_user(User *head, int id) {
    if (head == NULL) {
        return NULL;
    } else if (head->id == id) {
        User *temp = head->next;
        free(head);
        return temp;
    } else {
        head->next = remove_user(head->next, id);
        return head;
    }
}

User* find_user_by_display_name(User *head, char *display_name) {
    while (head != NULL && strcmp(head->display_name, display_name)) {
        head = head->next;
    }
    return head;
}

void print_users(User *head) {
    int i = 0;
    while (head != NULL) {
        printf("User %d:\n", ++i);
        printf("\tID: %d\n", head->id);
        printf("\tKey: %s\n", head->key);
        printf("\tDisplay Name: %s\n", head->display_name);
        head = head->next;
    }
}

void free_users(User *head) {
    while (head != NULL) {
        User *temp = head;
        head = head->next;
        free(temp);
    }
}
```
In the above code, the `add_user` function adds a new user to the list. If there's already a user with the same display name, it generates a new unique one by appending an incrementing index. The `remove_user` function removes a user from the list and the `print_users` prints all users in the database.

Remember that this is a very basic implementation and does not cover many edge cases or advanced features like concurrent operations, caching, or logging mechanisms. It's recommended to use more robust data structures and algorithms for production code, especially when dealing with large datasets and multiple threads.
