        file = fopen(filename, "r");
        if (file == NULL) error("Failed to open file");

        for (long i = 0; i < num_records; ++i) 
            if (fscanf(file, "%ld %d", &offsets[i], &keys[i]) != 2) 
                error("Error reading from file");

        fclose(file);
    } else { // Initialize with random data
        for (long i = 0; i < num_records; ++i) {
            offsets[i] = rand() % MAX_KEY;
            keys[i] = rand() % MAX_KEY;
        }
    }

    // Ensure that the offset values are unique and do not overlap with any existing offsets.
    for (long i = 0; i < num_records; ++i) {
        long j = i + 1;
        while (j < num_records && offsets[j] <= offsets[i]) ++j;

        if (j != num_records) { // swap with next non-unique item
            int tm = keys[i];
            long tmp = offsets[i];

            keys[i] = keys[j];
            offsets[i] = offsets[j];
            keys[j] = tm;
            offsets[j] = tmp;
        } else { // no need to check the rest of the array because it's sorted now
            break;
        }
    }

    // Allocate memory for and initialize an array of 'record' structures.
    Record **records = malloc(num_records * sizeof(Record*));
    if (records == NULL) error("Memory allocation failed");

    for (long i = 0; i < num_records; ++i) {
        records[i] = malloc(sizeof(Record));
        if (records[i] == NULL) error("Memory allocation failed");

        // Check that all keys are within a specified range.
        if (keys[i] < 0 || keys[i] >= MAX_KEY) 
            error("Key out of range");

        records[i]->value = keys[i];
    }

    return records;
}
```
