['Here's an implementation in C that fits your description. It uses `pthread` for threading, `errno` for error handling and `assert()` for validation checks. Memory allocation is done with `malloc()` and `realloc()`. 

This code snippet doesn't cover all the details mentioned in the task due to its complexity but provides a good starting point:

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <errno.h>
#include <assert.h>

typedef struct {
    double latitude;
    double longitude;
} LocationData;

typedef struct {
    time_t ActivityTime;
    int UserID;
    LocationData LocationData;
} UserActivityRecord;

// A simple dynamic list structure
typedef struct {
    UserActivityRecord* data;
    size_t capacity;
    size_t count;
    double growthFactor;
    pthread_mutex_t lock; // for concurrency support
} DynamicList;

DynamicList* createList(size_t initialCapacity, double growthFactor) {
    DynamicList* list = malloc(sizeof(DynamicList));
    if (list == NULL) {
        perror("Failed to allocate memory for dynamic list");
        return NULL;
    }

    list->data = malloc(initialCapacity * sizeof(UserActivityRecord));
    if (list->data == NULL) {
        free(list);
        perror("Failed to allocate memory for dynamic list data");
        return NULL;
    }

    list->capacity = initialCapacity;
    list->count = 0;
    list->growthFactor = growthFactor;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void addRecord(DynamicList* list, UserActivityRecord record) {
    pthread_mutex_lock(&list->lock); // lock for thread safety

    if (list->count >= list->capacity) {
        size_t newCapacity = (size_t)(list->capacity * list->growthFactor);

        UserActivityRecord* temp = realloc(list->data, newCapacity * sizeof(UserActivityRecord));
        if (temp == NULL) {
            perror("Failed to allocate memory for dynamic list data during resize");
            pthread_mutex_unlock(&list->lock); // unlock before return to maintain safety
            return;
        }

        list->data = temp;
        list->capacity = newCapacity;
    }

    assert(list->count < list->capacity); 
    list->data[list->count++] = record;

    pthread_mutex_unlock(&list->lock); // unlock after adding the record
}
```
This snippet only provides a skeleton of your function. Further implementation will be needed to cover validation, error handling, logging and batch processing as well as integrate it with other code in your system. It is advised that you add proper tests for these functionalities to ensure they work correctly and improve the robustness of the program.
