char* stringPool[1024]; // pre-allocated strings pool
int usedStrings = 0; // number of used strings in the pool

// Allocate a new string from the pool and return its pointer.
char* allocString() {
    if(usedStrings >= 1024) { // If there is no free space left in the pool, double its size.
        stringPool = realloc(stringPool, sizeof(char*) * usedStrings * 2);
        if(!stringPool) return NULL;
    }
    stringPool[usedStrings] = malloc(100); // Allocate a new string of maximum length 100.
    if(!stringPool[usedStrings]) return NULL;
    return stringPool[usedStrings++];
}

// Free all allocated strings in the pool and reset usedStrings to zero.
void freeStringPool() {
    for(int i = 0; i < usedStrings; ++i) {
        free(stringPool[i]);
    }
    usedStrings = 0;
}

// Update last accessed timestamp of a specified record and increase its access count.
void updateRecord(Record *record, time_t currentTime) {
    record->metadata.lastAccessedTimestamp = currentTime;
    ++record->accessCount;
}

