    if(*offsets == NULL){
        printf("Memory not allocated.\n"); 
        exit(0); 
    }

    *keys = (int*)malloc(sizeof(int)*size);
    if(*keys == NULL) {
        printf("Memory not allocated.\n"); 
        exit(0); 
    }

    *records = (record*)malloc(sizeof(record)*size);
    if(*records == NULL) {
        printf("Memory not allocated.\n"); 
        exit(0); 
    }
}

int main(int argc, char* argv[]) {
    FILE *file;
    char line[128];
    long size = 0;
    int range_low = -1000, range_high = 1000; 

    srand(time(NULL));

    if (argc == 1 || (argc > 1 && strcmp(argv[1], "--help") == 0)) {
        printf("Usage: %s [-c] [-o output_file] [input_file]\n", argv[0]);
        return 1;
    }

    if (argc > 2) {
        file = fopen(argv[argc - 1], "r");

        if (file == NULL) {
            printf("Error opening the file.\n");
            return 0;
        }

        while (fgets(line, sizeof line, file)) ++size;
        fclose(file);

        printf("Number of lines: %ld\n", size);
    } else {
        printf("No input file provided.\n");
        return 1;
    }

    long *offsets = NULL;
    int *keys = NULL;
    record* records = NULL;
    allocate_memory(&offsets, &keys, &records, size);

    for (long i = 0; i < size; ++i) {
        offsets[i] = rand();
        keys[i] = rand() % (range_high - range_low + 1) + range_low;
        records[i].value = keys[i];
    }

    free(offsets);
    free(keys);
    free(records);

    return 0;
}
```
In the code above, dynamic memory for offsets, keys and records is allocated using the `allocate_memory` function. Then a loop assigns random values to each record's int field by setting its value equal to a randomly generated key from within the specified range. The dynamically allocated memory is then freed before the program ends.
']

