["Here's an example of how you might tackle this in C, implementing the search functionality using hash tables. This example includes bounds checking and ensures memory allocation checks are performed before usage. 

This implementation assumes that key values will be in a reasonable range (0-100,000), but it doesn't check for overflows or underflows on the record size. The hash table resizes when it reaches 75% capacity to minimize collisions and provide faster lookup times.

```c
#include <stdlib.h>
#define MAX_RECORDS 100000
#define KEY_RANGE 100000
#define RESIZE_THRESHOLD 75
typedef struct Record {
    int key;
    int value;
} Record;

typedef struct HashTable {
    Record **records;
    int size;
    int count;
} HashTable;

HashTable *create_table(int size) {
    HashTable *table = malloc(sizeof(HashTable));
    if (table == NULL) {
        return NULL;
    }

    table->records = calloc(size, sizeof(Record*));
    if (table->records == NULL) {
        free(table);
        return NULL;
    }

    table->size = size;
    table->count = 0;
    return table;
}

void resize_table(HashTable *table, int newSize) {
    Record **oldRecords = table->records;
    int oldSize = table->size;

    table->records = calloc(newSize, sizeof(Record*));
    if (table->records == NULL) {
        free(oldRecords);
        return;
    }

    for (int i = 0; i < oldSize; i++) {
        Record *record = oldRecords[i];
        if (record != NULL) {
            insert_into_table(table, record);
            free(record);
        }
    }

    table->size = newSize;
    free(oldRecords);
}

void insert_into_table(HashTable *table, Record *record) {
    int index = record->key % table->size;
    while (table->records[index] != NULL) {
        index = (index + 1) % table->size;
    }

    table->records[index] = record;
    table->count++;

    if ((float) table->count / table->size * 100 > RESIZE_THRESHOLD) {
        resize_table(table, table->size * 2);
    }
}

Record *find_record(HashTable *table, int key) {
    if (key < 0 || key >= KEY_RANGE) {
        return NULL;
    }

    int index = key % table->size;
    while (table->records[index] != NULL) {
        if (table->records[index]->key == key) {
            return table->records[index];
        }

        index = (index + 1) % table->size;
    }

    return NULL;
}
```
To use this code, you would create a hash table with `create_table`, insert records into the table with `insert_into_table`, and find a record by key with `find_record`. Please note that dynamic memory management is handled manually in this example and may not be suitable for all scenarios. This solution assumes an initial size of 100000 and a resize factor of 2x when the hash table exceeds 75% capacity, which might need to be adjusted based on your specific use case. Also, it's important to free memory manually once you're done using it (e.g., `free` any allocated records or tables).
"]

