["Here's a basic implementation of what you asked for using POSIX threading and lock-based synchronization mechanisms. This version does not include error checking, as I wanted to keep the code concise for simplicity. You can easily add it yourself.

```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    double value;
    char* id;
} data_entry;

typedef struct {
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    data_entry** entries;
} data_array;

data_array* create_array(size_t initialCapacity) {
    data_array* array = malloc(sizeof(data_array));
    if (array == NULL) return NULL;

    array->capacity = initialCapacity;
    array->count = 0;
    pthread_mutex_init(&array->mutex, NULL);
    array->entries = malloc(initialCapacity * sizeof(data_entry*));

    return array;
}

void free_array(data_array* array) {
    for (size_t i = 0; i < array->count; ++i) {
        free(array->entries[i]->id);
        free(array->entries[i]);
    }

    pthread_mutex_destroy(&array->mutex);
    free(array->entries);
    free(array);
}

void add_entry(data_array* array, double value, const char* id) {
    pthread_mutex_lock(&array->mutex);

    // Check if we need to resize the array
    if (array->count == array->capacity) {
        data_entry** newEntries = realloc(array->entries, 2 * array->capacity * sizeof(data_entry*));

        if (newEntries != NULL) {
            array->entries = newEntries;
            array->capacity *= 2;
        } else {
            pthread_mutex_unlock(&array->mutex);
            return; // Could not resize, abort
        }
    }

    data_entry* entry = malloc(sizeof(data_entry));
    if (entry != NULL) {
        entry->value = value;

        char* idCopy = malloc(strlen(id) + 1); // Allocate space for the string and copy it
        if (idCopy == NULL) return; // Could not allocate memory, abort

        strcpy(idCopy, id);
        entry->id = idCopy;
    } else {
        pthread_mutex_unlock(&array->mutex);
        return; // Could not allocate memory for the new entry, abort
    }

    array->entries[array->count++] = entry;
    pthread_mutex_unlock(&array->mutex);
}

void update_entry(data_array* array, const char* id, double value) {
    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->count; ++i) {
        if (!strcmp(array->entries[i]->id, id)) { // Compare strings
            array->entries[i]->value = value;
            break;
        }
    }

    pthread_mutex_unlock(&array->mutex);
}
```
In this code, we use a lock to protect the data structure from concurrent access. We also dynamically resize our array as needed using `realloc`. Error checking and handling for memory allocation failures is omitted in this simple example, but you could easily add it yourself.
"]

