['Here is a simplified example that demonstrates some of the key aspects you mentioned like thread safety, error handling and dynamic resizing using C11 threading library and POSIX mutexes. Note that this is a complex task with many moving parts so implementing it in one go without a proper design review or further refinements will be difficult.

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    double latitude;
    double longitude;
} LocationData;

typedef struct {
    int userId;
    time_t activityTime;
    LocationData location;
} UserActivityRecord;

typedef struct {
    UserActivityRecord* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} ActivityList;

#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 2

static void check_error(int ret, const char* msg) {
    if (ret != 0) {
        perror(msg);
        exit(EXIT_FAILURE);
    }
}

ActivityList* create_activity_list() {
    ActivityList* list = malloc(sizeof(ActivityList));
    check_error((list == NULL), "malloc failed");

    list->records = calloc(INITIAL_CAPACITY, sizeof(UserActivityRecord));
    check_error((list->records == NULL), "calloc failed");

    list->capacity = INITIAL_CAPACITY;
    list->size = 0;

    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void add_activity(ActivityList* list, UserActivityRecord record) {
    pthread_mutex_lock(&list->lock);

    if (list->size == list->capacity) {
        list->records = realloc(list->records, sizeof(UserActivityRecord) * list->capacity * GROWTH_FACTOR);
        check_error((list->records == NULL), "realloc failed");

        list->capacity *= GROWTH_FACTOR;
    }

    list->records[list->size++] = record;

    pthread_mutex_unlock(&list->lock);
}

void destroy_activity_list(ActivityList* list) {
    free(list->records);
    pthread_mutex_destroy(&list->lock);
    free(list);
}
``` 

This is just a starting point. Each additional feature you described would require further investigation into how to implement it, which might include data synchronization with external data sources, error handling for out of memory or invalid input conditions, and more complex logic for throttling and geofencing validation.
