["Sure, here's how you can implement this in C:

```c
#include <stdlib.h>

typedef struct node 
{
    int value;
    struct node *next;
} Node;

Node* createNode(int value) 
{
    Node *new_node = malloc(sizeof(Node));

    if (new_node == NULL) 
    {
        // handle memory allocation error
        return NULL;
    }

    new_node->value = value;
    new_node->next = NULL;

    return new_node;
}

void insertNode(Node** head, int value) 
{
    Node *new_node = createNode(value);

    if (new_node == NULL) 
    {
        // handle memory allocation error
        return;
    }

    new_node->next = *head;
    *head = new_node;
}

int searchNode(Node* head, int value) 
{
    Node *current = head;
    int index = 0;

    while (current != NULL) 
    {
        if (current->value == value) 
        {
            return index;
        }

        current = current->next;
        index++;
    }

    // node not found
    return -1;
}

void freeList(Node* head) 
{
    Node *current;

    while (head != NULL) 
    {
        current = head;
        head = head->next;

        // release memory for the node
        free(current);
    }
}
```
In this code, `createNode` function is used to dynamically allocate a new `Node`. If allocation fails (i.e., it returns NULL), it will return NULL and handle the error at the calling function. In a real-world scenario, you might want to log or throw an exception instead of returning immediately in case of an error.

