['Here is a solution using `stdlib.h` and `stdio.h` for memory allocation, error handling, and random number generation. This code is not thread-safe because C standard library does not provide thread safe versions of these functions. Mutexes can be used to make it thread safe which is beyond the scope of this question.

```c
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <errno.h>
#include <time.h>

typedef struct {
    int value;
} record;

record* create_records(size_t size, int minVal, int maxVal) {
    if (size <= 0 || minVal > maxVal) {
        syslog(LOG_ERR, "Invalid input parameters");
        return NULL;
    }

    srand((unsigned int) time(NULL)); // Seed the random number generator. 

    // Allocate memory for arrays
    int* keys = (int*) malloc(sizeof(int) * size);
    if (!keys) {
        syslog(LOG_ERR, "Error allocating memory for keys: %s", strerror(errno));
        return NULL;
    }

    long* offsets = (long*) malloc(sizeof(long) * size);
    if (!offsets) {
        syslog(LOG_ERR, "Error allocating memory for offsets: %s", strerror(errno));
        free(keys); // Free allocated memory
        return NULL;
    }

    record* records = (record*) malloc(sizeof(record) * size);
    if (!records) {
        syslog(LOG_ERR, "Error allocating memory for records: %s", strerror(errno));
        free(keys); // Free allocated memory
        free(offsets); // Free allocated memory
        return NULL;
    }

    // Initialize arrays
    for (size_t i = 0; i < size; ++i) {
        keys[i] = rand();
        offsets[i] = rand();
        records[i].value = minVal + rand() % (( maxVal + 1 ) - minVal); // random value within specified range
    }

    // Free allocated memory
    free(keys);
    free(offsets);

    return records;
}
```
