    int *keys = malloc(sizeof(int) * size);
    if (offsets == NULL || keys == NULL) {
        free(offsets);
        free(keys);
        return -1; // Return error code for memory allocation failure
    }

    // Allocate memory for records array
    Record* recs = malloc(sizeof(Record) * size);
    if (recs == NULL) {
        free(offsets);
        free(keys);
        return -1; // Return error code for memory allocation failure
    }

    // Initialize arrays and records
    srand(time(NULL));  // Seed the random number generator
    for (size_t i = 0; i < size; ++i) {
        offsets[i] = rand(); // Set a random offset value
        keys[i] = rand();   // Set a random key value
        recs[i].value = keys[i];    // Set the record's int field to the corresponding key value
        recs[i].offset = &offsets[i];  // Set the record's offset pointer to the array element
        recs[i].metadata.created = time(NULL); // Initialize creation timestamp
        recs[i].metadata.lastAccessed = 0;    // Initialize last accessed timestamp as zero
    }

    *records = recs;  // Assign the records pointer to the output parameter

    return size;  // Return the number of successfully created records
}

void freeMemory(Record* records) {
    if (records != NULL) {
        free((long*)records[0].offset);   // Free offsets array
        free(&records[0].value);  // Free keys array
        free(records);    // Free records array
    }
}
