typedef struct {
    long timestamp;
    int severity_level;
    char *message;
} log_entry;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void* allocate_logs(size_t num_entries) {
    // Error checking and initializing long offset values array
    long *offsets = (long*) malloc(num_entries * sizeof(*offsets));
    if (!offsets) return NULL;

    srand((unsigned int) time(NULL));

    for (size_t i = 0; i < num_entries; ++i) {
        offsets[i] = rand() % 1000; // Random values from 0 to 999
    }

    // Error checking and initializing int keys array
    int *keys = (int*) malloc(num_entries * sizeof(*keys));
    if (!keys) {
        free(offsets);
        return NULL;
    }

    for (size_t i = 0; i < num_entries; ++i) {
        keys[i] = rand() % 6; // Random values from 0 to 5
    }

    // Error checking and initializing log_entry structures array
    log_entry *logs = (log_entry*) malloc(num_entries * sizeof(*logs));
    if (!logs) {
        free(offsets);
        free(keys);
        return NULL;
    }

    for (size_t i = 0; i < num_entries; ++i) {
        logs[i].timestamp = offsets[i];
        logs[i].severity_level = keys[i];

        // Allocate and initialize a string for each log entry
        logs[i].message = (char*) malloc(1024);
        if (!logs[i].message) {
            free(offsets);
            free(keys);

            // Free previously allocated memory
            for (size_t j = 0; j < i; ++j) {
                free(logs[j].message);
            }
            free(logs);

            return NULL;
        }
    }

    pthread_mutex_lock(&lock); // Lock for thread safety

    // Memory management with dynamic allocation
    void* mem = malloc(sizeof(*offsets) * num_entries + sizeof(*keys) * num_entries + sizeof(*logs) * num_entries);
    if (!mem) {
        pthread_mutex_unlock(&lock); // Unlock in case of error

        free(offsets);
        free(keys);

        for (size_t i = 0; i < num_entries; ++i) {
            free(logs[i].message);
        }
        free(logs);

        return NULL;
    }

    pthread_mutex_unlock(&lock); // Unlock once memory is allocated

    memcpy(mem, offsets, sizeof(*offsets) * num_entries);
    memcpy((char*) mem + sizeof(*offsets) * num_entries, keys, sizeof(*keys) * num_entries);
    memcpy((char*) mem + (sizeof(*offsets) * num_entries + sizeof(*keys) * num_entries), logs, sizeof(*logs) * num_entries);

    // Free intermediate allocations to minimize memory fragmentation
    free(offsets);
    free(keys);
    for (size_t i = 0; i < num_entries; ++i) {
        free(logs[i].message);
    }
    free(logs);

    return mem;
}

void deallocate_logs(void *mem) {
    pthread_mutex_lock(&lock); // Lock for thread safety
    free(mem); // Free allocated memory
    pthread_mutex_unlock(&lock); // Unlock after memory is freed
}
```

This code dynamically allocates memory for and initializes your arrays. It also handles error checking to ensure that all allocations are successful. The `deallocate_logs` function, on the other hand, frees up the allocated memory when you're done with it. Finally, the use of a mutex for thread safety ensures that concurrent access from multiple threads is managed in an effective way.
"]

