#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} Record;

Record** allocate_memory(long* offsets, int size, int minValue, int maxValue) {
    // Validation of input parameters
    if (size <= 0 || minValue > maxValue) {
        return NULL;
    }

    srand(time(NULL)); 

    Record** records = malloc(size * sizeof(Record*));
    if (!records) {
        perror("Memory allocation error");
        return NULL;
    }

    for (int i = 0; i < size; i++) {
        records[i] = malloc(sizeof(Record));
        if (!records[i]) {
            // Free previously allocated memory on error
            for (--i; i >= 0; --i)
                free(records[i]);
            free(records);

            perror("Memory allocation error");
            return NULL;
        }

        records[i]->value = minValue + rand() % ((maxValue + 1) - minValue);
    }

    return records;
}
