#include <pthread.h>
#include <stdlib.h>
#include <assert.h>

typedef struct {
    int value;
} record_t;

long* offsets = NULL;
int* keys = NULL;
record_t** records = NULL;
size_t size = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void allocate_resources(size_t sz) {
    assert(sz > 0);

    offsets = (long*)calloc(sz, sizeof(long));
    keys = (int*)malloc(sz * sizeof(int));
    records = (record_t**)malloc(sz * sizeof(record_t*));
    size = sz;

    assert(offsets != NULL && keys != NULL && records != NULL);
}

void initialize_resources() {
    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < size; ++i) {
        offsets[i] = rand();  // optimize this line for performance

        keys[i] = rand() % RAND_MAX + 1;  // random value in a given range

        records[i] = (record_t*)malloc(sizeof(record_t));
        assert(records[i] != NULL);
        records[i]->value = keys[i];
    }

    pthread_mutex_unlock(&mutex);
}

void deinitialize() {
    free(offsets);
    free(keys);
    for (size_t i = 0; i < size; ++i) {
        free(records[i]);
    }
    free(records);
}
