int compare(const void *a, const void *b) {
    long offset_a = ((long *)a)[0];
    long offset_b = ((long *)b)[0];
    return (offset_a > offset_b) - (offset_a < offset_b);
}

void sort_records(Record **records, long *offsets, int size) {
    qsort((void *)offsets, size, sizeof(long), compare);

    Record **temp = malloc(sizeof(Record *) * size);
    for (int i = 0; i < size; ++i) temp[i] = &records[(int)((offsets + i)->value)][0];
    memcpy((void *)records, (const void *)temp, sizeof(Record *) * size);
    free(temp);
}

void allocate_and_initialize(FILE *dataSource, Record ***recordsPtr, long **offsetsPtr, int **keysPtr, int size) {
    long *offsets = malloc(sizeof(long) * size);
    for (int i = 0; i < size; ++i) fscanf(dataSource, "%ld", offsets + i);

    Record **records = malloc(sizeof(Record *) * size);
    int *keys = malloc(sizeof(int) * size);
    for (int i = 0; i < size; ++i) {
        records[i] = malloc(sizeof(Record));
        fscanf(dataSource, "%d", keys + i);
        fscanf(dataSource, "%d", &records[i]->value);
    }

    *offsetsPtr = offsets;
    *keysPtr = keys;
    *recordsPtr = records;
}
