typedef struct {
    long* offsets;
    int* keys;
    Record* records;
    size_t n, keyRangeStart, keyRangeEnd;
    pthread_mutex_t lock;
} DataBuffer;

DataBuffer* initBuffers(size_t n, size_t keyRangeStart, size_t keyRangeEnd) {
    if (n <= 0 || keyRangeStart >= keyRangeEnd) return NULL;  // invalid parameters

    DataBuffer *buffer = malloc(sizeof(DataBuffer));
    buffer->offsets = malloc(n*sizeof(long));
    buffer->keys = calloc(keyRangeEnd - keyRangeStart + 1, sizeof(int));
    buffer->records = malloc(n*sizeof(Record));
    pthread_mutex_init(&buffer->lock, NULL);

    if (buffer->offsets == NULL || buffer->keys == NULL || buffer->records == NULL) {
        fprintf(stderr, "Memory allocation failure\n");
        freeBuffers(buffer);  // cleanup
        return NULL;
    }

    for (size_t i = 0; i < n; ++i) {
        buffer->offsets[i] = random() % LONG_MAX;
        int key = keyRangeStart + rand()/(RAND_MAX/keyRangeEnd + 1); // random in range [start, end]
        buffer->keys[key - keyRangeStart] = 1;
        buffer->records[i].value = (int)random(); 
    }

    return buffer;
}

void freeBuffers(DataBuffer* buffer) {
    if (buffer == NULL) return;
    pthread_mutex_destroy(&buffer->lock); // cleanup
    free(buffer->offsets);
    free(buffer->keys);
    free(buffer->records);
    free(buffer);
}
