```c
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

// Static buffers for offsets and keys
long offsets[1024];
int *keys = NULL;
size_t keySize = 0;

record *records = NULL;
size_t recordCount = 0;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initialize(unsigned int count, size_t range) {
    // Validate inputs
    if (count == 0 || range == 0 || range > INT_MAX) {
        return;
    }

    pthread_mutex_lock(&lock);

    // Resize keys buffer
    int *newKeys = realloc(keys, count * sizeof(*newKeys));
    if (newKeys == NULL && count != 0) {
        pthread_mutex_unlock(&lock);
        return;
    }
    keys = newKeys;
    keySize = count;

    // Resize records array
    record *newRecords = realloc(records, count * sizeof(*newRecords));
    if (newRecords == NULL && count != 0) {
        free(keys);
        keys = NULL;
        pthread_mutex_unlock(&lock);
        return;
    }
    records = newRecords;
    recordCount = count;

    // Seed random number generator
    srand((unsigned int) time(NULL));

    // Initialize offsets and keys
    for (size_t i = 0; i < keySize; ++i) {
        offsets[i] = rand();
        keys[i] = rand() % range;
    }

    // Initialize records
    for (size_t i = 0; i < recordCount; ++i) {
        records[i].value = rand() % range;
    }

    pthread_mutex_unlock(&lock);
}

void destroy(void) {
    pthread_mutex_lock(&lock);

    free(keys);
    keys = NULL;

    free(records);
    records = NULL;

    keySize = 0;
    recordCount = 0;

    pthread_mutex_unlock(&lock);
}
```
The `initialize` function is thread-safe and ensures that memory resources are properly allocated, initialized and synchronized. The `destroy` function frees up the allocated memory and sets the sizes to zero. 

This code doesn't handle integer overflow for the sake of simplicity but you might want to add checks or use a different random number generator in such scenarios. Note that reallocating on every iteration is not efficient, it would be better to batch the allocation if possible. 

