int initTransactions(Transaction** transactions, size_t num_transactions) {
    srand((unsigned int)time(NULL));

    *transactions = (Transaction*) malloc(num_transactions * sizeof(Transaction));
    if (*transactions == NULL) return -1; // memory allocation failed

    for(size_t i = 0; i < num_transactions; ++i) {
        long valueRangeLow  = 50;  // Adjust as needed
        long valueRangeHigh = 100; // Adjust as needed
        int stringLength    = 10;  // Adjust as needed

        (*transactions)[i].value = (rand() % (valueRangeHigh - valueRangeLow + 1)) + valueRangeLow;

        for(int j = 0; j < stringLength-1; ++j) {
            int isDigit = rand()%2; // Randomly generate a digit or letter
            if(isDigit){
                (*transactions)[i].item[j] = '0' + (rand() % 10);
            } else{
                int isUppercase = rand()%2;
                if(isUppercase) {
                    (*transactions)[i].item[j] = 'A' + (rand() % ('Z'-'A'));
                } else {
                    (*transactions)[i].item[j] = 'a' + (rand() % ('z'-'a'));
                }
            } 
        }
        (*transactions)[i].item[stringLength-1] = 0; // Null terminator

        int countRangeLow  = 5;    // Adjust as needed
        int countRangeHigh = 20;   // Adjust as needed
        (*transactions)[i].count = (rand() % (countRangeHigh - countRangeLow + 1)) + countRangeLow;

        time(&(*transactions)[i].timestamp); // get current timestamp
    }

    return 0; // success
}
