#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    double latitude;
    double longitude;
} LocationData;

typedef struct {
    time_t activityTime;
    int userID;
    LocationData location;
} UserActivityRecord;

typedef struct {
    pthread_mutex_t mutex;
    size_t capacity;
    size_t count;
    UserActivityRecord *records;
} UserActivityList;

UserActivityList* createList(size_t initialCapacity) {
    UserActivityList* list = malloc(sizeof(UserActivityList));
    if (!list) return NULL;

    list->capacity = initialCapacity;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    list->records = malloc(initialCapacity * sizeof(UserActivityRecord));
    if (!list->records) {
        free(list);
        return NULL;
    }

    return list;
}

void destroyList(UserActivityList* list) {
    pthread_mutex_destroy(&list->mutex);
    free(list->records);
    free(list);
}

int addRecord(UserActivityList* list, UserActivityRecord record) {
    if (record.location.latitude < -90 || record.location.latitude > 90 
        || record.location.longitude < -180 || record.location.longitude > 180) {
        return -1; // Invalid location data
    }

    pthread_mutex_lock(&list->mutex);

    if (list->count == list->capacity) {
        size_t newCapacity = list->capacity * 2;
        UserActivityRecord* newRecords = realloc(list->records, newCapacity * sizeof(UserActivityRecord));

        if (!newRecords) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Out of memory
        }

        list->capacity = newCapacity;
        list->records = newRecords;
    }

    list->records[list->count++] = record;
    pthread_mutex_unlock(&list->mutex);
    return 0; // Success
}
```
