void allocateAndInitialize(long *offset, size_t offsetSize, 
                           int *key, size_t keySize, Record **records, size_t recordSize) {
    // Ensure sizes are valid
    if (offsetSize < 1 || keySize < 1 || recordSize < 1) {
        printf("Error: Invalid input size\n");
        return;
    }

    pthread_mutex_lock(&lock);  // Lock the mutex for thread-safety

    *offset = malloc(offsetSize * sizeof(long));
    if (*offset == NULL) {
      printf("Error: Memory allocation failed\n");
      return;
    }

    srand(time(0));  // Seed random number generator
    for (size_t i = 0; i < offsetSize; ++i) {
        *offset[i] = rand();
    }

    *key = malloc(keySize * sizeof(int));
    if (*key == NULL) {
      printf("Error: Memory allocation failed\n");
      free(*offset);  // Free previously allocated memory on failure
      return;
    }

    for (size_t i = 0; i < keySize; ++i) {
        *key[i] = rand();
    }

    *records = malloc(recordSize * sizeof(Record));
