#define INITIAL_CAPACITY 10
#define RESIZE_THRESHOLD 80

typedef struct {
    int value;
} Record;

void handleError(const char* errorMessage) {
    fprintf(stderr, "%s\n", errorMessage);
    exit(EXIT_FAILURE);
}

int main() {
    long* offsetArray = (long*)malloc(INITIAL_CAPACITY * sizeof(long));
    if(!offsetArray) handleError("Allocation failed for offsetArray");

    int* keyArray = (int*)calloc(INITIAL_CAPACITY, sizeof(int));
    if(!keyArray) handleError("Allocation failed for keyArray");

    Record* recordArray = (Record*)malloc(INITIAL_CAPACITY * sizeof(Record));
    if(!recordArray) handleError("Allocation failed for recordArray");

    FILE* file = fopen("data.txt", "r");
    if (!file) handleError("File opening failed");

    long capacity = INITIAL_CAPACITY;
    int size = 0;
    while (fscanf(file, "%ld %d %d", &offsetArray[size], &keyArray[size], &recordArray[size].value) == 3) {
        if ((++size + 1) * 100 / capacity >= RESIZE_THRESHOLD) {
            capacity *= 2;

            offsetArray = (long*)realloc(offsetArray, capacity * sizeof(long));
            if(!offsetArray) handleError("Allocation failed for resized offsetArray");

            keyArray = (int*)realloc(keyArray, capacity * sizeof(int));
            if(!keyArray) handleError("Allocation failed for resized keyArray");

            recordArray = (Record*)realloc(recordArray, capacity * sizeof(Record));
            if(!recordArray) handleError("Allocation failed for resized recordArray");
