    for (int i = 0; i < size; ++i) {
        int minVal = keyArray[i] - 5, maxVal = keyArray[i] + 5;
        recordArray[i].value = rand() % (maxVal - minVal + 1) + minVal; // Random value within range
    }

    fclose(file);
    free(offsetArray);
    free(keyArray);
    free(recordArray);
}
