['```C
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    int value;
} Record;

void loadData(const char *filenames[], size_t fileCount, long **offsets, int **keys, Record ***records) {
    size_t capacity = 1024; // Initial capacity
    size_t count = 0;     // Number of entries in arrays

    *offsets = malloc(capacity * sizeof(**offsets));
    if (!*offsets) { perror("Failed to allocate offsets array"); return; }

    *keys = malloc(capacity * sizeof(**keys));
    if (!*keys) { perror("Failed to allocate keys array"); free(*offsets); return; }

    *records = malloc(capacity * sizeof(***records));
    if (!*records) { perror("Failed to allocate records array"); free(*offsets); free(*keys); return; }

    srand(time(NULL)); // Seed random number generator

    for (size_t i = 0; i < fileCount; ++i) {
        FILE *file = fopen(filenames[i], "r");
        if (!file) { perror("Failed to open file"); continue; }

        char line[256]; // Buffer for lines from file
        while (fgets(line, sizeof(line), file)) {
            long offset;
            int key, value;

            if (sscanf(line, "%ld,%d,%d", &offset, &key, &value) != 3) {
                perror("Failed to parse line");
                continue;
            }

            // Resize arrays if necessary
            if (count >= capacity * 0.8) {
                capacity *= 2;
                *offsets = realloc(*offsets, capacity * sizeof(**offsets));
                *keys = realloc(*keys, capacity * sizeof(**keys));
                *records = realloc(*records, capacity * sizeof(***records));
            }

            // Add data to arrays
            (*offsets)[count] = offset;
            (*keys)[count] = key;
            (*records)[count]->value = value;
            ++count;
        }
    }
}
```

In this implementation, we dynamically allocate and resize the three arrays based on the number of entries (`count`). When we reach 80% capacity, we double the size of each array to ensure that we don't have to reallocate memory frequently. This approach should provide a good balance between performance and memory usage.

