        records[i].float_value = ((float)rand() / (float)(RAND_MAX)) * 20.0f - 10.0f; // random float value between -10.0 to 10.0

        // Allocate and initialize a string field with a randomly generated alphanumeric string of length 10.
        records[i].string = malloc(11 * sizeof(char)); // +1 for null terminator
        if (records[i].string == NULL) {
