}

// Function to sort records based on their integer values in ascending order.
void sort_records(data_record *records, int num_records) {
    for (int i = 0; i < num_records - 1; i++) {
        for (int j = i + 1; j < num_records; j++) {
            if (records[i].integer_value > records[j].integer_value) { // If the integer value of record[i] is greater than record[j], swap them.
                data_record temp = records[i];
                records[i] = records[j];
                records[j] = temp;
            }
        }
    }
}

