int createSensors(double rangeStart, double rangeEnd, int numSensors, 
                  char **strings, int stringLen, 
                  SensorData **sensorData) {

    if (rangeStart >= rangeEnd || numSensors <= 0 || 
        strings == NULL || *strings == NULL || 
        sensorData == NULL) {
        return -1;
    }

    double *values = malloc(numSensors * sizeof(double));
    if (values == NULL) {
