int createAndInitializeArrays(long **offsets, int **keys, Record ***records, int numRecords) {
    srand(time(NULL));  // Seed the random number generator

    *offsets = malloc(numRecords * sizeof(long));
    if (*offsets == NULL) return -1;

    *keys = malloc(numRecords * sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        return -1;
    }

    *records = malloc(numRecords * sizeof(Record));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        return -1;
    }

    for (int i = 0; i < numRecords; ++i) {
        (*offsets)[i] = rand();  // Set offset value to random number
        (*keys)[i] = rand() % INT_MAX;  // Set key value to random int within range
        Metadata metadata = {time(NULL), time(NULL)};
        Record record = {rand(), &(*offsets)[i], metadata};
        (*records)[i] = record;
    }

    return 0;
}

int loadResourceBundleFromFile(const char* filename, int *numItems) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) return -1;

    fseek(file, 0L, SEEK_END);
    long size = ftell(file);
    rewind(file);
    *numItems = size / sizeof(int);  // Assume each item is an int

    fclose(file);
    return 0;
}

void quicksort(Record records[], int low, int high) {
   int i = low, j = high;
   Record pivot = records[(low + high) / 2];

   while (i <= j) {
      while (records[i].value < pivot.value) i++;
      while (records[j].value > pivot.value) j--;
      if (i <= j) {
         Record temp = records[i];
         records[i] = records[j];
         records[j] = temp;
         i++, j--;
      }
   }
   if (low < j) quicksort(records, low, j);
   if (i < high) quicksort(records, i, high);
}

int saveStateToFile(const char* filename, long *offsets, int *keys, Record **records, int numRecords) {
    FILE* file = fopen(filename, "w");
    if (file == NULL) return -1;

    for (int i = 0; i < numRecords; ++i) {
        fwrite(&offsets[i], sizeof(long), 1, file);
        fwrite(&keys[i], sizeof(int), 1, file);
        fwrite(*records + i, sizeof(Record), 1, file);
    }

    fclose(file);
    return 0;
}
```

