        (*sensors)[i].value = min + scale * (max - min); /* [min, max] */
    }

    return 0;
}

int cleanupSensors(SensorData **sensors) {
    if (*sensors != NULL) free(*sensors);
    *sensors = NULL;
    return 0;
}

