2. Sorting an array of SensorData structs:

Here's a simple quickSort implementation for sorting your sensor data based on their float values in ascending order.

```c
void swap(SensorData* a, SensorData* b) {
    SensorData t = *a;
    *a = *b;
    *b = t;
}

int partition (SensorData arr[], int low, int high){
    float pivot = arr[high].value; 
    int i = (low - 1);

    for (int j = low; j <= high- 1; j++){
        if (arr[j].value < pivot) {
            i++;
            swap(&arr[i], &arr[j]);
        }
    }
    swap(&arr[i + 1], &arr[high]);

    return (i + 1);
}

void quickSort(SensorData arr[], int low, int high){
    if (low < high) {
        int pi = partition(arr, low, high);
        quickSort(arr, low, pi - 1);
        quickSort(arr, pi + 1, high);
    }
}
```

