```c
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct record {
    int value;
    struct record *nextRecord;
} Record;

typedef struct node {
    int value;
    struct node *nextNode;
    Record *record;
} Node;

int generateArrays(double **doubleArray, char ***charStringArray, Node ***nodeArray, Record ***recordArray, 
                   size_t arraySize, const int rangeMin, const int rangeMax) {

    srand((unsigned int)time(NULL)); // Seed the random number generator.

    *doubleArray = malloc(sizeof(**doubleArray) * arraySize);
    if (*doubleArray == NULL) return -1; // Memory allocation failure.

    *charStringArray = malloc(sizeof(**charStringArray) * arraySize);
    if (*charStringArray == NULL) { 
        free(*doubleArray);
        return -2; // Memory allocation failure.
    }

    *nodeArray = calloc(arraySize, sizeof(**nodeArray));
    if (*nodeArray == NULL) {
        free(*doubleArray);
        free(*charStringArray);
        return -3; // Memory allocation failure.
    } 

    *recordArray = malloc(sizeof(**recordArray) * arraySize);
    if (*recordArray == NULL) {
        free(*doubleArray);
        free(*charStringArray);
        free(*nodeArray);
        return -4; // Memory allocation failure.
    } 

    for (size_t i = 0; i < arraySize; ++i) {
        (*recordArray)[i] = malloc(sizeof(Record));

        if ((*recordArray)[i] == NULL) {
            // Memory allocation failure. Free all previously allocated memory and return an error code.
            for (size_t j = 0; j < i; ++j) free((*recordArray)[j]);

            free(*doubleArray);
            free(*charStringArray);
            free(*nodeArray);
            free(*recordArray);

            return -5; // Memory allocation failure.
        } 

        (*recordArray)[i]->value = rangeMin + rand() % (rangeMax - rangeMin + 1);
    } 

    // Link the records in a circular manner.
    for (size_t i = 0; i < arraySize; ++i) {
        if(i == 0){
            (*recordArray)[arraySize-1]->nextRecord = (*recordArray)[i];
        }else{
            (*recordArray)[i-1]->nextRecord = (*recordArray)[i];
        }
    } 

    return 0; // Success.
}
```

