    *fps = malloc(sizeof(double) * size);
    if (*fps == NULL) {
        pthread_mutex_unlock(&lock);
        return -1;
    }

    *keys = calloc(size, sizeof(int));
    if (*keys == NULL) {
        free(*fps);
        pthread_mutex_unlock(&lock);
        return -1;
    }

    *data = malloc(sizeof(data_entry) * size);
    if (*data == NULL) {
        free(*keys);
        free(*fps);
        pthread_mutex_unlock(&lock);
        return -1;
