        (*keys)[i] = rand();
        (*fps)[i] = ((double) rand()) / RAND_MAX * 10.0; // Random double between 0 and 10

        metadata *md = malloc(sizeof(metadata));
        if (md == NULL) {
            free(*data);
            free(*keys);
            free(*fps);
            pthread_mutex_unlock(&lock);
            return -1;
        }

        md->creation_timestamp = time(NULL);
        md->last_accessed_timestamp = 0;

        (*data)[i].value = (*keys)[i];
        (*data)[i].fp = &(*fps)[i];
        (*data)[i].md = md;
    }

    ++record_count;

    pthread_mutex_unlock(&lock);

    return record_count;
}
