    int value;
    Metadata metadata;
    long *offset_value;
    char* ip_address;
} Record;

int createRecords(char* hostname, int num_records, int min_range, int max_range, Record** records){
    srand(time(NULL));

    struct hostent *host = gethostbyname(hostname);
    if (host == NULL) {
        herror("gethostbyname");
        return -1;
    }

    char ip[INET6_ADDRSTRLEN];
    inet_ntop(AF_INET, host->h_addr_list[0], ip, sizeof(ip));

    *records = calloc(num_records, sizeof(Record));
    if(*records == NULL){
        perror("calloc");
        return -1;
    }

    int recordsCreated = 0;
    for (int i = 0; i < num_records; ++i) {
        (*records)[i].value = rand() % (max_range - min_range + 1) + min_range;

        Metadata metadata = {.ts = time(NULL)};
        (*records)[i].metadata = metadata;

        long* offset_value = malloc(sizeof(long));
        if (offset_value == NULL){
            perror("malloc");
            continue;
        }
        *offset_value = i * sizeof(Record);
        (*records)[i].offset_value = offset_value;

        char* ip_address = strdup(ip);
        if (ip_address == NULL){
            perror("strdup");
            free(offset_value);
            continue;
        }
        (*records)[i].ip_address = ip_address;

        recordsCreated++;
    }

    return recordsCreated;
}
```
