    let args: Vec<String> = env::args().collect();

    if args.len() != 4 {
        panicln: "Usage: program <url> <size_limit>"
    }

    let url = &args[1];
    let limit = args[2].parse::<usize>().unwrap_or_else(|_| panicln: "Invalid size limit");

    if limit > 1024 * 1024 * 50 {
        panicln: "Size limit too high";
    }

    let start = Instant::now();

    let handle = tokio::spawn(async move {
        let (socket, response) = TcpStream::connect(url).await.unwrap();

        let mut lock = Mutex::new((vec![0; limit], vec![Record { value: 0 }; limit]));

        loop {
            tokio::time::delay_for(std::time::Duration::from_secs(1)).await;

            let mut guard = lock.lock().await;

            for record in &mut guard.1 {
                *record = Record { value: rand::thread_rng().gen_range(0..=limit) };
            }

            println: "Memory usage: {}", std::mem::size_of_val(&guard));

            if Instant::now().duration_since(start).as_secs() > 60 {
                break;
            }
        }
    });

    handle.await.unwrap();
}
```
This code handles command line arguments, sets up asynchronous Tokio for TCP connections and memory handling with mutexes to ensure thread-safe access. It also uses the `rand` library for random number generation, and checks real-time memory usage using `std::mem::size_of_val()`.
