    srand(time(NULL));  // seeding random generator with current time

    for (size_t i = 0; i < numNodes; ++i) {
        Node *newNode = malloc(sizeof(*newNode));

        if (!newNode) {
            fprintf(stderr, "Memory allocation failed\n");
            return -1;  // Return error code on failure
        }

        newNode->value = rand() % (maxVal - minVal + 1) + minVal;
        newNode->string = malloc(sizeof(char) * 20);

        if (!newNode->string) {
            fprintf(stderr, "Memory allocation failed\n");
            free(newNode);  // Free allocated memory before returning on failure
            return -1;  // Return error code on failure
        }

        sprintf(newNode->string, "%d", newNode->value);
        time(&newNode->creationTime);
        newNode->lastAccessed = newNode->creationTime;
        newNode->next = *head;
        *head = newNode;  // Update head of the list
    }

    return numNodes;  // Return count of successfully created nodes
}

void updateLastAccess(Node *node) {
    if (node) {
        time(&node->lastAccessed);
    }
}

void freeList(Node **head) {
    Node *current = *head;

    while (current) {
        Node *temp = current;
        current = current->next;

        if (temp->string) {
            free(temp->string);  // Free memory allocated for string field
        }

        free(temp);  // Free node itself
