void saveToFile(const char *filename, void *ptr, size_t size) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        printf("Error opening file for writing.\n");
        exit(1);
    }

    if (fwrite(ptr, size, 1, fp) != 1) {
