["Here is a simple C function which dynamically allocates memory for three arrays: one for 'long' offset values, one for 'int' keys, and one for 'record' structures. It also includes sorting, allocation failure handling, and returns the count of successfully created records.

```c
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct {
    long creation_timestamp;
    long last_accessed_timestamp;
} metadata;

typedef struct {
    int value;
    long* offset;
    metadata meta;
} record;

int cmpfunc (const void * a, const void * b) {
   return ( (*(record*)a).value - (*(record*)b).value );
}

long create_records(int **keys, long **offsets, record ***records, int size, int range){
    srand((unsigned int) time(NULL));

    *keys = malloc(sizeof(int)*size);
    if(*keys == NULL) return -1; // memory allocation failure

    *offsets = malloc(sizeof(long)*size);
    if(*offsets == NULL){
        free(*keys);
        return -2; // memory allocation failure
    }

    *records = malloc(sizeof(record)*size);
    if(*records == NULL){
        free(*keys);
        free(*offsets);
        return -3; // memory allocation failure
    }

    long count = 0;
    for(int i=0; i<size; i++){
        (*keys)[i] = rand() % range;
        (*offsets)[i] = (long)i*sizeof(record);

        // initialize metadata
        metadata meta = {time(NULL), time(NULL)}; 

        (*records)[i].value = (*keys)[i];
        (*records)[i].offset = &((*offsets)[i]);
        (*records)[i].meta = meta;

        count++;
    }

    qsort(*records, size, sizeof(record), cmpfunc); // sort the records

    return count;
}
```

