#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <sys/socket.h>

typedef struct {
    time_t createTime;
    time_t accessTime;
} MetaData;

typedef struct {
    int value;
    long* offset;
    MetaData meta;
} Record;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void swap(Record *a, Record *b) {
    Record temp = *a;
    *a = *b;
    *b = temp;
}

void bubbleSort(Record arr[], int n) {
   for (int i = 0; i < n-1; i++)       
       for (int j = 0; j < n-i-1; j++) 
           if (arr[j].value > arr[j+1].value)
              swap(&arr[j], &arr[j+1]);
}

Record* createAndSortRecords(long* offsets, int numOffsets, int minVal, int maxVal){
    Record* records = malloc(sizeof(Record) * numOffsets);

    if (records == NULL){
        return NULL; // Allocation failure
    }

    for (int i = 0; i < numOffsets; ++i){
        pthread_mutex_lock(&mutex);

        records[i].value = minVal + rand() % ((maxVal + 1) - minVal);
        records[i].offset = &offsets[i];
        records[i].meta.createTime = time(NULL);
        records[i].meta.accessTime = time(NULL);

        pthread_mutex_unlock(&mutex);
    }

    bubbleSort(records, numOffsets);

    return records;
}

