<?php
class UserManager {
    private $db;
    private $mfaService;
    private $passwordValidator;
    private $auditTrailLogger;

    public function __construct(DatabaseDao $db, MFAService $mfaService, PasswordStrengthValidator $passwordValidator) {
        $this->db = $db;
        $this->mfaService = $mfaService;
        $this->passwordValidator = $passwordValidator;
        // Initialize AuditTrailLogger
    }

    public function updatePassword($userId, $newPassword, $oldHashedPassword) {
        $dbConnection = null;

        try {
            // Validate password strength
            $this->passwordValidator->validate($newPassword);

            // Open database connection and start transaction
            $dbConnection = $this->db->getConnection();
            $dbConnection->beginTransaction();

            // Verify that the old hashed password matches the one stored in the DB
            $storedHashedPassword = $this->db->fetchUserPassword($userId);
            if ($oldHashedPassword !== $storedHashedPassword) {
                throw new Exception('Invalid current password');
            }

            // Validate MFA
            $isMfaVerified = $this->mfaService->verify();
            if (!$isMfaVerified) {
                throw new Exception('MFA verification failed');
            }

            // Update password in DB
            $hashedNewPassword = password_hash($newPassword, PASSWORD_DEFAULT);
            $this->db->updateUserPassword($userId, $hashedNewPassword);

            // Log audit trail
            $this->auditTrailLogger->logUpdatePasswordEvent($userId, $oldHashedPassword, $newPassword);

            // Commit transaction
            $dbConnection->commit();
        } catch (Exception $e) {
            if ($dbConnection !== null) {
                $dbConnection->rollBack();
            }

            // Handle error
            throw new Exception('Failed to update password: ' . $e->getMessage());
        } finally {
            if ($dbConnection !== null) {
                $this->db->closeConnection($dbConnection);
            }
        }
    }
}
?>
```

