    pthread_mutex_unlock(&slidingWindow.lock);

    for(int i = 0; i < SENSOR_TYPES; ++i){
        double sum = 0;
        for(int j = slidingWindow.insertIndex - WINDOW_SIZE + 1; 
            j <= slidingWindow.insertIndex; 
