void* allocateAndInitialize(size_t size, int range) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        // Handle allocation error
    }

    totalMemoryUsage += size;  // Track memory usage

    for (int i = 0; i < size / sizeof(int); i++) {
        ((int*)ptr)[i] = rand() % range;  // Initialize with random values within given range
    }

    return ptr;
}

void freeAllocatedMemory(void* ptr, size_t size) {
    free(ptr);
    totalMemoryUsage -= size;  // Update memory usage tracking
}

Record* createRecords(size_t count, int range) {
    Record* records = malloc(count * sizeof(Record));

    for (int i = 0; i < count; i++) {
        records[i].value = rand() % range;  // Initialize with random values within given range

        pthread_mutex_lock(&mutex);  // Ensure thread-safety when accessing shared resources
        totalMemoryUsage += sizeof(Metadata);  // Track memory usage
        records[i].metadata = malloc(sizeof(Metadata));
