// Function to create node
int createNode(char** keys, double** values, int size, Node** nodes, char minCharRange, char maxCharRange, int maxNodes) {
    if (pthread_mutex_lock(&lock) != 0) {  // lock mutex
        printf("Error: Failed to acquire the lock\n");
        return -1;
    }

    // check if allocation exceeds limit
    if(size >= maxNodes){
       pthread_mutex_unlock(&lock);   // unlock mutex before returning
       return -2; 
    }

    Node* newNode = (Node*)malloc(sizeof(Node));  // allocate memory for new node

    if (newNode == NULL) {  // check allocation success
        pthread_mutex_unlock(&lock);   // unlock mutex before returning
        printf("Error: Failed to allocate memory\n");
        return -3;
    }

    newNode->value = minCharRange + rand() % (maxCharRange - minCharRange + 1);  // initialize node value with random char from given range

    int index = 0;  
    while(index < size && *nodes != NULL){
        nodes++;
        index++;
    }

    if(index == size) {
       pthread_mutex_unlock(&lock);   // unlock mutex before returning
       return -4; 
    }

    newNode->ptrToCharKey = keys[index];  
    newNode->ptrToDoubleValue = values[index];

    // Initialize the metadata for node
    time(&newNode->metadata.creationTime);
    newNode->metadata.lastAccessedTime = newNode->metadata.creationTime;

    *nodes++ = newNode;  // add new node to array of nodes

    printf("Successfully created a node\n");  
    pthread_mutex_unlock(&lock);  // unlock mutex before returning

    return index+1;  // return the number of successfully created nodes
}
