['Here is a simple solution written in C. This solution assumes that memory resources are limited, thus it dynamically allocates and frees records in small chunks, which should help avoid excessive fragmentation. Also, as external data sources are not provided, we assume they provide us with integers for our 'int' value and longs for the offset values:

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    time_t creationTime;
    time_t lastAccessedTime;
    int status;  // Assume '1' for active and '0' for inactive
} Metadata;

typedef struct {
    long* offsetValue;
    int value;
    Metadata metadata;
} Record;

int createRecords(Record** records, int count, long *offsets, int start_range, int end_range) {
    srand((unsigned)time(NULL));  // initialize random seed

    int chunkSize = 100;
    *records = (Record*)malloc(chunkSize * sizeof(Record));
    if (*records == NULL) {
        printf("Memory allocation failed!\n");
        return -1;
    }
    int numRecordsCreated = 0;

    for (int i=0; i<count/chunkSize + 1; ++i) {  // create chunks of records
        if(i > 0 && *records != NULL){  // realloc when not the first time
            *records = (Record*)realloc(*records, chunkSize * sizeof(Record));
            if (*records == NULL) {
                printf("Memory allocation failed!\n");
                free(records);
                return -1;
            }
        }

        for (int j=i*chunkSize; j<(i+1)*chunkSize && j<count; ++j){  // create records in the chunk
            (*records)[numRecordsCreated].value = start_range + rand() % ((end_range + 1) - start_range);

            if (offsets != NULL){
                (*records)[numRecordsCreated].offsetValue = offsets+j;  // Assume it's a one-to-one mapping between records and offsets
            } else {
                printf("Error: Offset values not provided.\n");
                return -1;
            }

            (*records)[numRecordsCreated].metadata.creationTime = time(NULL);
            (*records)[numRecordsCreated].metadata.lastAccessedTime = time(NULL);
            (*records)[numRecordsCreated].metadata.status = 1;  // Set status to active by default
            ++numRecordsCreated;
        }
    }

    return numRecordsCreated;
}
```
The function createRecords takes a pointer to the records array, the total count of records, the offset values array, and a range for randomly generating 'int' values. It allocates memory in chunks using realloc, which minimizes the amount of overall memory allocation needed. If any allocation fails, it frees all previously allocated memory before returning an error code. The function also uses time(NULL) to initialize and update the creation and last accessed times of each record.
']

