    int min, max;
    float (*randomFloat)(void);
    int (*randomInt)(int min, int max);
    char* (*toString)(void);
} RandomGenerator;

RandomGenerator createRandomGenerator(int min, int max) {
    srand((unsigned)time(NULL));

    RandomGenerator randomGen = {min, max, 
        []() -> float { return (float) rand() / RAND_MAX; }, 
        [](int min, int max) -> int { return rand() % (max - min + 1) + min; }};
    randomGen.toString = &toString(randomGen);

    return randomGen;
}

char* toString(RandomGenerator randomGen){
    char buffer[50];
    sprintf(buffer, "Min: %d, Max: %d", randomGen.min, randomGen.max);
    return strdup(buffer);
}

Record *initializeRecords(long size, RandomGenerator randomGen) {
    long* offset = malloc(sizeof(long) * size);
    int* keys = calloc(size, sizeof(int));
    Record* records = malloc(sizeof(Record) * size);

    if (!offset || !keys || !records) {
        free(offset);
        free(keys);
        free(records);

        return NULL; // Return error code here.
    }

    int count = 0;

    for (long i=0; i<size; ++i){
        offset[i] = randomGen.randomInt(randomGen.min, randomGen.max);
        keys[i] = i;

        Record record = { .value = randomGen.randomInt(randomGen.min, randomGen.max), .offset = &offset[i], .metadata.creationTime = time(NULL)};
        records[count++] = record;
    }

    // Sort the records based on their int values in ascending order using qsort.
    qsort(records, count, sizeof(Record), [](const void *a, const void *b) {
        Record *recordA = (Record *)a;
        Record *recordB = (Record *)b;

        return recordA->value - recordB->value;
    });

    free(offset);
    free(keys);
    // Return records and the count of successfully created records.
    *records[size] = count;

    return records;
}
