    device *devices;
    size_t capacity;
    size_t count;
} deviceList;

int createDevices(deviceList *list, const char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) return -1; // Error opening file

    list->capacity = 20; // Initial capacity
    list->count = 0;
    list->devices = malloc(list->capacity * sizeof(*list->devices));
    if (list->devices == NULL) return -1; // Error allocating memory

    srand((unsigned int) time(NULL));
    char buffer[256];
    while (fgets(buffer, sizeof(buffer), file)) {
        buffer[strcspn(buffer, "\r\n")] = '\0'; // Remove trailing newline

        if (list->count == list->capacity) {
            void *temp = realloc(list->devices, 2 * list->capacity * sizeof(*list->devices));
            if (temp == NULL) return -1; // Error reallocating memory

            list->devices = temp;
            list->capacity *= 2;
        }

        device *newDevice = &list->devices[list->count];
        newDevice->name = malloc(strlen(buffer) + 1);
        if (newDevice->name == NULL) return -1; // Error allocating memory

        strcpy(newDevice->name, buffer);
        newDevice->id = rand(); // Set random id
        newDevice->meta.online = 0;
        newDevice->meta.maintenance = 0;
        list->count++;
    }

    fclose(file);
    return 0;
}
