#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct {
    time_t online;
    time_t maintenance;
} Metadata;

typedef struct {
    int id;
    char* name;
    Metadata metadata;
} Device;

// Function to create a device with the given identifier and default timestamps.
Device* createDevice(int id, time_t online, time_t maintenance) {
    // Allocate memory for the device structure.
    Device* dev = malloc(sizeof(Device));
    if (dev == NULL) return NULL;

    // Initialize the device fields.
    dev->id = id;
    dev->name = malloc(20 * sizeof(char));
    strcpy(dev->name, "Default Device");
    dev->metadata.online = online;
    dev->metadata.maintenance = maintenance;

    return dev;
}

// Function to compare two device structures for sorting.
int compareDevices(const void* a, const void* b) {
    Device* d1 = *(Device**)a;
    Device* d2 = *(Device**)b;
    return (d1->id - d2->id);
}

// Function to create and sort devices for each range in the given array.
int createAndSortDevices(int ranges[][2], size_t numRanges, Device* devList[]) {
    // Allocate memory for an array of device pointers.
    Device** devices = malloc(numRanges * sizeof(Device*));
    if (devices == NULL) return -1;

    srand(time(0));  // Seed the random number generator with current time.

    int successCount = 0;
    for (size_t i = 0; i < numRanges; i++) {
        int id = ranges[i][0] + rand() % (ranges[i][1] - ranges[i][0]);  // Generate a random identifier.

        Device* dev = createDevice(id, time(NULL), time(NULL));  // Create the device with default timestamps.
        if (dev != NULL) {
            devices[successCount++] = dev;  // Add the device to the array of devices.
        } else {
            break; // If allocation fails, stop creating and sorting more devices.
        }
    }

    qsort(devices, successCount, sizeof(Device*), compareDevices); // Sort the devices by identifier.

    *devList = malloc(successCount * sizeof(Device));  // Allocate memory for the device list.
    if (*devList == NULL) {
        free(devices);
        return -1;
    }

    memcpy(*devList, devices, successCount * sizeof(Device)); // Copy sorted devices to the output array.
    free(devices);  // Free memory allocated for device pointers.

    return successCount;
}
```
This code creates a function `createAndSortDevices` that takes an array of ranges and the number of ranges, and returns an array of sorted devices corresponding to each range. It also returns the number of successfully created devices. The main part of this function is the loop where it generates a random identifier for each device within its given range, creates the device with default timestamps using `createDevice` function and then adds it to an array of pointers to devices. After all devices are added, it sorts them by their identifiers using `qsort` from standard library.
