#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    time_t creationTime;
    time_t lastAccessedTime;
} Metadata;

typedef struct {
    int value;
    Metadata metadata;
} Record;

typedef struct {
    size_t numRecords;
    // Other configuration options...
} Config;

typedef struct {
    long* offsets;
    int* keys;
    Record** records;
    int successCount;
} Result;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void swap(Record **a, Record **b) {
    Record *temp = *a;
    *a = *b;
    *b = temp;
}

int partition (Record* arr[], int low, int high) {
    int pivotValue = arr[high]->value;
    int i = (low - 1);

    for (int j = low; j <= high- 1; j++) {
        if (arr[j]->value < pivotValue) {
            i++;
            swap(&arr[i], &arr[j]);
        }
    }
    swap(&arr[i + 1], &arr[high]);
    return (i + 1);
}

void quickSort(Record* arr[], int low, int high) {
    if (low < high) {
        int pi = partition(arr, low, high);
        quickSort(arr, low, pi - 1);
        quickSort(arr, pi + 1, high);
    }
}

Result createArrays(Config* config) {
    pthread_mutex_lock(&lock); // lock for thread safety

    Result result;
    result.successCount = 0;

    // Preallocate fixed size arrays
    long preAllocOffsets[100000];
    int preAllocKeys[100000];

    result.offsets = malloc(config->numRecords * sizeof(long));
    if (result.offsets == NULL) { 
        return result; // allocation failure
    }

    result.keys = malloc(config->numRecords * sizeof(int));
    if (result.keys == NULL) {
        free(result.offsets); 
        return result; // allocation failure
    }

    result.records = malloc(config->numRecords * sizeof(Record*));
    if (result.records == NULL) {
        free(result.offsets); 
        free(result.keys); 
        return result; // allocation failure
    }

    srand(time(0));

    for (size_t i = 0; i < config->numRecords; ++i) {
        Record* record = malloc(sizeof(Record));
        if (record == NULL) continue; // allocation failure, skip this record

        result.records[result.successCount] = record;
        result.offsets[result.successCount] = rand(); 
        result.keys[result.successCount] = rand();
        record->value = rand();

        time_t now = time(NULL);
        record->metadata.creationTime = now;
        record->metadata.lastAccessedTime = now;

        result.successCount++; // increment success count
    }

    quickSort(result.records, 0, config->numRecords -1); // sort records

    pthread_mutex_unlock(&lock); // unlock after all memory allocations are done

    return result;
}
