int create_events(long **timestamps, int **ids, event ***events, size_t num_events, const char *source, const char *type, bool isActive, bool logEnabled) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    if (logEnabled) printf("Creating events..\n");

    int successfulEvents = 0;
    *timestamps = malloc(num_events * sizeof(long));
    *ids = calloc(num_events, sizeof(int));
    *events = calloc(num_events, sizeof(event*));

    if (*timestamps == NULL || *ids == NULL || *events == NULL) {
        printf("Allocation failed\n");
        return -1;
    }

    for (size_t i = 0; i < num_events; ++i) {
        pthread_mutex_lock(&mutex);

        (*timestamps)[i] = time(NULL);
        (*ids)[i] = rand() % 100 + 1; // Random number between 1 and 100.
        event *e = malloc(sizeof(event));

        if (e == NULL) {
            printf("Allocation failed\n");
            pthread_mutex_unlock(&mutex);
            continue;
        }

        e->value = (*ids)[i];
        e->timestamp = &(*timestamps)[i];
        strncpy(e->meta.source, source, sizeof(e->meta.source) - 1);
        strncpy(e->meta.type, type, sizeof(e->meta.type) - 1);

        (*events)[i] = e;
        if (isActive) successfulEvents++;

        pthread_mutex_unlock(&mutex);
    }

    free(*timestamps);
    free(*ids);
    for(size_t i = 0; i < num_events; ++i) {
        if((*events)[i] != NULL) free((*events)[i]);
    }
    free(*events);

    return successfulEvents;
}
