    // Allocate memory for arrays
    long* offsets = malloc(sizeof(long)*N);
    int* keys = malloc(sizeof(int)*N);
    record_t** records = malloc(sizeof(record_t*)*N);

    if (offsets == NULL || keys == NULL || records == NULL) {
