['Here's the C code for this task. It uses a quicksort algorithm to sort the sensors, and uses a simple lock-based mechanism to ensure thread safety when logging operations are performed concurrently. 

```c
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct Metadata {
    int sensor_id;
    time_t timestamp;
    bool status;
} Metadata;

typedef struct SensorData {
    float value;
    char key;
    Metadata metadata;
} SensorData;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int partition(SensorData arr[], int low, int high) {
    float pivot = arr[high].value;  // pivot
    int i = (low - 1);  // Index of smaller element

    for (int j = low; j <= high - 1; j++) {
        if (arr[j].value < pivot) {
            i++;  // increment index of smaller element
            SensorData temp = arr[i];
            arr[i] = arr[j];
            arr[j] = temp;
        }
    }
    SensorData temp = arr[i + 1];
    arr[i + 1] = arr[high];
    arr[high] = temp;
    return (i + 1);
}

void quicksort(SensorData arr[], int low, int high) {
    if (low < high) {
        /* pi is partitioning index, arr[p] is now at right place */
        int pi = partition(arr, low, high);

        // Separately sort elements before 
        // partition and after partition
        quicksort(arr, low, pi - 1);
        quicksort(arr, pi + 1, high);
    }
}

int initialize_sensors(SensorData **sensors, int num_sensors) {
    if (num_sensors < 100 || num_sensors > 1000) return -1;  // Invalid sensor number

    *sensors = malloc(sizeof(SensorData) * num_sensors);
    if (*sensors == NULL) return -2;  // Allocation failure

    srand((unsigned int) time(NULL));
    for (int i = 0; i < num_sensors; i++) {
        (*sensors)[i].value = -100.0f + ((float) rand() / RAND_MAX) * 200.0f;
        (*sensors)[i].key = 'A' + (rand() % 26);
        (*sensors)[i].metadata.sensor_id = 1000 + i;
        (*sensors)[i].metadata.timestamp = time(NULL);
        (*sensors)[i].metadata.status = true; // all sensors are active by default
    }

    quicksort(*sensors, 0, num_sensors - 1);

    return num_sensors;
}

void log_event(const char* event) {
    pthread_mutex_lock(&lock);
    // Add logging mechanism here (e.g., printf or write to a file)
    printf("Event: %s\n", event);
    pthread_mutex_unlock(&lock);
}
```
This code uses dynamic memory allocation and quicksort algorithm. Note that this is just a basic example of how you can approach the problem. You would need to adapt it according to your real-world requirements, such as error checking, thread safety for logging operations, efficient use of resources like memory etc. 

Also note that proper cleanup after allocation failure is not handled here. Always remember to free any dynamically allocated memory in case an error occurs or when you are done with it.
