typedef struct {
    long creation_timestamp;
    long last_accessed_timestamp;
} metadata;

typedef struct {
    int value;
    long *offset;
    metadata meta;
} record;

int createRecords(long **offsets, int **keys, record ***records, 
                  size_t num_records, int minVal, int maxVal) {

    srand(time(NULL)); // seed the random number generator

    *offsets = malloc(num_records * sizeof(long));
    if (*offsets == NULL) return -1;

    *keys = malloc(num_records * sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        return -1;
    }

    *records = malloc(num_records * sizeof(record*));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        return -1;
    }

    for (size_t i = 0; i < num_records; ++i) {
        (*records)[i] = malloc(sizeof(record));
        if ((*records)[i] == NULL) {
            // Handle memory allocation failure gracefully
            while (i-- > 0) free((*records)[i]);

            free(*offsets);
            free(*keys);
            free(*records);
            return -1;
        }

        (*records)[i]->value = minVal + rand() % (maxVal - minVal + 1); // set a random value
        (*records)[i]->offset = &((*offsets)[i]);

        // Initialize metadata with default values
        time_t now = time(NULL);
        (*records)[i]->meta.creation_timestamp = now;
        (*records)[i]->meta.last_accessed_timestamp = now;
    }

    return num_records;
}

void sortRecords(record **records, size_t num_records) {
    // Use an appropriate sorting algorithm (e.g., quicksort, mergesort)
    qsort(records, num_records, sizeof(record*), compare);
}

int compare(const void *a, const void *b) {
    record **recordA = (record**)a;
    record **recordB = (record**)b;

    return (*recordA)->value - (*recordB)->value;
}

void freeRecords(long *offsets, int *keys, record ***records, size_t num_records) {
    for (size_t i = 0; i < num_records; ++i) {
        free((*records)[i]); // Free the inner records
    }

    free(offsets);
    free(keys);
    free(*records); // Finally, free the outer array of records
}
```
