#include <pthread.h>

typedef struct {
    int intValue;
    char str[20];
} record;

// Callback function prototype
typedef long (*OffsetCallback)(int index);

void initializeRecords(record **records, int numRecords, int minValue, int maxValue, 
                       OffsetCallback getOffset, char heapStrings) {
    srand(time(0)); // Initialize random number generator

    pthread_mutex_t mutex;
    if (pthread_mutex_init(&mutex, NULL) != 0) {
        printf("Failed to initialize mutex\n");
        exit(1);
    }

    for (int i = 0; i < numRecords; ++i) {
        pthread_mutex_lock(&mutex);

        long offset = getOffset(i);
        if (offset < 0) {
            printf("Invalid offset received from callback\n");
            exit(1);
        }

        records[i] = malloc(sizeof(record)); // Allocate memory for record structure
        if (!records[i]) {
            printf("Failed to allocate memory for record %d\n", i + 1);
            continue;
        }

        records[i]->intValue = rand() % (maxValue - minValue + 1) + minValue; // Initialize int value with random number

        if(heapStrings == 0){
          sprintf(records[i]->str, "Record%d", i+1);  // Initialize string on stack
        }else{
          char *heapString = malloc(20); // Allocate memory for string on heap
          if (!heapString) {
              printf("Failed to allocate memory for string in record %d\n", i + 1);
              continue;
          }
          sprintf(heapString, "Record%d", i+1);  // Initialize string on heap
          strncpy(records[i]->str, heapString, 20);
          free(heapString);
        }

        pthread_mutex_unlock(&mutex);
    }
}
```
