typedef struct {
    int event_type;
    long timestamp;
    int unique_id;
} EventRecord;

typedef struct {
    EventRecord* records;
    size_t capacity;
    size_t size;
} SystemModule;

SystemModule* init_module(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;

    SystemModule* module = malloc(sizeof(SystemModule));
    if (!module) return NULL;

    module->records = calloc(initial_capacity, sizeof(EventRecord));
    if (!module->records) {
        free(module);
        return NULL;
    }

    module->size = 0;
    module->capacity = initial_capacity;

    srand(time(NULL)); // for random event type generation

    return module;
}

int add_record(SystemModule* module, long timestamp, int unique_id) {
    if (!module || timestamp < 0 || unique_id < 1 || unique_id > 2147483647) 
        return -1; // invalid input

    for (size_t i = 0; i < module->size; ++i) {
        if (module->records[i].unique_id == unique_id) 
            return -2; // non-unique ID
    }

    if (module->size >= module->capacity) {
        EventRecord* newRecords = realloc(module->records, module->capacity * 2 * sizeof(EventRecord));
        if (!newRecords) return -3; // allocation failure

        module->records = newRecords;
        module->capacity *= 2;
    }

    module->records[module->size].event_type = rand();
    module->records[module->size].timestamp = timestamp;
    module->records[module->size].unique_id = unique_id;
    ++(module->size);

    return 0; // success
}
```
This implementation uses a struct to store an array of records, along with the current size and capacity. The `init_module` function handles dynamic memory allocation for the initial module and record arrays, ensuring error checking on memory allocations. 
