void* allocate_and_initialize(size_t size) {
    // Allocate memory for arrays
    long* offsets = malloc(size * sizeof(*offsets));
    if (offsets == NULL) return -1;  // Error code

    int* keys = calloc(size, sizeof(*keys));
    if (keys == NULL) {
        free(offsets);
        return -2;  // Error code
    }

    double* values = malloc(size * sizeof(*values));
    if (values == NULL) {
        free(offsets);
        free(keys);
        return -3;  // Error code
    }

    Record* records = calloc(size, sizeof(*records));
    if (records == NULL) {
        free(offsets);
        free(keys);
        free(values);
        return -4;  // Error code
    }

    char* str1 = "example";
    char* str2 = "data";

    for (size_t i = 0; i < size; ++i) {
        keys[i] = rand() % 1000;  // Random value between 0 and 999

        values[i] = ((double)rand() / RAND_MAX) * 100.0;  // Random double between 0.0 and 100.0

        records[i].key = keys[i];
        records[i].value = values[i];

        size_t strLen = strlen(str1) + strlen(str2) + 1; // Include null terminator
        char* string = malloc(strLen);
        if (string == NULL) {  // Error handling for memory allocation failure
            free(offsets);
            free(keys);
            free(values);

            for (size_t j = 0; j < i; ++j) {
                free(records[j].string);
            }
            free(records);

            return -5;  // Error code
        }

        records[i].string = string;
        strcpy(string, str1);
        strcat(string, str2);
    }

    // Free memory on exit
    free(offsets);
    free(keys);
    free(values);
    for (size_t i = 0; i < size; ++i) {
        free(records[i].string);
    }
    free(records);

    return 0; // Success code
}
```
