int createRecords(long maxMemSize, int numOfRecords, int minIntValue, int maxIntValue) {

    if (numOfRecords <= 0 || maxMemSize < sizeof(record)) {
        return -1; // Invalid arguments
    }

    long chunkSize = maxMemSize / numOfRecords; 
    if (chunkSize < sizeof(record)) {
        chunkSize = sizeof(record);
    }

    int createdCount = 0;
    while (numOfRecords > 0) {
        size_t currChunkSize = (chunkSize > numOfRecords) ? numOfRecords : chunkSize; 

        record* recordsPtr = malloc(currChunkSize); // Allocate memory for a chunk of records
        if (!recordsPtr) {
            return createdCount; // Handle allocation failure by returning the count of successfully allocated records
        }

        for (size_t i = 0; i < currChunkSize/sizeof(record); ++i) {
            recordsPtr[i].key = minIntValue + rand() % ((maxIntValue + 1) - minIntValue); // Assign random int value to the key field of each record

            time(&recordsPtr[i].metaData.creationTime);  // Initialize metadata with default values
            recordsPtr[i].metaData.lastAccessedTime = 0;
            recordsPtr[i].metaData.recordStatus = 1;
        }

        numOfRecords -= currChunkSize/sizeof(record);
        createdCount += currChunkSize/sizeof(record);
    }

    return createdCount; // Return count of successfully allocated records
}
