int create_records(long **offsets, int **keys, record_t **records, size_t n) {

    srand(time(NULL));  // for random number generation
    *offsets = malloc(n * sizeof(long));
    if(*offsets == NULL) return -1;

    *keys = malloc(n * sizeof(int));
    if(*keys == NULL){
        free(*offsets);
        return -1;
    }

    *records = calloc(n, sizeof(record_t));
    if(*records == NULL){
        free(*offsets);
        free(*keys);
        return -1;
    }

    for (size_t i = 0; i < n; ++i) {
        (*offsets)[i] = rand();  // initialize with random values
        (*keys)[i] = rand() % 100;  // initialize with random values within a given range

        (*records)[i].value = rand() % 100;  // set int field to random value
        (*records)[i].offset = &(*offsets)[i];  // set offset pointer

        time_t current_time = time(NULL);
        (*records)[i].meta.creation_ts = current_time;  // init creation timestamp
        (*records)[i].meta.last_accessed_ts = 0;  // init last accessed timestamp
    }

    return n;
}

