typedef struct {
    time_t creationTime;
    time_t lastAccessedTime;
} Metadata;

typedef struct {
    int value;
    long* offsetValue;
    Metadata metadata;
} Record;

typedef enum {
    SUCCESS,
    FAILURE,
    INVALID_PARAMS
} ErrorCode;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
long* offsets;
int* keys;
Record** records;
size_t recordCount = 0;
size_t maxRecords; // maximum number of records that can be stored

ErrorCode initialize(size_t capacity) {
    if (capacity == 0) return INVALID_PARAMS;

    offsets = malloc(sizeof(long) * capacity);
    keys = malloc(sizeof(int) * capacity);
    records = malloc(sizeof(Record*) * capacity);
    maxRecords = capacity;

    if (offsets == NULL || keys == NULL || records == NULL) {
        free(offsets);
        free(keys);
        free(records);

        return FAILURE;
    }

    return SUCCESS;
}

ErrorCode createRecord(int randomValue, int accessFlag) {
    if (recordCount >= maxRecords) return FAILURE;

    Record* record = malloc(sizeof(Record));
    if (record == NULL) return FAILURE;

    // Initialize record
    record->value = randomValue;
    record->offsetValue = &offsets[recordCount];

    time_t currentTime = time(NULL);
    record->metadata.creationTime = currentTime;
    record->metadata.lastAccessedTime = (accessFlag) ? currentTime : 0;

    // Update shared state
    pthread_mutex_lock(&mutex);
    records[recordCount] = record;
    keys[recordCount] = randomValue;
    offsets[recordCount] = record->value * sizeof(int);
    recordCount++;
    pthread_mutex_unlock(&mutex);

    return SUCCESS;
}

void cleanup() {
    for (size_t i = 0; i < recordCount; ++i) {
        free(records[i]);
    }
    free(offsets);
    free(keys);
    free(records);

    pthread_mutex_destroy(&mutex);
}
``` 

