#include <stdio.h>
#include <stdlib.h>

typedef struct sensor_data {
    long timestamp;
    float sensor_reading;
} SensorData;

int readFile(const char *filename, SensorData **data) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        printf("Error opening file %s\n", filename);
        return -1;
    }

    int capacity = 1024;  // Initial array size
    long *timestamps = malloc(capacity * sizeof(long));
    float *readings = malloc(capacity * sizeof(float));
    if (timestamps == NULL || readings == NULL) {
        printf("Memory allocation failed\n");
        return -1;  // Return error code
    }

    int count = 0;  // Number of valid lines processed
    char line[256];  // Line buffer
    while (fgets(line, sizeof(line), file)) {
        long timestamp;
        float reading;

        // Parse the line
        if (sscanf(line, "%ld,%f", &timestamp, &reading) != 2) {
            printf("Skipping invalid line: %s\n", line);
            continue;  // Skip this line and move to next one
        }

        // If we've run out of space in our arrays, allocate more memory
        if (count >= capacity) {
            capacity *= 2;  // Double the array size for each reallocation
            timestamps = realloc(timestamps, capacity * sizeof(long));
            readings = realloc(readings, capacity * sizeof(float));

            if (timestamps == NULL || readings == NULL) {
                printf("Memory allocation failed\n");
                return -1;  // Return error code
            }
        }

        timestamps[count] = timestamp;
        readings[count] = reading;
        count++;
    }

    fclose(file);

    // Allocate memory for array of sensor data structures
    *data = malloc(count * sizeof(SensorData));
    if (*data == NULL) {
        printf("Memory allocation failed\n");
        return -1;  // Return error code
    }

    // Initialize sensor data structures
    for (int i = 0; i < count; i++) {
        (*data)[i].timestamp = timestamps[i];
        (*data)[i].sensor_reading = readings[i];
    }

    free(timestamps);
    free(readings);
    return count;  // Return number of valid data lines processed
}
```
In this code, we first allocate arrays for the timestamps and sensor readings. If our array is full (which it will be after processing half the file), we double its size using `realloc()`. We then parse each line from the CSV file and add valid data to our arrays. Finally, we initialize an array of `sensor_data` structures with our parsed data and return the number of valid lines processed.
