typedef struct {
    int integer_value;
    double float_value;
    char *str;
} data_record;

data_record* init_array(int size) {
    data_record *arr = (data_record*)malloc(sizeof(data_record)*size);
    if (!arr) exit(-1); // out of memory
    return arr;
}

void free_array(data_record* arr, int size) {
    for(int i = 0; i < size; ++i) {
        free(arr[i].str);
    }
    free(arr);
}

// sort array by integer values in ascending order using quicksort
void quick_sort(data_record *array, int left, int right) {
    if (left < right) {
        int pivot = partition(array, left, right);
        quick_sort(array, left, pivot - 1);
        quick_sort(array, pivot + 1, right);
    }
}

int partition(data_record *array, int left, int right) {
    int pivot = array[right].integer_value;
    int i = (left - 1);

    for (int j = left; j <= right- 1; j++) {
        if (array[j].integer_value <= pivot) {
            i++;
            swap(&array[i], &array[j]);
        }
    }
    swap(&array[i + 1], &array[right]);
    return (i + 1);
}

void swap(data_record* a, data_record* b) {
    data_record t = *a;
    *a = *b;
    *b = t;
}

