from importlib import reload

class FileLoader:
    def __init__(self):
        self.lock = threading.Lock()

    def load_file(self, filename):
        if not os.path.exists(filename) or not os.access(filename, os.R_OK):
            print("File does not exist or is not readable")
            return None

        with self.lock:  # ensure thread safety when loading files
            module = filename[:-3]  # remove .py from the end of the file name
            spec = importlib.util.spec_from_file_location(module, filename)
            foo = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(foo)
            reload(foo)  # reload module to ensure latest changes are applied

