    metadata->lastAccessedTime = metadata->creationTime;
}

int compareRecordsByValue(const void *a, const void *b) {
    Record* recordA = (Record*) a;
    Record* recordB = (Record*) b;
    return recordA->value - recordB->value;
}

void sortRecords(Record* records, size_t numRecords) {
    qsort(records, numRecords, sizeof(Record), compareRecordsByValue);
}

