        (*logs)[i]->timestamp = rand();

        // Initialize event structure
        (*events)[i]->eventType = rand();
        (*events)[i]->timestamp = rand();

        successfulCount++;
    }

    // Sort logs by timestamp (bubble sort for simplicity)
    for(size_t i = 0; i < n-1; i++) {      
        for(size_t j = 0; j < (n-i-1); j++){  
            if((*logs)[j]->timestamp > (*logs)[j+1]->timestamp){ 
                // Swap log structures
                Log *temp = (*logs)[j];
                (*logs)[j] = (*logs)[j+1];
                (*logs)[j+1] = temp;
            }          
        }      
    } 

    return successfulCount;
}
