void update_api(int id, int new_value) {
    g_async_lock(&record_mutex);
    Record *r = (Record*)g_async_queue_peek(record_queue);
    while (r != NULL) {
        if (r->value == id) {
            r->value = new_value;
            syslog(LOG_INFO, "Updated record with ID %d", id);
            break;
        }
        g_async_queue_pop(record_queue);
        r = (Record*)g_async_queue_peek(record_queue);
    }
    g_async_unlock(&record_mutex);
}

void delete_api(int id) {
    g_async_lock(&record_mutex);
    Record *r = (Record*)g_async_queue_peek(record_queue);
    while (r != NULL) {
        if (r->value == id) {
            r->value = 0; // or some other default value
            syslog(LOG_INFO, "Deleted record with ID %d", id);
            break;
        }
        g_async_queue_pop(record_queue);
        r = (Record*)g_async_queue_peek(record_queue);
