	}
	*offset_array = malloc(sizeof(long) * num_records);
	if (*offset_array == NULL) {
		free(*key_array); // clean up previously allocated memory on fail
		return NULL; 
	}

	// Initialize random number generator seed with current time
	srand((unsigned int)time(NULL));

	// Calculate range limits
	const long offsetRange = LONG_MAX / num_records;
	const int keyRange1 = INT_MAX / (num_records * 2); // for the first half
	const int keyRange2 = INT_MAX / num_records; // for the second half

	// Initialize arrays
	for (int i = 0; i < num_records; ++i) {
		if (i < num_records / 2) {
			(*key_array)[i] = rand() % keyRange1; // random value within the first half range
		} else {
