		}
		(*offset_array)[i] = (long)rand() * offsetRange / RAND_MAX; // random long number for offsets
	}
	// Dynamically allocate memory and initialize records array
	Record *records = malloc(sizeof(Record) * num_records); 
	if (records == NULL) {
		free(*key_array);
		free(*offset_array); // clean up on fail
		return NULL; 
	}
	// Initialize records with random values within the first half range
	for (int i = 0; i < num_records / 2; ++i) {
		records[i].value = rand() % keyRange1;
	}
	// Initialize remaining records with random values within the second half range
