int modificationsThreshold = 1000; /* Set this according to your needs */

void initLogger() {
    logFile = fopen(logFileName, "a");
}

void flushToDiskAndUpdateMetadata() {
    for(int i=0;i<recordsCreated;++i){
        records[i]->metadata_ptr->last_accessed_timestamp = time(NULL);
        records[i]->metadata_ptr->access_count += 1;
    }
}

void* backgroundFlushThreadFunc(void *arg) {
    while(1){
        if (difftime(time(NULL), lastFlushTime) >= flushIntervalTimeInSecs || flushCounter >= modificationsThreshold ){
            pthread_mutex_lock(&mutexFlush);
            isFlushing = 1;
            flushToDiskAndUpdateMetadata();
            fprintf(logFile, "Flushed %d records to disk\n",recordsCreated);
            fflush(logFile);
            flushCounter=0; 
            lastFlushTime = time(NULL);
            isFlushing = 0;
            pthread_mutex_unlock(&mutexFlush);
        } else {
            pthread_cond_wait(&cond, &mutexFlush);
        }
    }
}

