#include "types.hpp"
#include "carray.hpp"
#include "dct.hpp"

carray<real>* dct::init_dct_mat(creal N) {
    carray<real>* mat = new carray<real>(N);
    for (size_t k = 0; k < N; ++k) {
        real c_k = ((k == 0)? 1.0/sqrt(2) : 1);
        for (size_t n = 0; n < N; ++n) {
            mat->data[n*N+k] = c_k * cos(((2*n + 1)*k*pi) / (2*N));
        }
    }
    return mat;
}

