            img* data;

            image(creal _w=0, creal _h=0, creal _c=1) :
                width(_w), height(_h), channels(_c),
                data((img*)calloc(_w*_h*_c, sizeof(img))) {}
            ~image() { free(data); }

            void print_pixel(creal x, creal y) const;
    };

    image* load_from_file(const char* filepath);
}

