#include <stdlib.h>
#include "carray.hpp"
#include "types.hpp"
#include "dct.hpp"
#include "mat.hpp"

void mat::image::print_pixel(creal x, creal y) const {
    printf("pixel (%lu, %lu): [", x, y);
    for (size_t c = 0; c < channels-1; ++c) {
        printf("%u, ", data[(y*width+x)*channels + c]);
    }
    printf("%u]\n", data[((y*width+x)*channels + channels-1)]);
}

mat::image* mat::load_from_file(const char* filepath) {
    FILE* fp = fopen(filepath, "rb");
    if (fp == NULL) return NULL;

    // read the 54-byte header
    byte info[54];
    fread(info, sizeof(byte), 54, fp);

    creal width  = *(creal*)&info[18];
    creal height = *(creal*)&info[22];

    // allocate 3 bytes per pixel
    mat::image* img = new mat::image(width, height, 3);

    // read the rest of the data at once
    fread(img->data, sizeof(byte), width*height*3, fp);
    fclose(fp);

    return img;
