/**
 * @author Jake Dern
 * This file contains the definition of a Binary Search Tree (BST) class
 * that can be used to build and manipulate binary search trees for any
 * data type where "<" is defined.  This class provides functions for
 * inserting an element, checking if an element is in the tree, performing
 * breadth first traversal, and deleting elements from the tree.
 */
#ifndef BSTREE_HPP
#define BSTREE_HPP

template <typename T>
class BSTree {
  public:
    /**
     * @brief Default constructor for the binary search tree that initializes
     * its root node to nullptr, signifying an empty tree.
     */
    BSTree();

    /**
     * @brief Constructor for the binary search tree that takes a vector of
     * elements and inserts them into the tree.  This function will call the
     * insert() method on each element in the vector.
     *
     * @param vec A vector of elements to be inserted into the tree.
     */
    BSTree(const std::vector<T> &vec);

    /**
     * @brief Destructor for the binary search tree that deletes all nodes in
     * the tree to prevent memory leaks.  This function will call the
     * deleteTree() method on the root node, which will recursively delete all
     * child nodes of the root.
     */
    ~BSTree();

    /**
     * @brief Deletes all elements in the tree.  This function calls the
     * deleteTree() method on the root node, which will recursively delete all
     * child nodes of the root.
     */
    void clear();

    /**
     * @brief Inserts an element into the binary search tree by calling the
     * insert() method on the root node and passing it the element to be inserted.
     *
     * @param elem The element to be inserted into the tree.
     */
    void insert(const T &elem);

    /**
     * @brief Checks if an element is in the binary search tree by calling the
     * find() method on the root node and passing it the element to be found.
     *
     * @param elem The element to be searched for in the tree.
     * @return True if the element is found in the tree, false otherwise.
     */
    bool find(const T &elem) const;

    /**
     * @brief Performs a breadth first traversal of the binary search tree by
     * calling the bfs() method on the root node.  This function prints each
     * element in the tree to standard output, with elements separated by spaces.
     */
    void printBFS() const;

    /**
     * @brief Deletes a single instance of an element from the binary search
     * tree.  If the element appears multiple times in the tree, only its first
     * appearance will be deleted.  This function calls the deleteElem() method
     * on the root node and passes it the element to be deleted.
     *
     * @param elem The element to be deleted from the tree.
     */
    void erase(const T &elem);

    /**
     * @brief Returns a vector of elements in the binary search tree that are
     * greater than or equal to a given value, sorted in ascending order.  This
     * function creates an empty vector, calls the inorder() method on the root
     * node with this vector as an argument, and returns the resulting vector
     * of elements.
     *
     * @param elem The element to be compared to each element in the tree.
     * @return A sorted vector of elements greater than or equal to the given
     * value.
     */
    std::vector<T> rangeQuery(const T &elem) const;

  private:
    /**
     * @brief Node struct that is used as a building block for the binary search tree.
     * Each node contains an element of type T, and pointers to its left and right child nodes.
     */
    class Node {
      public:
        /**
         * @brief Constructor for the Node class that takes an element and initializes
         * its left and right child nodes to nullptr, signifying a leaf node in the tree.
         *
         * @param elem The element to be stored in this node.
         */
        Node(const T &elem);

        /**
         * @brief Destructor for the Node class that is used to delete this node and all its child nodes.
         */
        ~Node();

        /**
         * @brief Inserts an element into the subtree rooted at this node by recursively
         * calling insert() on either the left or right child, depending on whether the given
         * element is less than or greater than the current element.  This function returns a pointer
         * to the newly created Node, which will be nullptr if no new node was inserted (i.e., the
         * element already existed in the tree).
         *
         * @param elem The element to be inserted into the subtree rooted at this node.
         * @return A pointer to the newly created Node that stores the given element, or nullptr if no
         * new node was inserted (i.e., the element already existed in the tree).
         */
        Node* insert(const T &elem);

        /**
         * @brief Checks if an element is in the subtree rooted at this node by recursively calling find() on either
         * the left or right child, depending on whether the given element is less than or greater than the current
         * element.  This function returns true if the element was found in the tree, false otherwise.
         *
         * @param elem The element to be searched for in the subtree rooted at this node.
         * @return True if the element was found in the tree, false otherwise.
         */
        bool find(const T &elem) const;

        /**
         * @brief Prints all elements in the subtree rooted at this node to standard output by recursively calling printBFS().
         * This function prints each element followed by a space character, with no trailing newline.  It is assumed that
         * the elements of type T can be printed to standard output using the "<<" operator.
         */
        void printBFS() const;

        /**
         * @brief Deletes an element from the subtree rooted at this node.  If the given element matches the current
         * element, this function will delete it and rearrange any child nodes to preserve the binary search tree property.
         * This function returns a pointer to the newly created Node, which will be nullptr if no new node was inserted
         * (i.e., the element already existed in the tree).  If the current element is greater than the given element and
         * has a right child, it calls deleteElem() on this child; otherwise, it does nothing.
         *
         * @param elem The element to be deleted from the subtree rooted at this node.
         */
        Node* deleteElem(const T &elem);

        /**
         * @brief Stores all elements in the subtree rooted at this node that are greater than or equal to a given value,
         * sorted in ascending order.  This function will recursively call inorder() on either the left or right child, depending
         * on whether the current element is less than or greater than the given value.  This function does not return anything, but
         * instead modifies its argument to include all relevant elements.
         *
         * @param elem The element to be compared to each element in the subtree rooted at this node.
         * @param result A reference to a vector of elements that is modified by this function to store all relevant elements.
         */
        void inorder(const T &elem, std::vector<T>& result) const;

      private:
        Node* _left;  // Pointer to the left child node
        Node* _right;  // Pointer to the right child node
        T _elem;  // The element stored in this node
    };

    Node* _root;  // Root of the binary search tree
};
