['This problem requires knowledge of C programming, dynamic memory allocation, error handling, sorting algorithms, logging mechanism, and concurrent execution. Below is the code to solve this task with all the described features. 

```c
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <sys/time.h>

typedef struct {
    unsigned int device_id;
    time_t timestamp;
} metadata;

typedef struct {
    float temperature;
    char key;
    metadata meta_data;
} device_info;

pthread_mutex_t log_lock = PTHREAD_MUTEX_INITIALIZER;

void swap(device_info *a, device_info *b) {
    device_info temp = *a;
    *a = *b;
    *b = temp;
}

int partition (device_info arr[], int low, int high) {
    float pivot = arr[high].temperature; 
    int i = (low - 1);  

    for (int j = low; j <= high- 1; j++) {
        if (arr[j].temperature < pivot) {
            i++;
            swap(&arr[i], &arr[j]);
        }
    }
    swap(&arr[i + 1], &arr[high]);
    return (i + 1);
}

void quickSort(device_info arr[], int low, int high) {
    if (low < high) {
        int pi = partition(arr, low, high);
        quickSort(arr, low, pi - 1);
        quickSort(arr, pi + 1, high);
    }
}

int create_devices(device_info **devices, int num_devices, float min_temp, float max_temp) {
    if (num_devices > 1000 || num_devices < 1) {
        pthread_mutex_lock(&log_lock);
        printf("Invalid device count.\n");
        pthread_mutex_unlock(&log_lock);
        return -1;
    }
    if (max_temp < min_temp) {
        pthread_mutex_lock(&log_lock);
        printf("Invalid temperature range.\n");
        pthread_mutex_unlock(&log_lock);
        return -2;
    }
    srand(time(0));
    *devices = malloc(num_devices * sizeof(device_info));
    if (*devices == NULL) {
        pthread_mutex_lock(&log_lock);
        printf("Memory allocation failed.\n");
        pthread_mutex_unlock(&log_lock);
        return -3;
    }
    for (int i = 0; i < num_devices; i++) {
        (*devices)[i].temperature = min_temp + ((float)rand()/(float)(RAND_MAX)) * (max_temp-min_temp);
        (*devices)[i].key = 'A' + rand() % 26;
        (*devices)[i].meta_data.device_id = 0;
        (*devices)[i].meta_data.timestamp = 0;
    }
    quickSort(*devices, 0, num_devices - 1);
    return num_devices;
}
```
This code creates a `create_devices` function that allocates memory for and initializes an array of `device_info` structures with a given number of devices and temperature range. It also logs errors when the device count is out of bound or the min temp > max temp, as well as handles failures in memory allocation.
']

