typedef struct record {
    int value;
    long *offsets;
    Metadata metaData;
} Record;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;  // mutex to handle concurrency

void *createRecord(long size, int range) {
    long* offsets = malloc(sizeof(long) * size);
    if (offsets == NULL) return NULL;

    int* keys = calloc(size, sizeof(int));
    if (keys == NULL) {
        free(offsets);  // clean up if allocation failed
        return NULL;
    }

    Record* records = malloc(sizeof(Record) * size);
    if (records == NULL) {
        free(offsets);
        free(keys);
        return NULL;
    }

    srand(time(NULL));  // seed random number generator
    for (int i = 0; i < size; ++i) {
        records[i].value = rand() % range;
        records[i].offsets = &offsets[i];
        Metadata metaData = {.creation=time(NULL), .lastAccessed=time(NULL), .id=i};
        records[i].metaData = metaData;
    }

    qsort(records, size, sizeof(Record), compare);  // sort array of records

    pthread_mutex_lock(&lock);  // Lock mutex before updating or deleting record.
    // Handle PUT and DELETE requests here using the http request data.
    pthread_mutex_unlock(&lock);  // Unlock mutex after updating or deleting record.

    free(offsets);
    free(keys);
    free(records);
}

// Function to compare two records based on their values. Used by qsort for sorting.
int compare(const void *a, const void *b) {
