    Record *recordB = (Record *)b;
    return (recordA->value - recordB->value);
}

void PUT_method(int id, int newValue) {
    char *sql;
    sqlite3_stmt *res;

    asprintf(&sql, "UPDATE records SET value = %d WHERE id = %d", newValue, id);
    if (sqlite3_prepare_v2(db, sql, -1, &res, 0) != SQLITE_OK) {
        printf("Failed to execute PUT method: %s\n", sqlite3_errmsg(db));
        return;
    }

    if (sqlite3_step(res) != SQLITE_DONE) {
        printf("Failed to execute PUT method: %s\n", sqlite3_errmsg(db));
        return;
    }

    sqlite3_finalize(res);
}

void DELETE_method(int id) {
    char *sql;
    sqlite3_stmt *res;

    asprintf(&sql, "DELETE FROM records WHERE id = %d", id);
    if (sqlite3_prepare_v2(db, sql, -1, &res, 0) != SQLITE_OK) {
        printf("Failed to execute DELETE method: %s\n", sqlite3_errmsg(db));
        return;
    }

    if (sqlite3_step(res) != SQLITE_DONE) {
        printf("Failed to execute DELETE method: %s\n", sqlite3_errmsg(db));
        return;
    }

    sqlite3_finalize(res);
}
```
