        free(*offsets);
        free(*keys);
        return -3;
    }

    pthread_mutex_t mutex;  // for synchronization
    pthread_mutex_init(&mutex, NULL);

    int created = 0;  // track the number of records successfully created

    for (size_t i = 0; i < count; ++i) {
        (*offsets)[i] = rand() % INT_MAX;  // set a random value to offsets[i]

