        (*entries)[i].meta.last_accessed = 0;  // default last accessed timestamp is 0
        (*entries)[i].meta.in_use = 0;  // data initially not in use

        pthread_mutex_lock(&mutex);  // lock for synchronization
        created++;  // increment the count of records successfully created
        pthread_mutex_unlock(&mutex);  // unlock after finished creating this record
    }

    return created;
}
