    entry->metaData.lastAccessedTime = time(NULL);
}

// Dynamic memory allocation function 
int allocateMemoryAndInitialize(long **offset, int **keys, data_entry **entries, size_t count, int min, int max) {
    // Allocate aligned memory for arrays
    *offset = (long*)aligned_alloc(64, sizeof(long)*count); 
    *keys = (int*)aligned_alloc(64, sizeof(int)*count);
    *entries = (data_entry*)aligned_alloc(64, sizeof(data_entry)*count);

    if (*offset == NULL || *keys == NULL || *entries == NULL) { 
        printf("Memory allocation failed.\n");
        return -1; // Return error code for allocation failure
    }

    srand((unsigned int)time(NULL)); // Seed random number generator

    size_t i, createdCount = 0;
    time_t currentTime = time(NULL); 
    for (i=0; i<count; ++i) {
        (*entries)[i].value = rand()%(max-min+1) + min; // Set random value within range
        (*offset)[i] = ((long)(*entries)) - ((long)(&((*entries)[0]))); 

        (*keys)[i] = i; // Assign sequential keys

        time_t expirationTime = currentTime + (rand()%10 + 1); // Set random expiration timestamp in future within 10 seconds
        if(currentTime < expirationTime) {
            (*entries)[i].metaData.creationTime = currentTime;
            (*entries)[i].metaData.lastAccessedTime = currentTime;
            (*entries)[i].metaData.expirationTime = expirationTime;
            (*entries)[i].metaData.isInUse = 1; // Entry is valid at the start
            ++createdCount; 
        } else {
            (*entries)[i].metaData.creationTime = currentTime;
            (*entries)[i].metaData.lastAccessedTime = currentTime;
            (*entries)[i].metaData.expirationTime = expirationTime;
            (*entries)[i].metaData.isInUse = 0; // Entry is invalid if creation time is already past its expiration time
        }
    }

    return createdCount; 
}

// Function to check and update validity of entries 
void validateEntries(data_entry *entries, size_t count) {
    for (size_t i=0; i<count; ++i) {
        time_t currentTime = time(NULL);

        // If entry is expired or has been accessed after its creation but before its expiration 
        if(entries[i].metaData.expirationTime < currentTime || 
           (entries[i].metaData.creationTime <= entries[i].metaData.lastAccessedTime && 
            entries[i].metaData.lastAccessedTime < currentTime)) {
            entries[i].metaData.isInUse = 0; // Mark as invalid
        } else if(entries[i].metaData.creationTime <= currentTime && currentTime < entries[i].metaData.expirationTime) {
            entries[i].metaData.isInUse = 1;  // Mark as valid
        }
    }
}

// Function to free memory allocated for the arrays 
void deallocateMemory(long *offset, int *keys, data_entry *entries) {
    free(offset);
    free(keys);
    free(entries);
}
