int createArrays(long** offsets, int** keys, DataEntry** entries, size_t size) {
    *offsets = malloc(sizeof(long)*size);
    *keys = malloc(sizeof(int)*size);
    *entries = calloc(size, sizeof(DataEntry));

    if (*offsets == NULL || *keys == NULL || *entries == NULL) {
        free(*offsets);
        free(*keys);
        free(*entries);

        return -1; //allocation failure
    }

    for (size_t i = 0; i < size; ++i) {
        (*offsets)[i] = rand();
        (*keys)[i] = rand();

        pthread_mutex_lock(&mutex);
        counter++;
        (*entries)[i].value = (*keys)[i]; //initialize value to a random key
        (*entries)[i].offset = &(*offsets)[i];

        time(&((*entries)[i].metaData.created)); //set creation timestamp
        (*entries)[i].metaData.accessed = (*entries)[i].metaData.created; //initialize last accessed timestamp as creation time
        (*entries)[i].metaData.inUse = 0; //initialize in use flag as 0
        (*entries)[i].metaData.id = counter; //set unique identifier for each entry

        pthread_mutex_unlock(&mutex);
    }

    return 0;
}
