#include <stdlib.h> // for malloc, free, rand, srand
#include <time.h>  // for time

// Assuming NFAPI_CRC_INDICATION_PDU_T is defined somewhere else
typedef struct {
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T; 

typedef struct {
    long creation_timestamp, last_accessed_timestamp;
} metadata;

typedef struct record {
    int value;
    long *offset;
    metadata meta;
} record;

void swap(record* a, record* b) {
    record t = *a;
    *a = *b;
    *b = t;
}

int partition (record arr[], int low, int high) {
    int pivot = arr[high].value;  
    int i = (low - 1);

    for (int j = low; j <= high- 1; j++){
        if (arr[j].value < pivot) {
            i++;
            swap(&arr[i], &arr[j]);
        }
    }
    swap(&arr[i + 1], &arr[high]);
    return (i + 1);
}

void quickSort(record arr[], int low, int high) {
    if (low < high){
        int pi = partition(arr, low, high);
        quickSort(arr, low, pi - 1);
        quickSort(arr, pi + 1, high);
    }
}

int generate_structs(long **offsets, int **keys, record **records, NFAPI_CRC_INDICATION_PDU_T **pdus) {
    srand((unsigned int)time(NULL)); // seed the random generator

    *offsets = malloc(4 * sizeof(long));
