void allocateMemory(double **doubles, long **integers, Node ***nodes, size_t size, unsigned int seed) {
    *doubles = (double *) malloc(sizeof(double) * size);
    if (*doubles == NULL) {
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }

    *integers = (long *) malloc(sizeof(long) * size);
    if (*integers == NULL) {
        free(*doubles);
