        (*nodes)[i] = (Node *) malloc(sizeof(Node));
        if ((*nodes)[i] == NULL) {
            perror("malloc failed");
            exit(EXIT_FAILURE);
        }

        pthread_mutex_lock(&mutex);  // Critical section: lock mutex before writing to shared resource
        (*doubles)[i] = (double) rand() / RAND_MAX;
        (*integers)[i] = rand();
        (*nodes)[i]->integer = rand();
        pthread_mutex_unlock(&mutex);  // Critical section: unlock mutex after writing to shared resource
    }
}
