// initializes a linked list with a specified number of nodes, where each node's 
// int value is set to a random value within a given range.
void initialize(double **doubles, char ***strings, Node ***nodes, int sizeDoubles, int numStrings, const char *stringLengths[], int sizeNodes, int minValue, int maxValue) {
    // Allocate memory for the arrays
    *doubles = (double*) malloc(sizeof(double) * sizeDoubles);
    *strings = (char**) malloc(sizeof(char*) * numStrings);

    // Check for successful allocation
    if (*doubles == NULL || *strings == NULL) {
        printf("Memory not allocated.\n");
        exit(0);
    }

    // Initialize the double array with random floating point numbers
    for (int i = 0; i < sizeDoubles; i++) {
        (*doubles)[i] = (double) rand() / RAND_MAX * maxValue;
    }

    // Initialize the char arrays based on their content length
    for (int i = 0; i < numStrings; i++) {
        int len = strlen(stringLengths[i]);
        (*strings)[i] = (char*) malloc((sizeof(char)) * (len + 1)); // Extra space for null-termination character

        if ((*strings)[i] == NULL) {
            printf("Memory not allocated.\n");
            exit(0);
        }
        strcpy((*strings)[i], stringLengths[i]);
    }

    // Initialize the linked list with nodes, each node's int value is set to a random value within a given range. 
    *nodes = (Node**) malloc(sizeof(Node*) * sizeNodes);
    if (*nodes == NULL) {
        printf("Memory not allocated.\n");
        exit(0);
    }

    for (int i = 0; i < sizeNodes; ++i) {
        Node* new_node = (Node*) malloc(sizeof(Node)); 
        if (new_node == NULL) {
            printf("Memory not allocated.\n");
            exit(0);
        }

        new_node->value = minValue + rand() % (( maxValue + 1 ) - minValue); // Random value within the given range
        new_node->next = NULL; 

        (*nodes)[i] = new_node; 
    } 
}
```

