void init_records(int size) {
    if (size < 1) {
        fprintf(stderr, "Error: Invalid size %d. Size must be positive.\n", size);
        return;
    }

    pthread_mutex_lock(&mutex);

    // If the size is the same as before, we don't need to reallocate memory
    if (size != records_size) {
        if (records != NULL) free(records);

        records = malloc(size * sizeof(record));
        if (records == NULL) {
            fprintf(stderr, "Error: Failed to allocate memory for records.\n");
            pthread_mutex_unlock(&mutex);
            return;
