void init_logging() {
    logfile = fopen("log.txt", "w");
    if (logfile == NULL) {
        perror("Failed to open log file");
        exit(1);
    }
}

void log_error(const char* message) {
    pthread_mutex_lock(&mutex);
    fprintf(stderr, "Error: %s\n", message);
    if (logfile != NULL) {
        fprintf(logfile, "Error: %s\n", message);
    }
    pthread_mutex_unlock(&mutex);
}

void log_warning(const char* message) {
    pthread_mutex_lock(&mutex);
    fprintf(stderr, "Warning: %s\n", message);
    if (logfile != NULL) {
        fprintf(logfile, "Warning: %s\n", message);
    }
    pthread_mutex_unlock(&mutex);
}

void init_tasks(int size) {
    tasks = malloc(size * sizeof(task));
    if (tasks == NULL) {
        log_error("Failed to allocate memory for tasks");
        return;
    }

    for (int i = 0; i < size; ++i) {
        pthread_mutex_lock(&mutex);
        tasks[i].priority = rand();
        tasks[i].id = i;
        pthread_mutex_unlock(&mutex);
    }

    tasks_size = size;
}

void free_tasks() {
    if (tasks != NULL) {
        free(tasks);
        tasks = NULL;
        tasks_size = 0;
    } else {
        log_warning("Attempted to free already freed memory");
    }
}
```
