void *applyFiltersThread(void *arg) {
    Data *data = ((Data**) arg)[0];
    FilterFunction* filters = (FilterFunction*) (((Data**) arg)[1]);
    size_t numElements = ((size_t*) arg)[2];

    applyFilters(data, filters, numElements);
    return NULL;
}

void processConcurrently(Data *data, FilterFunction filters[], size_t numThreads, size_t numElements) {
    pthread_t threads[numThreads];
    Data* threadArgs[3][2] = {{data, (Data*)filters}, {data + numElements / 2, (Data*)filters}}; // split data and filters for two threads

    size_t i = 0;
    for (; i < numThreads - 1 && i < 2; ++i) {
        threadArgs[i][2] = &numElements / 2; // set number of elements per thread
        pthread_create(&threads[i], NULL, applyFiltersThread, (void*) threadArgs[i]);
    }

    // process the remaining data in main thread if numThreads > 1
    if(numThreads > 1 && numElements % 2 != 0) {
        threadArgs[i][2] = &numElements / 2 + 1; // add one extra element to first thread for odd total number of elements
        applyFilters(threadArgs[i][0], (FilterFunction*) threadArgs[i][1], *((size_t*) threadArgs[i][2]));
    }

    for (i = 0; i < numThreads - 1 && i < 2; ++i) {
        pthread_join(threads[i], NULL); // wait until all threads have finished
    }
}
