int init_memory(double **doubles, char ***strings, Data ***structs, int minInt, int maxInt, 
                double minDouble, double maxDouble, size_t count) {

    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&lock);

    *doubles = malloc(count * sizeof(double));
    if (*doubles == NULL) {
        pthread_mutex_unlock(&lock);
        return 1; // memory allocation failure
    }

    *strings = malloc(count * sizeof(char*));
    if (*strings == NULL) {
        free(*doubles);
        pthread_mutex_unlock(&lock);
        return 2; // memory allocation failure
    }

    *structs = malloc(count * sizeof(Data*));
    if (*structs == NULL) {
        free(*strings);
        free(*doubles);
        pthread_mutex_unlock(&lock);
        return 3; // memory allocation failure
    }

    for (size_t i = 0; i < count; ++i) {
        (*structs)[i] = malloc(sizeof(Data));
        if ((*structs)[i] == NULL) {
            // cleanup all previously allocated memory and return error code
            for (size_t j = 0; j < i; ++j) {
