int generateRecords(long start, long end, size_t count, bool sortEnabled) {
    if (start >= end || count <= 0) return 0;
    srand(time(NULL));

    long* offsetValues = calloc(count, sizeof(long));
    int* keys = calloc(count, sizeof(int));
    Metadata* metadatas = calloc(count, sizeof(Metadata));
    Record* records = calloc(count, sizeof(Record));
    if (!offsetValues || !keys || !metadatas || !records) {
        free(offsetValues);
        free(keys);
        free(metadatas);
        free(records);
        return 0;
    }

    for (size_t i = 0; i < count; ++i) {
        offsetValues[i] = rand();
        keys[i] = rand() % (end - start + 1) + start;
        metadatas[i].creationTime = time(NULL);
        metadatas[i].lastAccessed = metadatas[i].creationTime;
        metadatas[i].uniqueId = rand();
        metadatas[i].accessCount = 0;
    }

    for (size_t i = 0; i < count; ++i) {
        records[i].value = keys[i];
        records[i].offsetValue = &offsetValues[i];
        records[i].metaData = metadatas[i];
    }

    if (sortEnabled) {
        qsort(records, count, sizeof(Record), [](const void* a, const void* b) {
            Record* recordA = (Record*)a;
            Record* recordB = (Record*)b;
            return (recordA->value - recordB->value);
        });
