typedef struct Record {
    int value;
    long* offset_value;
    time_t timestamp;
    unsigned long unique_identifier;
    int access_counter;
} Record;

int create_records(int num_sets, int *num_records, int **keys, long ***offsets) {
    srand(time(NULL)); // initialize random seed

    for (int i = 0; i < num_sets; i++){
        if(num_records[i] == 0){
            printf("Error: zero-sized batch at index %d\n", i);
            continue;
        }

        // Allocate memory for set of records
        Record *records = malloc(sizeof(Record) * num_records[i]);
        if (records == NULL){
            printf("Memory allocation failed at index %d\n", i);
            continue;
        }

        // Initialize each record in the set
        for (int j = 0; j < num_records[i]; j++) {
            records[j].value = rand(); 
            records[j].offset_value = offsets[i][j]; 
            records[j].timestamp = time(NULL); 
            records[j].unique_identifier = rand(); 
            records[j].access_counter = 0; 
        }

        // Sort the set of records in ascending order by integer value
        qsort(records, num_records[i], sizeof(Record), compare);

        // Store successful creations for each batch
        keys[i] = malloc(sizeof(int) * num_records[i]); 
        if (keys[i] == NULL){
            printf("Memory allocation failed at index %d\n", i);
            free(records); 
            continue; 
        }

        for (int j = 0; j < num_records[i]; j++) {
            keys[i][j] = records[j].value; 
        }

        // Free memory allocated to each batch after usage
        free(records); 
    }

    return EXIT_SUCCESS;
}

int compare(const void *a, const void *b) {
    Record *recordA = (Record *)a;
    Record *recordB = (Record *)b;
    return recordA->value - recordB->value;
}
