    int statusFlag;
} Record;

extern void logError(char *message);
extern void logWarning(char *message);
extern void storeInDatabase(Record *records, size_t nRecords);

void handleIoError(FILE *file) {
    if (ferror(file)) {
        perror("Read error");
        logError("Read error");
        exit(EXIT_FAILURE);
    } else if (feof(file)) {
        logWarning("End of file reached");
    }
}

void *initializeRecordsThreaded(void* arg) {
    char* filename = (char*)arg;
    FILE *offsetFile = fopen(filename, "r");
    if (offsetFile == NULL) {
        perror("Error opening file");
        logError("Error opening file");
        exit(EXIT_FAILURE);
    }

    long* offsets; // initialize this with number of lines in the file
    size_t nOffsets = 0, offsetCapacity = 1024;
    offsets = malloc(offsetCapacity * sizeof(long));
    if (offsets == NULL) {
        perror("Memory allocation error");
        logError("Memory allocation error");
        exit(EXIT_FAILURE);
    }

    while (fscanf(offsetFile, "%ld", &offsets[nOffsets]) == 1) {
        nOffsets++;

        if (nOffsets == offsetCapacity) {
            offsetCapacity *= 2;

            long* temp = realloc(offsets, offsetCapacity * sizeof(long));
            if (temp == NULL) {
                perror("Memory allocation error");
                logError("Memory allocation error");
                exit(EXIT_FAILURE);
            }

            offsets = temp;
        }

        handleIoError(offsetFile);
    }

    fclose(offsetFile);

    size_t nRecords = 1024, recordsCapacity = 1024; // initialize these based on the task requirements
    Record *records = malloc(nRecords * sizeof(Record));
    if (records == NULL) {
        perror("Memory allocation error");
        logError("Memory allocation error");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < nRecords; ++i) {
        records[i].value = rand() % 1000 + 1; // adjust this to set the correct range of random values
        records[i].timestamp = (double)clock();
        records[i].statusFlag = records[i].value < /* threshold */ ? 0 : 1; // adjust this to set the correct status flag condition
    }

    storeInDatabase(records, nRecords);

    free(offsets);
    free(records);
}
```
This function can be used as a starting point and adjusted based on specific requirements. It's worth noting that the actual implementation details for logging errors, storing in the database, or handling concurrency would require additional code which is not included here due to its complexity and lengthy nature. This also assumes certain external dependencies such as `logError`, `logWarning`, and `storeInDatabase` functions exist elsewhere in your code base.
