['```C
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdatomic.h>
#include <sys/time.h> // for gettimeofday
#include <assert.h>  // for assertions

typedef struct {
    long creation_timestamp;
    atomic_long last_accessed_timestamp;
} metadata;

typedef struct {
    double value;
    char* string;
    metadata data_metadata;
} sensor_data;

extern time_t getTimeFromRTC(void); // Assume this function returns milliseconds since epoch

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
atomic_int success_count = 0; 

// Assuming a logging API where logs are stored in memory
extern void appendLog(const char* message); 

double getRandomDouble(double min, double max) {
    return (max - min) * ((double)rand() / RAND_MAX) + min;
}

int createSensorData(sensor_data** dataArray, char** stringArray, int size) {
    if (!size || !getTimeFromRTC) return 0; // No memory allocation needed for zero or invalid RTC function

    *dataArray = calloc(size, sizeof(sensor_data));
    assert(*dataArray); // Handle allocation failure

    char** strings = calloc(size, sizeof(char*));
    assert(strings); // Handle allocation failure

    for (int i = 0; i < size; i++) {
        (*dataArray)[i].value = getRandomDouble(-10.0, 10.0); // Set a random value in [-10, 10] range

        pthread_mutex_lock(&lock); // Thread safety
        time_t timestamp = getTimeFromRTC();

        if (timestamp < 0) {
            appendLog("Error: Invalid timestamp from RTC");
            continue; // Skip this iteration 
        }

        (*dataArray)[i].data_metadata.creation_timestamp = timestamp;
        (*dataArray)[i].data_metadata.last_accessed_timestamp = timestamp;

        success_count++; // Increment successful allocation count
        pthread_mutex_unlock(&lock);
    }

    *stringArray = strings; 
    return (int)success_count; 
}
```

I have made the following assumptions:
- The RTC module provides time in milliseconds since epoch. If it doesn't, you would need to adjust the `getTimeFromRTC` function accordingly.
- I used atomic operations to make sure metadata is updated safely when multiple threads are accessing shared resources. Please note that not all platforms support atomic types (like `atomic_long`). In such cases, consider using a mutex or similar synchronization primitives.
- The external logging API functions are assumed to be implemented elsewhere and are declared as extern functions here.
- I have used dynamic memory allocation for simplicity but in real-world scenarios, static memory allocation would usually be preferred due to its predictability and efficiency (no overhead of system calls). However, this is a design trade-off based on the specific requirements of your application.
- Error checking only includes asserts which should be removed or replaced with more robust error handling strategies in production code. 
- This code doesn't handle allocation failure for string arrays and it assumes that string allocation will not fail if memory was allocated for sensor data array successfully. It is a potential area of improvement as it could lead to memory leaks.
- Logging errors when getting timestamp from RTC module could be helpful in debugging and identifying issues with the real time clock module. 
- The atomic variable `success_count` tracks the number of successful sensor data structures created, ensuring thread safety while updating this count. 
- I have used pthread mutex to ensure only one thread can access shared resources at a time (i.e., updating success_count and logging errors). This is to prevent data races and provide thread-safety. However, in more complicated scenarios, you may want to use higher level constructs like `std::mutex` or `atomic<int>` from C++11 standard library for better control over locking behavior.
']

