void allocateAndInit(long *offsets, int sizeOffsets, 
                     int **keys, int sizeKeys, 
                     Record ***records, int sizeRecords) {

    // Error checking for valid sizes
    if (sizeOffsets <= 0 || sizeKeys <= 0 || sizeRecords <= 0){
        printf("Invalid array sizes.\n");
        return;
    }

    srand(time(NULL)); // Seed the random number generator

    // Allocate memory for arrays
