    if (*offsets == NULL) { printf("Memory allocation failed."); return; }

    *keys = (int*)malloc(sizeKeys * sizeof(int));
    if (*keys == NULL) { free(*offsets); printf("Memory allocation failed."); return; }

    *records = (Record**)malloc(sizeRecords * sizeof(Record*));
    if (*records == NULL) { free(*offsets); free(*keys); printf("Memory allocation failed."); return; }

    for (int i = 0; i < sizeRecords; i++){
        // Allocate memory for Record structures
        (*records)[i] = (Record*)malloc(sizeof(Record));
        if ((*records)[i] == NULL) { 
            printf("Memory allocation failed."); 
