The Java method to generate MD5 hash:

```java
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class Main {

    public static void main(String[] args) {
        // Testing the C function and Java method here
    }

    private static String generateMD5Hash(String input){
        try{
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes());
            return convertByteToString(messageDigest);
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    private static String convertByteToString(byte[] byteData){
        StringBuilder sb = new StringBuilder();
        for (byte bytes : byteData) {
            sb.append(Integer.toString((bytes & 0xff) + 0x100, 16).substring(1));
        }
        return sb.toString();
    }
