typedef struct {
    int value;
    long* offsetValue;
    Metadata metadata;
} Record;

int initRecords(Record** records, long **offsets, int *keys, size_t n, 
                void (*externalDataCallback)(long*, size_t)) {
    // Allocate memory for the arrays.
    *records = calloc(n, sizeof(Record));
    if (!*records) return -1;

    *offsets = malloc(n * sizeof(long));
    if (!*offsets) {
        free(*records);
        return -2;
    }

    *keys = calloc(n, sizeof(int));
    if (!*keys) {
        free(*records);
        free(*offsets);
        return -3;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long currentTimestamp = ts.tv_sec * 1000 + ts.tv_nsec / 1e6;

    for (size_t i = 0; i < n; ++i) {
        // Set the value of each record's int field to a random value within a given range.
        (*records)[i].value = rand() % INT_MAX;  // Replace with your own implementation if needed

        // Set the offsetValue pointer.
        (*records)[i].offsetValue = &(*offsets)[i];

        // Initialize metadata fields.
        (*records)[i].metadata.creationTimestamp = currentTimestamp;
        (*records)[i].metadata.lastAccessedTimestamp = 0;
    }

    if (externalDataCallback) {
        externalDataCallback(*offsets, n);
    }

    return 0;
}
```
