                            int minKey, int maxKey, double minValue, double maxValue) {
    // Allocate memory for the arrays
    long* offsets = malloc(arraySize * sizeof(long));
    int* keys = calloc(arraySize, sizeof(int));
    double* values = malloc(arraySize * sizeof(double));
    if (offsets == NULL || keys == NULL || values == NULL) {
        printf("Memory allocation failed.\n");
        free(offsets); free(keys); free(values);  // Free previously allocated memory
        return -1;
    }

    // Read offset values from the configuration file
    FILE* configFile = fopen(filename, "r");
    if (configFile == NULL) {
        printf("Failed to open configuration file.\n");
        free(offsets); free(keys); free(values);  // Free previously allocated memory
        return -1;
    }

    for (size_t i = 0; i < arraySize; ++i) {
        if (fscanf(configFile, "%ld", &offsets[i]) != 1) {
            printf("Error reading offset value from configuration file.\n");
            free(offsets); free(keys); free(values);  // Free previously allocated memory
            fclose(configFile);
            return -1;
        }
    }

    fclose(configFile);  // Close the configuration file after reading

    // Initialize the key array with unique integer values within a given range, ensuring no duplicates
    srand(time(NULL));
    int* chosenKeys = calloc((size_t)(maxKey - minKey + 1), sizeof(int));
    for (size_t i = 0; i < arraySize; ++i) {
        do {
            keys[i] = rand() % (maxKey - minKey + 1) + minKey;
        } while (chosenKeys[keys[i] - minKey]);
        ++chosenKeys[keys[i] - minKey];
