    free(chosenKeys);  // Free the temporary array

    // Initialize the value array with random floating-point numbers within a specified range
    for (size_t i = 0; i < arraySize; ++i) {
        values[i] = ((double)rand() / RAND_MAX) * (maxValue - minValue) + minValue;
    }

    // Allocate memory and initialize records
    Record* records = malloc(arraySize * sizeof(Record));
    if (records == NULL) {
        printf("Memory allocation failed.\n");
        free(offsets); free(keys); free(values);  // Free previously allocated memory
        return -1;
    }

    for (size_t i = 0; i < arraySize; ++i) {
        records[i].offset = offsets[i];
        records[i].key = keys[i];
        records[i].value = values[i];
    }

    // Free all allocated memory before returning
    free(offsets);
    free(keys);
    free(values);
    free(records);

    return arraySize;  // Return the number of successfully created records
