int create_records(long* offsets, int* keys, Record* records, int initial_pool_size, int min_random, int max_random, char* logfile_path) {
    FILE *logfile = fopen(logfile_path, "w");

    if (logfile == NULL) {
        printf("Error opening the file.\n");
        return -1;
    }

    srand(time(NULL));
    int count = 0;

    pthread_mutex_lock(&lock);  // lock for thread safety
    for (int i = 0; i < initial_pool_size; ++i) {
        offsets[i] = rand() % max_random + min_random;
        ++count;
        keys[i] = rand();  // example key generation
        records[i].value = rand() % max_random + min_random;
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        long current_timestamp = ts.tv_sec * (int)1e9 + ts.tv_nsec;  // high-resolution timestamp
        records[i].metadata.creation_timestamp = current_timestamp;
        records[i].metadata.last_accessed_timestamp = current_timestamp;
        fprintf(logfile, "Record created at %ld with value: %d\n", current_timestamp, records[i].value);
    }
    pthread_mutex_unlock(&lock);  // unlock after operation is complete

    fclose(logfile);
    return count;
}
