import os
from threading import Lock
lock = Lock()

def execute_file(filename):
    lock.acquire() # acquire lock before executing file
    if not os.path.exists(filename) or not os.access(filename, os.X_OK):
        print("File does not exist or is not executable")
        return False

    try:
        exec(open(filename).read()) # execute the python file
        lock.release() # release lock after executing file
        return True
    except Exception as e:
        lock.release() # release lock if there was an error during execution
        print("Error while executing file", filename)
        print(e)
        return False
```
