void change_extension(char* filename, const char* new_ext) {
    char* last_dot = strrchr(filename, '.'); // find the last dot in the filename

    if(!last_dot) {
        sprintf(filename, "%s.%s", filename, new_ext); // append new extension if there is no existing one
    } else {
        strcpy(last_dot + 1, new_ext); // replace the old extension with the new one
    }
}
