```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} record;

void manage_data(int num_offsets, int num_keys, int num_records, int min_val, int max_val) 
{
    // Validate user input to ensure it does not exceed system limits
    if (num_offsets <= 0 || num_keys <= 0 || num_records <= 0 || min_val < 1 || max_val > 2147483647 / (max_val - min_val)) 
    {
        printf("Invalid input values\n");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for dynamic data structures
    long* offsets = malloc(num_offsets * sizeof(long));
    int* keys = malloc(num_keys * sizeof(int));
    record* records = malloc(num_records * sizeof(record));

    // Check if memory allocation was successful for all arrays
    if (offsets == NULL || keys == NULL || records == NULL) 
    {
        printf("Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL)); // Seed the random number generator

    // Initialize all arrays and generate a random integer for each record
    for (int i = 0; i < num_records; i++) 
