```c
#include <stdlib.h>
#include <string.h>
#include <time.h>
#define PREDEFINED_STRINGS 10

typedef struct {
    int value;
    char* str;
} Record;

const char *predefinedStrings[PREDEFINED_STRINGS] = {"Alice", "Bob", "Charlie", "David", "Eve", "Frank", "Grace", "Heidi", "Ivan", "John"};

Record* initializeRecords(int size, const char *predefinedStrings[], int predefinedCount) {
    if (size <= 0) return NULL;

    long *offsets = malloc(sizeof(long) * size);
    int *keys = malloc(sizeof(int) * size);
    Record *records = malloc(sizeof(Record) * size);

    if (!offsets || !keys || !records) {
        free(offsets);
        free(keys);
        free(records);
        return NULL;
    }

    srand((unsigned int)time(NULL));
    for (int i = 0; i < size; ++i) {
        offsets[i] = rand() % 1000000L;
        keys[i] = rand() % 101;

        records[i].value = rand() % 101;
        if (predefinedStrings && i < predefinedCount) {
            records[i].str = malloc(sizeof(char) * (strlen(predefinedStrings[i]) + 1));
            if (!records[i].str) goto free_all;  // handle memory allocation failure
            strcpy(records[i].str, predefinedStrings[i]);
        } else {
            char name[20];
            sprintf(name, "name%d", i);
            records[i].str = malloc(sizeof(char) * (strlen(name) + 1));
            if (!records[i].str) goto free_all;  // handle memory allocation failure
            strcpy(records[i].str, name);
