config_setting* read_settings(const char* filename) {
    FILE* file = fopen(filename, "r");
    if (file == NULL) {
        perror("Failed to open the file");
        return NULL;
    }

    // dynamically allocated array of config_setting structures.
    config_setting* settings = malloc(sizeof(config_setting)); 
    char buffer[256];
    int setting_count = 0;
    while (fgets(buffer, sizeof(buffer), file)) {
        char* equal_sign = strchr(buffer, '=');
        if (equal_sign == NULL) continue; // invalid format

        *equal_sign = '\0'; 
        int setting_name = atoi(buffer); 

        char* value = malloc(strlen(equal_sign + 1) + 1);
        strcpy(value, equal_sign + 1); 

        settings[setting_count].setting_name = setting_name;
        settings[setting_count].value = value;
        setting_count++;

        // reallocate memory for the array.
        settings = realloc(settings, sizeof(config_setting) * (setting_count + 1));
    }

    fclose(file);
    return settings;
}
