#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdatomic.h>

typedef struct {
    time_t creationTimestamp;
    time_t lastAccessedTimestamp;
} Metadata;

typedef struct {
    int value;
    long* offsetValuePtr;
    Metadata metadata;
} Record;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
atomic_int totalRecords = 0;
size_t allocatedMemory = 0;
size_t memoryThreshold = 1024 * 1024 * 1024; // 1GB

void* allocateOrFail(size_t size) {
    while (allocatedMemory + size > memoryThreshold) {
        if (pthread_mutex_lock(&lock)) {
            return NULL; // failed to acquire lock, handle this error as you see fit.
        }
        if (allocatedMemory + size <= memoryThreshold) {
            allocatedMemory += size;
            pthread_mutex_unlock(&lock);
            break;
        } else {
            pthread_mutex_unlock(&lock);
            sleep(1); // Exponential backoff.
        }
    }
    return malloc(size);
}

int createRecords(long* offsets, int numOffsets, void (*sortFunc)(Record*, int), long (*getDataSourceValue)()) {
    srand(time(NULL));

    Record* records = allocateOrFail(numOffsets * sizeof(Record));
    if (!records) return -1; // Memory allocation failure.

    for (int i = 0; i < numOffsets; ++i) {
        offsets[i] = getDataSourceValue();
        records[i].value = rand() % 100; // Random value within range of 0 to 99.
        records[i].offsetValuePtr = &offsets[i];
        time(&records[i].metadata.creationTimestamp);
        atomic_fetch_add(&totalRecords, 1);
    }

    sortFunc(records, numOffsets); // Sort the records based on user's criteria.

    free(records);
    return 0;
}
```
