#include <pthread.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct {
    time_t creationTime;
    time_t lastAccessedTime;
} Metadata;

typedef struct Node{
    int value;
    char* str;
    Metadata meta;
    struct Node *next;
}Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; 

typedef struct {
    Node *head;
    int count;
} List;

int createNodes(List* list, int numOfNodes) {
    pthread_mutex_lock(&lock);

    srand((unsigned)time(NULL)); // seed the random number generator

    for (int i = 0; i < numOfNodes; ++i) {
        Node *newNode = malloc(sizeof(Node)); 
        if (newNode == NULL){
            pthread_mutex_unlock(&lock);
            return -1; // Allocation failure.
        }

        newNode->value = rand(); // Assuming random int range is handled in external config file.
        newNode->str = malloc(20); // Dynamically allocating string for example.
        if (newNode->str == NULL){
            free(newNode);
            pthread_mutex_unlock(&lock);
            return -1; // Allocation failure.
        } 

        time(&newNode->meta.creationTime);
        newNode->meta.lastAccessedTime = newNode->meta.creationTime;

        newNode->next = list->head;
        list->head = newNode;
    } 

    list->count += numOfNodes;

    pthread_mutex_unlock(&lock);
    return 0; // Success.
}
```
