    setting->setting_name = malloc(strlen(line) + 1);
    strcpy(setting->setting_name, line);

    setting->value = malloc(strlen(equals_pos + 1));
    strcpy(setting->value, equals_pos + 1);

    return setting;
}

// Sort an array of ConfigSettings using bubble sort
void sort_settings(ConfigSetting** settings, int num_settings) {
    for (int i = 0; i < num_settings - 1; i++) {
        for (int j = 0; j < num_settings - i - 1; j++) {
            if (strcmp(settings[j]->value, settings[j + 1]->value) > 0) {
                ConfigSetting* temp = settings[j];
                settings[j] = settings[j + 1];
                settings[j + 1] = temp;
            }
        }
    }
}

// Process a line from the config file into a ConfigSetting struct and store it in Redis if necessary
void process_line(char* line, redis3m::connection::ptr_t conn) {
    ConfigSetting* setting = parse_line(line);

    // Store this setting in Redis for future use
