```c
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct {
    time_t creationTimestamp;
    time_t lastAccessedTimestamp;
} Metadata;

typedef struct Node {
    int value;
    long *offset;
    Metadata metadata;
} Node;

int allocateNodes(Node **nodes, size_t n) {
    // Allocating memory for nodes array once.
    *nodes = calloc(n, sizeof(Node));
    if(*nodes == NULL) return 1;

    int successCount = 0;
    time_t currentTime;

    for (size_t i = 0; i < n; ++i) {
        // Allocating memory for long offset separately.
        (*nodes)[i].offset = malloc(sizeof(long));

        if((*nodes)[i].offset == NULL){
            free(*nodes);
            return 1;
        } else {
            successCount++;

            time(&currentTime);
            Metadata meta = { currentTime, currentTime };
            (*nodes)[i].metadata = meta;
        }
    }

    // Sorting nodes based on their int values in ascending order. 
    qsort(*nodes, n, sizeof(Node), compareNodes);
    return successCount;
}

int compareNodes (const void * a, const void * b) {
    Node *nodeA = (Node *)a;
    Node *nodeB = (Node *)b;

    if(nodeA->value < nodeB->value) return -1;
    if(nodeA->value > nodeB->value) return 1;

    // If values are equal, sort by creation timestamp.
    if(difftime(nodeA->metadata.creationTimestamp, nodeB->metadata.creationTimestamp) < 0) {
        return -1;
    } else if (difftime(nodeA->metadata.creationTimestamp, nodeB->metadata.creationTimestamp) > 0) {
        return 1;
    }

    return 0;
}
```
This code uses the `qsort` function from the C standard library for sorting nodes in ascending order based on their int values and creation timestamps, which is an efficient sorting algorithm. The time complexity of this algorithm is O(n log n). Memory allocation calls are minimized by allocating memory for all 'offset' pointers together at once and then individually for each 'Node'. 

The function `allocateNodes` returns the number of nodes successfully created, which can be useful in case some allocation fails. If any allocation fails (and thus calloc or malloc return NULL), the function frees all previously allocated memory with `free()` and returns an error code (1).

This is a simple implementation and doesn't include error checking for potential system-related failures, such as running out of memory, I/O errors, etc. This would require additional code to handle these conditions appropriately based on the specific requirements and constraints of your application.
