int allocateAndInitialize(double** doubles, int** keys, DataRecord*** records, 
                          size_t numRecords, int minRandomVal, int maxRandomVal) {
    srand(time(NULL)); // Initialize random seed

    *doubles = (double*) malloc(numRecords * sizeof(double));
    if(*doubles == NULL) return -1;

    *keys = (int*) malloc(numRecords * sizeof(int));
    if(*keys == NULL) { free(*doubles); return -1; }

    *records = (DataRecord**) malloc(numRecords * sizeof(DataRecord*));
    if(*records == NULL) { free(*doubles); free(*keys); return -1; }

    int successCount = 0;

    for(size_t i=0; i<numRecords; i++) {
        (*doubles)[i] = (double)(rand() % 10000 + 1) / 100.0; // Random double value
        (*keys)[i] = rand() % maxRandomVal + minRandomVal; // Random int value within range

        DataRecord* record = malloc(sizeof(DataRecord));
        if(record == NULL) continue; // Ignore allocation failure, move to next record

        record->correspondingDoubleValue = &(*doubles)[i]; 
        record->value = (*keys)[i];
        record->metadata.creationTime = time(NULL); // Current time
        record->metadata.lastAccessedTime = 0; // Not accessed yet

        (*records)[i] = record;
        successCount++;
    }

    return successCount;
}
