#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
    long *offset;
} Record;

typedef struct {
    time_t createdAt;
    time_t accessedAt;
    char userID[20];
    unsigned int accessCount;
} Metadata;

typedef struct {
    char name[50];
    char email[50];
} User;

Record *records;
Metadata *metadatas;
User *users;
long offsets[5];
int keys[5];

void swap(Record *a, Record *b) {
    Record temp = *a;
    *a = *b;
    *b = temp;
}

int partition (Record arr[], int low, int high){
    int pivot = arr[high].value; 
    int i = (low - 1);

    for (int j = low; j <= high-1; j++) {
        if (arr[j].value < pivot) {
            i++;
            swap(&arr[i], &arr[j]);
        }
    }
    swap(&arr[i + 1], &arr[high]);
    return (i + 1);
}

void quickSort(Record arr[], int low, int high) {
    if (low < high){
        int pi = partition(arr, low, high);

        quickSort(arr, low, pi - 1);
        quickSort(arr, pi + 1, high);
    }
}

void sort() {
    srand(time(0));

    for (int i = 0; i < 5; i++) {
        keys[i] = rand();  // initialize with random value within a given range.

        offsets[i] = rand();
        records[i].offset = &offsets[i];

        metadatas[i].createdAt = time(0);
        metadatas[i].accessedAt = time(0);
        sprintf(metadatas[i].userID, "%d", rand() % 1000 + 1);
        metadatas[i].accessCount = 0;

        records[i].value = keys[i]; // use the random key as value of record.
    }

    quickSort(records, 0, 4);
}

int main() {
    records = malloc(sizeof(Record) * 5);
    if (records == NULL) return -1; // handle allocation failure gracefully.

    offsets = malloc(sizeof(long) * 5);
    if (offsets == NULL) return -2; // handle allocation failure gracefully.

    keys = malloc(sizeof(int) * 5);
    if (keys == NULL) return -3; // handle allocation failure gracefully.

    metadatas = calloc(5, sizeof(Metadata));
    if (metadatas == NULL) return -4; // handle allocation failure gracefully.

    users = malloc(sizeof(User) * 5);
    if (users == NULL) return -5; // handle allocation failure gracefully.

    sort();

    free(records);
    free(offsets);
    free(keys);
    free(metadatas);
    free(users);

    return 0;
}
