#include <pthread.h>
#include <stdlib.h>
#include <assert.h>

typedef struct {
    int value;
} record;

typedef struct {
    long *offsets;
    int *keys;
    record **records;
    pthread_mutex_t mutex;
    int size;
} shared_data;

shared_data data;

void init_task(int size) {
    assert((data.offsets = malloc(size * sizeof(long))) != NULL);
    assert((data.keys = calloc(size, sizeof(int))) != NULL);
    assert((data.records = malloc(size * sizeof(record*))) != NULL);

    for (int i = 0; i < size; i++) {
        assert((data.records[i] = malloc(sizeof(record))) != NULL);
        data.records[i]->value = rand();
    }

    pthread_mutex_init(&data.mutex, NULL);
    data.size = size;
}

void access_task(int index) {
    assert(index >= 0 && index < data.size); // Ensure valid index

    pthread_mutex_lock(&data.mutex);

    printf("Offset: %ld, Key: %d, Value: %d\n", 
           data.offsets[index], data.keys[index], data.records[index]->value);

    pthread_mutex_unlock(&data.mutex);
}

void modify_task(int index, long offset, int key, record *record) {
    assert(index >= 0 && index < data.size); // Ensure valid index

    pthread_mutex_lock(&data.mutex);

    data.offsets[index] = offset;
    data.keys[index] = key;
    data.records[index]->value = record->value;

    pthread_mutex_unlock(&data.mutex);
}

void cleanup_task() {
    for (int i = 0; i < data.size; i++) {
        free(data.records[i]);
    }

    free(data.offsets);
    free(data.keys);
    free(data.records);

    pthread_mutex_destroy(&data.mutex);
}
