#include <string.h>

typedef struct {
    long session_id;
    time_t timestamp;
} SessionRecord;

typedef struct {
    size_t capacity;
    size_t count;
    long *session_ids;
    time_t *timestamps;
    SessionRecord *records;
} SessionManager;

SessionManager* create_manager(size_t initial_capacity) {
    SessionManager *manager = malloc(sizeof(SessionManager));

    if (manager == NULL) {
        return NULL;  // Failed to allocate manager
    }

    manager->session_ids = malloc(initial_capacity * sizeof(*manager->session_ids));
    manager->timestamps = malloc(initial_capacity * sizeof(*manager->timestamps));
    manager->records = malloc(initial_capacity * sizeof(*manager->records));

    if (manager->session_ids == NULL || manager->timestamps == NULL || manager->records == NULL) {
        free(manager->session_ids);
        free(manager->timestamps);
        free(manager->records);
        free(manager);
        return NULL;  // Failed to allocate arrays
    }

    manager->capacity = initial_capacity;
    manager->count = 0;
    return manager;
}

void resize_arrays(SessionManager *manager, size_t new_size) {
    manager->session_ids = realloc(manager->session_ids, new_size * sizeof(*manager->session_ids));
    manager->timestamps = realloc(manager->timestamps, new_size * sizeof(*manager->timestamps));
    manager->records = realloc(manager->records, new_size * sizeof(*manager->records));

    if (new_size > manager->capacity) {
        memset(manager->session_ids + manager->capacity, 0, (new_size - manager->capacity) * sizeof(*manager->session_ids));
        memset(manager->timestamps + manager->capacity, 0, (new_size - manager->capacity) * sizeof(*manager->timestamps));
        memset(manager->records + manager->capacity, 0, (new_size - manager->capacity) * sizeof(*manager->records));
    }

    if (manager->session_ids && manager->timestamps && manager->records) {
        manager->capacity = new_size;
    }
}

void add_session(SessionManager *manager, long session_id, time_t timestamp) {
    if (manager->count == manager->capacity) {
        resize_arrays(manager, manager->capacity * 2);
    }

    manager->session_ids[manager->count] = session_id;
    manager->timestamps[manager->count] = timestamp;
    manager->records[manager->count].session_id = session_id;
    manager->records[manager->count].timestamp = timestamp;
    ++manager->count;
}
