    mgr->records = calloc(initialSize, sizeof(*mgr->records));
    if (mgr->records == NULL) {
        free(mgr);
        return NULL;
    }

    return mgr;
}

void destroy_session_manager(SessionManager *mgr) {
    pthread_mutex_destroy(&(mgr->lock));
    free(mgr->records);
    free(mgr);
}

int add_session(SessionManager *mgr, long id, time_t timestamp) {
    pthread_mutex_lock(&(mgr->lock));

    if (mgr->size == mgr->capacity) {
        size_t newCapacity = mgr->capacity * 2;

        SessionRecord *newRecords = realloc(mgr->records, newCapacity * sizeof(*newRecords));
        if (newRecords == NULL) {
            pthread_mutex_unlock(&(mgr->lock));
            return -1; // Memory allocation failed
        }

        mgr->capacity = newCapacity;
        mgr->records = newRecords;
    }

    mgr->records[mgr->size].id = id;
    mgr->records[mgr->size].timestamp = timestamp;
    ++(mgr->size);

    pthread_mutex_unlock(&(mgr->lock));

    return 0; // Success
}

void clear_sessions(SessionManager *mgr) {
