    insertNode(&head, newNode(2));
    insertNode(&head, newNode(9));
    printList(head);  // Should print: 2 -> 5 -> 9 -> NULL

    deleteNode(&head, 5);
    printList(head);  // Should print: 2 -> 9 -> NULL

    return 0;
}

// Function to create a new node with given value
Node* newNode(int val) {
    Node *new_node = (Node*) malloc(sizeof(Node));

    if (new_node == NULL) {
        printf("Memory allocation failed!\n");
        exit(-1);
    } 

    // Initialize new node with given value, timestamp and offset
    new_node->value = val;
    time(&new_node->meta.creation);
    new_node->offset = malloc(sizeof(long));

    return new_node;
}

// Function to insert a node in linked list (in sorted order)
void insertNode(Node** head, Node* new_node) {
    pthread_mutex_lock(&lock); // lock mutex before changing data structure

    Node* current;

    if (*head == NULL || (*head)->value >= new_node->value) {
        new_node->next = *head;
        *head = new_node;
    } else {
        current = *head;

        while (current->next != NULL && current->next->value < new_node->value) {
            current = current->next;
        }

        new_node->next = current->next;
        current->next = new_node;
    }

    pthread_mutex_unlock(&lock); // unlock mutex after changing data structure
}

// Function to delete a node from linked list by value
void deleteNode(Node** head, int valueToDelete) {
    pthread_mutex_lock(&lock);  // lock mutex before changing data structure

    Node* temp = *head;
    Node* prev = NULL;

    if (temp != NULL && temp->value == valueToDelete) {
        *head = temp->next;
        free(temp);
        return;
    }

    while (temp != NULL && temp->value != valueToDelete) {
        prev = temp;
        temp = temp->next;
    }

    if (temp == NULL) return; // node not found

    prev->next = temp->next;

    free(temp);

    pthread_mutex_unlock(&lock);  // unlock mutex after changing data structure
}
```
