```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    time_t creation;
    time_t lastAccessed;
} Metadata;

typedef struct Node {
    int value;
    long offset;
    Metadata metadata;
    struct Node *next;
} Node;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
int nodeCount = 0;
FILE* logFile = NULL; // You can initialize this with stdout for console logging.

void swap(Node *a, Node *b) {
    int temp = a->value;
    a->value = b->value;
    b->value = temp;
}

int partition (Node arr[], int low, int high) {
    int pivot = arr[high].value; 
    int i = (low - 1);

    for (int j = low; j <= high- 1; j++) {
        if (arr[j].value < pivot) {
            i++;
            swap(&arr[i], &arr[j]);
        }
    }
    swap(&arr[i + 1], &arr[high]);
    return (i + 1);
}

void quickSort(Node arr[], int low, int high) {
    if (low < high) {
        int pi = partition(arr, low, high);
        quickSort(arr, low, pi - 1);
        quickSort(arr, pi + 1, high);
    }
}

int createNodeList(Node **head, int size){
    if (logFile) fprintf(logFile, "Creating nodes...\n");
    for(int i = 0; i < size; i++){
        Node *new_node = malloc(sizeof(Node));
        if(!new_node){
            if (logFile) fprintf(logFile, "Failed to allocate memory for node %d\n", i);
            return -1;
        }
        new_node->value = rand() % 100;
        time(&new_node->metadata.creation);
        new_node->next = *head;

        pthread_mutex_lock(&lock);
        nodeCount++;
        pthread_mutex_unlock(&lock);

        if (logFile) fprintf(logFile, "Created node %d with value %d\n", i, new_node->value);

        *head = new_node;
    }

    Node array[size]; // This is a workaround for quicksort. Quicksort would work directly on linked list which can be complex to implement.
    int count = 0;
    for(Node* temp = *head; temp != NULL; temp = temp->next) {
        array[count++] = *temp;
    }

    quickSort(array, 0, size - 1); // Sorting nodes.
    for (int i = 0; i < count; i++){
        (*head)->value = array[i].value;
        head = &((*head)->next);
    }
    return nodeCount;
}
```
In the code above, we created a linked list and each node contains an integer value, a pointer to its offset in memory (which is just for demonstration purposes) and metadata structure with creation and last accessed timestamps. The createNodeList function generates nodes of random integer values and sorts them using quicksort before returning the number of successfully created nodes.

We have also implemented logging mechanism to console or file, tracking node count and handling memory allocation failure. For thread safety pthread library is used.

