        record.doubles = doubles;
        record.strings = strings;
        record.sensor_data = sensor_data;
        record.metadata = metadata;

        // handle the record however you want, e.g., print it or store it in a file
    }

    free(offsets);  // free allocated memory before returning
    free(keys);
    free(doubles);
    for (i = 0; i < size; ++i) {
        free(strings[i]);
        free(sensor_data[i]->string);
        free(sensor_data[i]);
        free(metadata[i]);
