int createArrays(char* inputStrings[], size_t numOfInputs, long** offsetValues, int** keys, record*** records) {
    if (numOfInputs < 1 || !inputStrings) {
        fprintf(stderr, "Invalid number of inputs or NULL pointer\n");
        return -1;
    }

    *offsetValues = malloc(sizeof(long) * numOfInputs);
    if (!(*offsetValues)) {
        perror("Failed to allocate memory for offset values");
        return -1;
    }

    *keys = malloc(sizeof(int) * numOfInputs);
    if (!(*keys)) {
        perror("Failed to allocate memory for keys");
        free(*offsetValues);
        return -1;
    }

    *records = malloc(sizeof(record*) * numOfInputs);
    if (!(*records)) {
        perror("Failed to allocate memory for records");
        free(*keys);
        free(*offsetValues);
        return -1;
    }

    for (size_t i = 0; i < numOfInputs; ++i) {
        size_t len = strlen(inputStrings[i]);
        if (len > MAX_STRING_LENGTH) {
            fprintf(stderr, "String at index %zu exceeds max length\n", i);
            // This is a bit tricky. We need to free the memory we've already allocated in this case...
            for (size_t j = 0; j < i; ++j) {
                if ((*records)[j]) free((*records)[j]);
            }
            free(*keys);
            free(*offsetValues);
            return -1;
        }

        (*records)[i] = malloc(sizeof(record));
        if (!(*records)[i]) {
            perror("Failed to allocate memory for record");
            // We need to clean up again...
            free(*keys);
            free(*offsetValues);
            for (size_t j = 0; j < i; ++j) {
