['Here is a simple C code to implement the function according to the requirements:
```c
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int value;
} Record;

static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

int initialize(long* offsets, size_t offsetSize, int** keys, size_t keySize, Record*** records, size_t recordSize) {
    if (offsetSize <= 0 || keySize <= 0 || recordSize <= 0) return -1; // Input validation

    *offsets = malloc(sizeof(long) * offsetSize); // Allocate memory for offsets
    if (*offsets == NULL) return -1;  // Handle allocation failure

    srand((unsigned int) time(NULL)); // Seed random number generator

    pthread_mutex_lock(&lock); // Lock to prevent concurrent access

    *keys = malloc(sizeof(int) * keySize); // Allocate memory for keys
    if (*keys == NULL) { 
        free(*offsets); 
        pthread_mutex_unlock(&lock);
        return -1;  
    } 

    *records = malloc(sizeof(Record*) * recordSize); // Allocate memory for records array
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        pthread_mutex_unlock(&lock);
        return -1; 
    }

    for (size_t i = 0; i < recordSize; ++i) { // Allocate memory for each Record
        (*records)[i] = malloc(sizeof(Record));
        if ((*records)[i] == NULL) { 
            free(*offsets);
            free(*keys);
            for (size_t j = 0; j < i; ++j) { // Free previously allocated Records
                free((*records)[j]);
            }
            free(*records);
            pthread_mutex_unlock(&lock);
            return -1; 
        }
    }

    for (size_t i = 0; i < recordSize; ++i) { // Set Record values to random ints
        (*records)[i]->value = rand(); 
    }

    pthread_mutex_unlock(&lock); // Unlock after all allocations are done

    return 0; // Return success
}

void freeAll(long* offsets, int** keys, Record*** records, size_t recordSize) {
    if (offsets != NULL) free(offsets);
    if (keys != NULL) free(*keys);
    if (*records != NULL) { 
        for (size_t i = 0; i < recordSize; ++i) { // Free each Record
            if ((*records)[i] != NULL) free((*records)[i]);
        }
        free(*records); 
    }
}
```
The `initialize` function allocates memory for offsets, keys and an array of records, sets the values of the records to random integers within a specified range, and handles allocation failures. The code also uses a mutex lock to ensure thread-safe access when dealing with shared data. 

Please note that you would need to modify this according to your specific use case or requirements including error checking, concurrency handling, memory management, etc. Please always remember to free the memory after usage to avoid memory leaks and other issues such as segmentation faults.
']

