typedef struct {
    long* offsets;
    int* keys;
    Record** records;  // array of pointers to Records
    pthread_mutex_t mutex;
} DataStructures;

DataStructures* init_data_structures(size_t size, const char* filename) {
    assert(size > 0 && "Array sizes must be positive");
    assert(filename != NULL && "File path cannot be null");

    // Dynamically allocate memory for data structures
    DataStructures* ds = (DataStructures*) malloc(sizeof(DataStructures));
    if (!ds) {
        perror("Failed to allocate memory for DataStructures");
        return NULL;  // Return null on failure to indicate error
    }

    ds->offsets = (long*) calloc(size, sizeof(long));
    ds->keys = (int*) malloc(size * sizeof(int));
    ds->records = (Record**) malloc(size * sizeof(Record*));

    if (!ds->offsets || !ds->keys || !ds->records) {
        perror("Failed to allocate memory for arrays");
        free_data_structures(ds);  // Free already allocated memory on failure
        return NULL;
    }

    // Initialize each record in records array with a single int value of 0
    for (size_t i = 0; i < size; ++i) {
        ds->records[i] = (Record*) malloc(sizeof(Record));
        if (!ds->records[i]) {
            perror("Failed to allocate memory for a record");
            free_data_structures(ds);  // Free already allocated memory on failure
            return NULL;
        }

        ds->records[i]->value = 0;
    }

    /* This is where you would read offset values from an external source and
     * initialize the offsets array with these values. For simplicity, it's not 
     * included in this example. */

    // Initialize mutex for thread-safe access to data structures
    if (pthread_mutex_init(&ds->mutex, NULL) != 0) {
        perror("Failed to initialize mutex");
        free_data_structures(ds);  // Free already allocated memory on failure
        return NULL;
    }

    return ds;
}

void free_data_structures(DataStructures* ds) {
    assert(ds != NULL && "Cannot free null DataStructures pointer");

    pthread_mutex_destroy(&ds->mutex);  // Destroy mutex to avoid memory leaks

    if (ds->offsets) {
        free(ds->offsets);  // Free offsets array
        ds->offsets = NULL;
    }

    if (ds->keys) {
        free(ds->keys);  // Free keys array
        ds->keys = NULL;
    }

    if (ds->records) {
        for (size_t i = 0; i < sizeof(ds->records)/sizeof(Record*); ++i) {
            free(ds->records[i]);  // Free each record in records array
            ds->records[i] = NULL;
        }

        free(ds->records);  // Free records array
        ds->records = NULL;
    }

    free(ds);  // Finally, free DataStructures pointer
}
```
