['Below is a simplified version of C function which creates multiple arrays of different types and uses loops to set random values in them. It also checks for memory allocation failures and free allocated memories before returning. Additionally, it marks new events as active or archived through an additional parameter. 

```c
#include <stdlib.h>
#include <time.h>

typedef struct {
    char source[20];
    char type[20];
} MetaData;

typedef struct {
    int value;
    long *timestamp;
    MetaData metadata;
} Event;

int create_events(Event **events, size_t num_events, int active) {
    srand((unsigned int)time(NULL)); // Seed the random number generator.

    if (active != 0 && active != 1) return -2;  // Check valid value of active flag.
    *events = malloc(num_events * sizeof(Event));  
    if (*events == NULL) return -1; // Check for memory allocation failure.

    int i, count = 0;
    for (i = 0; i < num_events; i++) {
        Event event;
        long *timestamp = malloc(sizeof(long));  // Allocate memory for timestamp.
        if (timestamp == NULL) return -1; // Check for memory allocation failure.

        *timestamp = time(NULL);  // Initialize timestamp.
        event.value = 1 + rand() % 100;   // Set value to random within range of [1, 100].
        event.timestamp = timestamp;
        strcpy(event.metadata.source, "source"); // Dummy data for meta-data.
        strcpy(event.metadata.type, "type");

        if (active) {  
            (*events)[count] = event;    // If active flag is set, add to events array.
            count++;
        } else {
            free(timestamp);  // If not active, free the allocated memory without adding to events array.
        }
    }

    if (active == 0) *events = realloc(*events, count * sizeof(Event)); // Reallocate memory based on successful counts.

    return count;   // Return number of successfully created active events or total events if active flag is 1.
}
```

Please remember that this is a simplified solution and might need to be adjusted according to the actual requirements, constraints, and integration points with other systems in a larger codebase. Also note that error checking and handling are kept minimalistic here for brevity. In real-world applications, consider implementing more comprehensive error checks and handling strategies to ensure robustness of your implementation.
']

