```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int value;
} Record;

void allocateAndInitialize(long *offsets, int num_records, int **keys, Record ***records) {

    srand((unsigned int) time(NULL)); // initialize random seed

    // allocate memory for offsets and keys
    *offsets = (long*)malloc(num_records * sizeof(long));
    if (*offsets == NULL) exit(-1); // handle memory allocation failure

    *keys = malloc(num_records * sizeof(int));
    if (*keys == NULL) exit(-1); // handle memory allocation failure

    for (int i = 0; i < num_records; ++i) {
        (*offsets)[i] = rand(); // generate random offset value
        (*keys)[i] = rand();  // generate random key within range
    }

    *records = malloc(num_records * sizeof(Record*));
    if (*records == NULL) exit(-1); // handle memory allocation failure

    for (int i = 0; i < num_records; ++i) {
        (*records)[i] = malloc(sizeof(Record));

        if ((*records)[i] == NULL) exit(-1); // handle memory allocation failure
        (*records)[i]->value = rand(); // generate random value within range
    }
}
```

Note: 
