['Here is a simple implementation of the problem described using the QuickSort algorithm for sorting records based on their 'int' values in ascending order. The code handles potential allocation failures gracefully, freeing all allocated memory before returning when an error occurs. It also ensures the data consistency between arrays and reads records from an external source (a file in this case). 

```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    long offset;
} Offset;

typedef struct {
    int key;
} Key;

typedef struct {
    int value;
    time_t creationTime;
    time_t lastAccessedTime;
} Metadata;

typedef struct {
    int* pValue;
    Offset offset;
    Metadata metadata;
} Record;

int readRecordsFromFile(Record** records, Key* keys, int recordCount) {
    FILE *file = fopen("records.txt", "r");
    if (file == NULL) return 1; // Error opening file

    for (int i = 0; i < recordCount; ++i) {
        fscanf(file, "%ld %d %d", &(*records)[i].offset.offset, &keys[i].key, &(*records)[i].pValue);

        // Initialize metadata with default values
        (*records)[i].metadata.creationTime = time(NULL);
        (*records)[i].metadata.lastAccessedTime = time(NULL);
    }

    fclose(file);
    return 0; // No errors reading file
}

int compareRecords(const void *a, const void *b) {
    Record *recordA = (Record *) a;
    Record *recordB = (Record *) b;
    return (*recordA->pValue - *recordB->pValue);
}

void sortRecords(Record* records, int recordCount) {
    qsort(records, recordCount, sizeof(Record), compareRecords);
}

int handleAllocations(Offset** offsets, Key** keys, Record*** records, int recordCount) {
    *offsets = malloc(sizeof(Offset) * recordCount);
    if (*offsets == NULL) return 1; // Error allocating memory for offsets

    *keys = malloc(sizeof(Key) * recordCount);
    if (*keys == NULL) {
        free(*offsets);
        return 2; // Error allocating memory for keys
    }

    *records = malloc(sizeof(Record) * recordCount);
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        return 3; // Error allocating memory for records
    }

    return 0; // No errors allocating memory
}

int processRecords(Record** records, int* recordCount) {
    Key* keys = NULL;
    Offset* offsets = NULL;
    int errorCode = 0;

    *recordCount = 1000;  // example value, you can replace it with actual size of your data source
    errorCode = handleAllocations(&offsets, &keys, records, *recordCount);

    if (errorCode != 0) return errorCode;

    // Assuming data consistency between arrays. You may need additional checks for your use case
    errorCode = readRecordsFromFile(records, keys, *recordCount);

    free(offsets);
    free(keys);

    if (errorCode != 0) return errorCode;

    sortRecords(*records, *recordCount);

    return 0; // No errors processing records
}
```

This code should be used as a starting point and adjusted based on the specific requirements of your use case. The QuickSort algorithm is chosen here due to its average time complexity of O(n log n) which makes it suitable for large datasets, however other sorting algorithms like Merge Sort or Heap Sort could also be considered depending on the specific use case and data access patterns.
']

