    if (maxCount <= 0 || minValue > maxValue || rec == NULL) {
        fprintf(logFile, "Invalid input parameters.\n");
        return EINVAL;
    }

    srand(time(NULL));  // Initialize random seed
    *rec = calloc(maxCount, sizeof(record));
