['Here is a C implementation of your problem. Please note that the code uses POSIX threads to support multithreading, and assumes a UNIX-like environment. Also, please be aware this is a complex problem which requires careful design and consideration of various trade-offs and potential edge cases.

```c
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <sys/types.h>

typedef struct {
    time_t creationTime;
    time_t lastAccessedTime;
} Metadata;

typedef struct {
    int value;
    long *offset;
    Metadata metadata;
} Record;

typedef struct {
    size_t recordCount;
    Record *records;
} AllocationResult;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

Metadata initializeMetadata() {
    Metadata metadata;
    metadata.creationTime = time(NULL);
    metadata.lastAccessedTime = time(NULL);
    return metadata;
}

Record* allocateRecords(long *offsets, int *keys, size_t recordCount) {
    Record* records = malloc(sizeof(Record) * recordCount);
    for (size_t i = 0; i < recordCount; ++i) {
        records[i].value = keys[i];
        records[i].offset = &offsets[i];
        records[i].metadata = initializeMetadata();
    }
    return records;
}

AllocationResult allocateAndInitializeRecords(long *offsets, int *keys, size_t recordCount) {
    AllocationResult result;

    pthread_mutex_lock(&lock);

    Record* records = allocateRecords(offsets, keys, recordCount);
    if (records == NULL) {
        result.recordCount = 0;
    } else {
        result.recordCount = recordCount;
        result.records = records;
    }

    pthread_mutex_unlock(&lock);

    return result;
}
```
In this code, we use a mutex to ensure that only one thread can access the allocation function at a time and avoid data races. The function `allocateRecords` allocates memory for an array of records and initializes each record with its corresponding offset value from the first array and default metadata values. If any allocation fails, it returns 0 as the count of successfully created records. After allocating memory, it updates the count in the result structure to reflect the actual number of records that were successfully created.
