char *renderFooterScripts(const ScriptObject scripts[], size_t numOfScripts, unsigned int range) {
    char *html = NULL;
    size_t htmlLen = 0;
    size_t recordsCount = 0;
    long *offsetValues = malloc(numOfScripts * sizeof(*offsetValues));
    if (!offsetValues) goto cleanup;

    int *keys = malloc(numOfScripts * sizeof(*keys));
    if (!keys) goto cleanup;

    Record *records = calloc(MAX_RECORDS, sizeof(*records));
    if (!records) goto cleanup;

    srand((unsigned int)time(NULL)); // seed the random generator
    for (size_t i = 0; i < numOfScripts && recordsCount < MAX_RECORDS; ++i) {
        Record *record = &records[recordsCount];
        record->key = rand() % range;
        offsetValues[i] = strlen(scripts[i].code);
        record->offsetValue = offsetValues[i];
        ++recordsCount;
    }

    size_t totalLen = 0;
    for (size_t i = 0; i < recordsCount; ++i) {
        Record *record = &records[i];
        Metadata metadata = {time(NULL), time(NULL)};
        record->metadata = malloc(sizeof(*record->metadata));
        if (!record->metadata) goto cleanup;
        memcpy(record->metadata, &metadata, sizeof(*record->metadata));

        totalLen += snprintf(NULL, 0, "<script key='%d'>%s</script>", record->key, scripts[i].code);
    }

    html = malloc(totalLen + 1);
    if (!html) goto cleanup;

    for (size_t i = 0; i < recordsCount; ++i) {
        Record *record = &records[i];
        htmlLen += snprintf(&html[htmlLen], totalLen - htmlLen, "<script key='%d'>%s</script>", record->key, scripts[i].code);
    }

cleanup:
    for (size_t i = 0; i < recordsCount; ++i) {
        if(records[i].metadata) free(records[i].metadata);
    }
    if(records) free(records);
    if(keys) free(keys);
    if(offsetValues) free(offsetValues);

    return html;
}
