#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <jansson.h>  // JSON parsing library

typedef struct {
    int value;
    long *offset;
} record;

// Returns 0 on success, -1 otherwise
int create_records(long *initialOffsets, size_t numOffsets, int *initialKeys, size_t numKeys, char* jsonRecords, size_t limitBytes, int **keysOut, long ***offsetsOut, record ***recordsOut) {
    // Allocate memory for keys array and copy data from initialKeys
    *keysOut = malloc(numKeys * sizeof(int));
    if (*keysOut == NULL) return -1;  // Error handling
    memcpy(*keysOut, initialKeys, numKeys * sizeof(int));

    // Allocate memory for offsets array and copy data from initialOffsets
    *offsetsOut = malloc(numOffsets * sizeof(long));
    if (*offsetsOut == NULL) {  // Error handling
        free(*keysOut);
        return -1;
    }
    memcpy(*offsetsOut, initialOffsets, numOffsets * sizeof(long));

    json_error_t error;
    json_t* root = json_loads(jsonRecords, 0, &error);
    if(!root) {
        // Log the error to logging system
        printf("JSON parsing failed: %s\n", error.text);

        free(*keysOut);
        free(*offsetsOut);

        return -1;  // Error handling
    }

    if(!json_is_array(root)) {
        printf("JSON is not an array of records\n");

        json_decref(root);
        free(*keysOut);
        free(*offsetsOut);

        return -1;  // Error handling
    }

    size_t numRecords = json_array_size(root);

    *recordsOut = malloc(numRecords * sizeof(record));
    if (*recordsOut == NULL) {  // Error handling
        json_decref(root);
        free(*keysOut);
        free(*offsetsOut);

        return -1;
    }

    size_t i, j;
    for (i = 0, j = 0; i < numRecords && j < limitBytes; ++i) {
        json_t* record = json_array_get(root, i);

        if(!json_is_integer(record)) {
            printf("Record is not an integer\n");

            json_decref(root);
            free(*keysOut);
            free(*offsetsOut);
            free(*recordsOut);

            return -1;  // Error handling
        }

        (*recordsOut)[i].value = (int)json_integer_value(record);
        (*recordsOut)[i].offset = &((*offsetsOut)[j++ % numOffsets]);
    }

    size_t createdRecordsCount = i;

    json_decref(root);  // Decrement the reference count

    return createdRecordsCount;
}
```

This function uses a JSON parsing library to parse the input records, and checks each record to ensure it's an integer. It then initializes the 'record' structure for each valid record with an offset value from the allocated array of offsets. The total number of successfully created records is returned as part of the function's output.
