#ifndef CRC_H
#define CRC_H

#include <cstddef>
#include <string>

namespace CRC {
    unsigned int Calculate(const std::string &data, const size_t len);
} // namespace CRC

#endif /* CRC_H */

//src/main.cpp
#include "base64.hpp"
#include "crc.hpp"
#include <fstream>
#include <iostream>

int main(void) {
    std::string data;
    char buf[1024];

    // Load the binary file
    std::ifstream ifs("test.bin", std::ios::binary);
    while (ifs.read(buf, sizeof(buf)) || ifs.gcount()) {
        data += std::string(buf, buf + ifs.gcount());
    }
    ifs.close();

    // Calculate CRC and base64 encode it
    unsigned int crc = CRC::Calculate((unsigned char *)data.c_str(), data.size());
    std::string encodedCRC = Base64::Encode(reinterpret_cast<const unsigned char *>(&crc), sizeof(crc));

    // Save the encoded CRC to file
    std::ofstream ofs("output.txt");
    ofs << encodedCRC;
    ofs.close();

    return 0;
}

