["Your request is quite extensive and covers several aspects which would make this response unfeasibly long. However, I will provide a simplified version of what you asked for - writing a C function that dynamically allocates memory for three arrays. Then, we sort the records based on their int values in ascending order before returning them.

Please note that creating a complete system like this would involve much more than just one function, but hopefully, this can give you an idea of how to approach it.

```c
#include <stdlib.h>
#include <time.h>
#include <string.h>

typedef struct record {
    int value;
    long* offset_value;
} Record;

int allocateAndInit(long** offsets, int** keys, Record*** records, int num) {
    srand(time(NULL)); // initialize random seed

    *offsets = (long*) malloc(num * sizeof(long));
    if (*offsets == NULL) return -1;

    *keys = (int*) malloc(num * sizeof(int));
    if (*keys == NULL) {
        free(*offsets);
        return -1;
    }

    *records = (Record**) malloc(num * sizeof(Record*));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        return -1;
    }

    for (int i = 0; i < num; i++) {
        (*keys)[i] = rand(); // set a random value for each key
        Record* record = malloc(sizeof(Record));

        if (record == NULL) {
            free(*offsets);
            free(*keys);
            for (int j = 0; j < i; j++)
                free((*records)[j]);

            return -1;
        }

        record->value = (*keys)[i];
        record->offset_value = &(*offsets)[i];

        (*records)[i] = record;
    }

    qsort(*records, num, sizeof(Record*), compareRecords); // sort records based on their value

    return 0;
}

int compareRecords (const void * a, const void * b) {
   Record* recordA = *(Record**)a;
   Record* recordB = *(Record**)b;

   return (recordA->value - recordB->value);
}
```
This code first allocates and initializes the three arrays: one for 'long' offset values, one for 'int' keys, and an array of 'record' structures. Each record contains a single 'int' value and a pointer to the corresponding offset value from the first array. Then it sorts these records based on their int values in ascending order using qsort().
"]

