```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

typedef struct {
    int key;
    float value;
    char *data;
} dataRecord;

void initializeDataRecords(dataRecord ***records, long numRecords) {
    *records = (dataRecord **)calloc(numRecords, sizeof(dataRecord*));
    if (*records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records.\n");
        exit(1);
    }
}

void readFileIntoRecords(dataRecord ***records, const char *filename, long offset) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", filename);
        return;
    }

    dataRecord *record = malloc(sizeof(dataRecord));
    while (fscanf(file, "%d %f %m[^\n]", &record->key, &record->value, &record->data) == 3) {
        (*records)[offset++] = record;
        record = malloc(sizeof(dataRecord));
    }

    free(record);  // Free the last unused record
    fclose(file);
}

int compareRecords(const void *a, const void *b) {
    dataRecord *recordA = *(dataRecord **)a;
    dataRecord *recordB = *(dataRecord **)b;
    return (recordA->key - recordB->key);
}

void sortDataRecords(dataRecord ***records, long numRecords) {
    qsort(*records, numRecords, sizeof(dataRecord*), compareRecords);
}

void freeDataRecords(dataRecord ***records, long numRecords) {
    for (long i = 0; i < numRecords; ++i) {
        dataRecord *record = (*records)[i];
        if (record != NULL) {
            free(record->data);  // Free the string
            free(record);  // Free each record
        }
    }
    free(*records);  // Free the array of pointers
}
```
