void update_metadata(record_t *record){
    pthread_mutex_lock(&record->lock);
    record->meta.accessed = time(NULL);
    record->meta.access_count++;
    fprintf(logfile, "Access: %d", record->value);
    pthread_mutex_unlock(&record->lock);
}

int search_key(int key){
    if (keys[key] >= 0 && keys[key] < MAX_RECORDS) {
        update_metadata(records[keys[key]]);
        return 1;
    } else {
        return 0;
    }
}

int create_record(){
    pthread_mutex_lock(&record_lock);
    static int record_index = 0;
    if(record_index >= MAX_RECORDS){
