Here is an example of how one might approach solving the problem at hand:
```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#define INIT_CAPACITY 10

typedef struct Record {
    int value;
} Record;

typedef struct ArrayManager {
    pthread_mutex_t lock; // for concurrent access
    long* offsets;
    int* keys;
    Record** records;
    size_t capacity;
    size_t length;
} ArrayManager;

void initArrayManager(ArrayManager *arrayManager) {
    arrayManager->capacity = INIT_CAPACITY;
    arrayManager->length = 0;
    arrayManager->offsets = malloc(sizeof(long) * arrayManager->capacity);
    arrayManager->keys = malloc(sizeof(int) * arrayManager->capacity);
    arrayManager->records = malloc(sizeof(Record*) * arrayManager->capacity);
    if (arrayManager->offsets == NULL || arrayManager->keys == NULL || arrayManager->records == NULL){
        printf("Memory allocation failed. Exiting.\n");
        exit(-1);
    }

    pthread_mutex_init(&(arrayManager->lock), NULL);
}

void addRecord(ArrayManager *arrayManager, long offset, int key, Record* record) {
    pthread_mutex_lock(&(arrayManager->lock));

    if (arrayManager->length >= arrayManager->capacity) {
        // reallocate memory when the capacity is exceeded
        arrayManager->offsets = realloc(arrayManager->offsets, sizeof(long) * 2 * arrayManager->capacity);
        arrayManager->keys = realloc(arrayManager->keys, sizeof(int) * 2 * arrayManager->capacity);
        arrayManager->records = realloc(arrayManager->records, sizeof(Record*) * 2 * arrayManager->capacity);

        if (arrayManager->offsets == NULL || arrayManager->keys == NULL || arrayManager->records == NULL){
            printf("Memory allocation failed. Exiting.\n");
            exit(-1);
        }

        arrayManager->capacity *= 2; // update capacity
    }

    // add record
    arrayManager->offsets[arrayManager->length] = offset;
    arrayManager->keys[arrayManager->length] = key;
    arrayManager->records[arrayManager->length] = record;
    (arrayManager->length)++; // update length

    pthread_mutex_unlock(&(arrayManager->lock));
}
```
This code manages dynamic memory allocation for arrays of 'long' offset values, 'int' keys, and 'record' structures. It includes mechanisms to resize the arrays and record structures when the initial capacity is exceeded. The function handles memory allocation failures gracefully and implements a mechanism for concurrent access from multiple threads through the use of mutex locks. 

