void sortRecords(network_record* records, int numOfRecords) {
    // Use bubble sort algorithm for simplicity and efficiency
    for (int i = 0; i < numOfRecords - 1; ++i) {
        for (int j = 0; j < numOfRecords - i - 1; ++j) {
            if(records[j].timestamp > records[j+1].timestamp) { // Swap if current record's timestamp is greater than the next one
                network_record temp = records[j];
                records[j] = records[j+1];
                records[j+1] = temp;
            }
        }
    }
}

