For sorting the record arrays based on their int values, you could use a quicksort algorithm and then update the pointers in your records array. This is just a very simple example:

```c
int partition(Record *records, int low, int high) {
    int pivot = records[high].value; 
    int i = (low - 1);

    for (int j = low; j <= high- 1; j++) { 
        if (records[j].value < pivot) { 
            i++;
            Record temp = records[i];
            records[i] = records[j];
            records[j] = temp;
        } 
    }
    Record temp = records[i+1];
    records[i+1] = records[high];
    records[high] = temp;

    return (i + 1);
}

void quickSort(Record *records, int low, int high) { 
    if (low < high) { 
        int pi = partition(records, low, high); 

        quickSort(records, low, pi - 1); 
        quickSort(records, pi + 1, high); 
    } 
}
```
